CREATE OR REPLACE FUNCTION public.submit_free_agent_offer(p_negotiation_id uuid, p_offer_salary_weekly integer, p_offer_duration_seasons integer, p_offer_signing_bonus integer, p_offer_agent_fee integer)
 RETURNS TABLE(negotiation_id uuid, status text, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_negotiation public.rider_free_agent_negotiations%rowtype;
  v_game_date date;

  v_market_value integer := 0;
  v_min_signing_bonus integer := 0;
  v_min_agent_fee integer := 0;
  v_preferred_duration integer := 1;
  v_next_attempt_count integer := 0;

  v_eval record;

  v_new_status text;
  v_closed_reason text := null;
  v_locked_until timestamptz := null;
  v_message text := '';
begin
  if p_negotiation_id is null then
    raise exception 'Negotiation id is required';
  end if;

  if p_offer_salary_weekly is null or p_offer_salary_weekly <= 0 then
    raise exception 'Weekly salary must be greater than 0';
  end if;

  if p_offer_duration_seasons is null or p_offer_duration_seasons <= 0 then
    raise exception 'Contract duration must be at least 1 season';
  end if;

  if p_offer_duration_seasons > 5 then
    raise exception 'Contract duration cannot exceed 5 seasons';
  end if;

  if p_offer_signing_bonus is null or p_offer_signing_bonus < 0 then
    raise exception 'Signing bonus must be 0 or greater';
  end if;

  if p_offer_agent_fee is null or p_offer_agent_fee < 0 then
    raise exception 'Agent fee must be 0 or greater';
  end if;

  select n.*
  into v_negotiation
  from public.rider_free_agent_negotiations n
  where n.id = p_negotiation_id
  for update;

  if not found then
    raise exception 'Negotiation not found';
  end if;

  if lower(coalesce(v_negotiation.status, '')) in (
    'accepted',
    'declined',
    'rejected',
    'expired',
    'completed',
    'withdrawn'
  ) then
    return query
    select
      v_negotiation.id,
      coalesce(v_negotiation.status, 'closed'),
      'This negotiation is already closed.';
    return;
  end if;

  v_game_date := public.get_current_game_date_date();
  if v_game_date is null then
    raise exception 'Game date is not available';
  end if;

  if v_negotiation.expires_on_game_date is not null
     and v_negotiation.expires_on_game_date < v_game_date then
    update public.rider_free_agent_negotiations
    set
      status = 'expired',
      closed_reason = 'negotiation_expired',
      updated_at = now()
    where id = v_negotiation.id;

    return query
    select
      v_negotiation.id,
      'expired',
      'Negotiation expired before agreement was reached.';
    return;
  end if;

  select coalesce(round(r.market_value)::integer, 0)
  into v_market_value
  from public.riders r
  where r.id = v_negotiation.rider_id;

  v_min_signing_bonus := floor(greatest(v_market_value, 0) * 0.10);
  v_min_agent_fee := floor(greatest(v_market_value, 0) * 0.15);
  v_preferred_duration := greatest(coalesce(v_negotiation.preferred_duration_seasons, 1), 1);

  if p_offer_signing_bonus < v_min_signing_bonus then
    raise exception
      'Signing bonus cannot be below the minimum of %',
      concat('$', to_char(v_min_signing_bonus, 'FM999,999,999,990'));
  end if;

  if p_offer_agent_fee < v_min_agent_fee then
    raise exception
      'Agent fee cannot be below the minimum of %',
      concat('$', to_char(v_min_agent_fee, 'FM999,999,999,990'));
  end if;

  v_next_attempt_count := coalesce(v_negotiation.attempt_count, 0) + 1;

  update public.rider_free_agent_negotiations
  set
    offer_salary_weekly = p_offer_salary_weekly,
    offer_duration_seasons = p_offer_duration_seasons,
    offer_signing_bonus = p_offer_signing_bonus,
    offer_agent_fee = p_offer_agent_fee,
    attempt_count = v_next_attempt_count,
    updated_at = now()
  where id = v_negotiation.id;

  select *
  into v_eval
  from public._evaluate_free_agent_offer_package(
    v_negotiation.free_agent_id,
    v_negotiation.club_id,
    p_offer_salary_weekly,
    p_offer_duration_seasons,
    p_offer_signing_bonus,
    p_offer_agent_fee
  )
  limit 1;

  if p_offer_salary_weekly < coalesce(v_negotiation.min_acceptable_salary_weekly, 0) then
    v_new_status := 'countered';
    v_closed_reason := 'salary_too_low';
    v_locked_until := now() + interval '12 hours';
    v_message := 'The rider wants a higher weekly salary.';
  elsif p_offer_duration_seasons < greatest(v_preferred_duration - 1, 1) then
    v_new_status := 'countered';
    v_closed_reason := 'contract_too_short';
    v_locked_until := now() + interval '12 hours';
    v_message := 'The rider wants a longer contract.';
  elsif p_offer_duration_seasons > v_preferred_duration + 2 then
    v_new_status := 'countered';
    v_closed_reason := 'contract_too_long';
    v_locked_until := now() + interval '12 hours';
    v_message := 'The rider is not comfortable with such a long contract.';
  elsif coalesce(v_eval.predicted_outcome, 'counter') = 'accept' then
    v_new_status := 'open';
    v_closed_reason := null;
    v_locked_until := null;
    v_message := 'This package looks acceptable. Signing can proceed.';
  elsif coalesce(v_negotiation.max_attempts, 0) > 0
        and v_next_attempt_count >= v_negotiation.max_attempts
        and coalesce(v_eval.predicted_outcome, 'counter') = 'decline' then
    v_new_status := 'declined';
    v_closed_reason := coalesce(v_eval.primary_reason, 'salary_or_duration_not_competitive');
    v_locked_until := null;
    v_message := 'The rider has ended the negotiation.';
  else
    v_new_status := 'countered';
    v_closed_reason := coalesce(v_eval.primary_reason, 'salary_or_duration_not_competitive');
    v_locked_until := now() + interval '12 hours';
    v_message := coalesce(v_eval.summary_text, 'The rider wants a stronger overall package.');
  end if;

  update public.rider_free_agent_negotiations
  set
    status = v_new_status,
    closed_reason = v_closed_reason,
    locked_until = v_locked_until,
    notes_json = coalesce(notes_json, '{}'::jsonb) || jsonb_build_object(
      'last_preview_total_score', v_eval.total_score,
      'last_preview_acceptance_percent', v_eval.acceptance_percent,
      'last_preview_acceptance_band', v_eval.acceptance_band,
      'last_preview_predicted_outcome', v_eval.predicted_outcome,
      'last_preview_primary_reason', v_eval.primary_reason,
      'last_preview_reasons', v_eval.reasons,
      'last_preview_hard_block', v_eval.hard_block
    ),
    updated_at = now()
  where id = v_negotiation.id;

  return query
  select
    v_negotiation.id,
    v_new_status,
    v_message;
end;
$function$
;

CREATE OR REPLACE FUNCTION public._complete_free_agent_signing_internal(p_negotiation_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_auth_uid uuid := auth.uid();
  v_result record;
begin
  /*
    User flow:
    - use the normal user signing function, because it enforces ownership
      and uses the authenticated club context.

    Internal / AI / admin flow:
    - use the admin helper because auth.uid() may be null.
  */
  if v_auth_uid is not null then
    select *
    into v_result
    from public.sign_free_agent_from_negotiation(p_negotiation_id)
    limit 1;
  else
    select *
    into v_result
    from public.admin_sign_free_agent_from_negotiation(
      p_negotiation_id,
      p_actor_user_id
    )
    limit 1;
  end if;

  if v_result.contract_id is null then
    raise exception 'Free-agent signing finalizer did not create a contract.';
  end if;

  return jsonb_build_object(
    'status', 'completed',
    'message', 'Free-agent signing completed successfully.',
    'negotiation_id', p_negotiation_id,
    'free_agent_id', v_result.free_agent_id,
    'rider_id', v_result.rider_id,
    'club_id', v_result.club_id,
    'contract_id', v_result.contract_id,
    'salary_weekly', v_result.salary_weekly,
    'duration_seasons', v_result.duration_seasons,
    'starts_on', v_result.starts_on,
    'expires_on', v_result.expires_on,
    'start_season_number', v_result.start_season_number,
    'end_season_number', v_result.end_season_number
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_rider_free_agent_contract_offer(p_negotiation_id uuid, p_offer_salary_weekly integer, p_offer_duration_seasons integer, p_offer_signing_bonus integer, p_offer_agent_fee integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare
  v_uid uuid := auth.uid();
  v_status_after text;
  v_locked_until_after timestamptz;
  v_can_sign boolean := false;
  v_sign_result jsonb;
begin
  if v_uid is null then
    raise exception 'Not authenticated'
      using errcode = 'P0001';
  end if;

  if not exists (
    select 1
    from public.rider_free_agent_negotiations n
    join public.clubs c
      on c.id = n.club_id
    where n.id = p_negotiation_id
      and c.owner_user_id = v_uid
      and c.deleted_at is null
  ) then
    raise exception 'Free-agent negotiation not found or access denied.'
      using errcode = 'P0001';
  end if;

  if lower(coalesce((
    select n.status
    from public.rider_free_agent_negotiations n
    where n.id = p_negotiation_id
    limit 1
  ), '')) <> 'open' then
    raise exception 'Only open free-agent negotiations can receive a contract offer.'
      using errcode = 'P0001';
  end if;

  perform *
  from public.submit_free_agent_offer(
    p_negotiation_id,
    p_offer_salary_weekly,
    p_offer_duration_seasons,
    p_offer_signing_bonus,
    p_offer_agent_fee
  );

  select
    n.status,
    n.locked_until,
    (
      coalesce(n.offer_salary_weekly, 0) >= coalesce(n.min_acceptable_salary_weekly, 0)
      and coalesce(n.offer_duration_seasons, 0) >= 1
      and n.status = 'open'
    )
  into
    v_status_after,
    v_locked_until_after,
    v_can_sign
  from public.rider_free_agent_negotiations n
  where n.id = p_negotiation_id
  limit 1;

  if lower(coalesce(v_status_after, '')) in ('rejected', 'declined') then
    return jsonb_build_object(
      'negotiation_id', p_negotiation_id,
      'status', 'declined',
      'message', 'Rider refused the contract terms.'
    );
  end if;

  if lower(coalesce(v_status_after, '')) = 'expired' then
    return jsonb_build_object(
      'negotiation_id', p_negotiation_id,
      'status', 'expired',
      'message', 'Negotiation expired before agreement.'
    );
  end if;

  if coalesce(v_can_sign, false) = true then
    v_sign_result := public._complete_free_agent_signing_internal(
      p_negotiation_id,
      v_uid
    );

    return coalesce(
      v_sign_result,
      jsonb_build_object(
        'negotiation_id', p_negotiation_id,
        'status', 'completed',
        'message', 'Free-agent signing completed successfully.'
      )
    );
  end if;

  return jsonb_build_object(
    'negotiation_id', p_negotiation_id,
    'status', coalesce(v_status_after, 'open'),
    'message',
      case
        when v_locked_until_after is not null and v_locked_until_after > now()
          then 'Rider was not satisfied with the latest offer and temporarily paused negotiations.'
        else 'Rider has not accepted yet. Improve salary, contract length, signing bonus and/or agent fee.'
      end,
    'locked_until', v_locked_until_after
  );
end;$function$
;

CREATE OR REPLACE FUNCTION public.staff_name_country_fallbacks(p_country_code text)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_code text := upper(coalesce(trim(p_country_code), ''));
begin
  if v_code in ('RS', 'HR', 'BA', 'ME') then
    return array[v_code, 'RS', 'HR', 'BA', 'ME'];
  elsif v_code = 'SI' then
    return array['SI', 'HR', 'RS'];
  elsif v_code in ('MK', 'BG') then
    return array[v_code, 'BG', 'MK', 'RS'];
  elsif v_code in ('IT', 'SM') then
    return array[v_code, 'IT', 'SM'];
  elsif v_code in ('ES', 'AD', 'PT') then
    return array[v_code, 'ES', 'AD', 'PT'];
  elsif v_code in ('FR', 'BE', 'CH', 'LU') then
    return array[v_code, 'FR', 'BE', 'CH', 'LU'];
  elsif v_code in ('DE', 'AT') then
    return array[v_code, 'DE', 'AT', 'CH'];
  elsif v_code in ('NL', 'BE') then
    return array[v_code, 'NL', 'BE'];
  elsif v_code <> '' then
    return array[v_code];
  else
    return array['RS'];
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.pick_staff_first_name(p_country_code text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_fallbacks text[];
  v_name text;
begin
  v_fallbacks := public.staff_name_country_fallbacks(p_country_code);

  select fn.first_name
  into v_name
  from public.first_names_master fn
  where upper(fn.country_code) = any(v_fallbacks)
  order by array_position(v_fallbacks, upper(fn.country_code)), random()
  limit 1;

  if v_name is null then
    select fn.first_name
    into v_name
    from public.first_names_master fn
    order by random()
    limit 1;
  end if;

  return coalesce(v_name, 'Aleksandar');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.pick_staff_last_name(p_country_code text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_fallbacks text[];
  v_name text;
begin
  v_fallbacks := public.staff_name_country_fallbacks(p_country_code);

  select ln.last_name
  into v_name
  from public.last_names_master ln
  where upper(ln.country_code) = any(v_fallbacks)
  order by array_position(v_fallbacks, upper(ln.country_code)), random()
  limit 1;

  if v_name is null then
    select ln.last_name
    into v_name
    from public.last_names_master ln
    order by random()
    limit 1;
  end if;

  return coalesce(v_name, 'Petrovic');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_staff_identity_fields()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.country_code := upper(nullif(trim(new.country_code), ''));

  if nullif(trim(new.first_name), '') is not null
     and nullif(trim(new.last_name), '') is not null then
    new.first_name := regexp_replace(trim(new.first_name), '\s+', ' ', 'g');
    new.last_name := regexp_replace(trim(new.last_name), '\s+', ' ', 'g');
    new.staff_name := trim(new.first_name || ' ' || new.last_name);
    return new;
  end if;

  if nullif(trim(new.staff_name), '') is not null then
    new.staff_name := regexp_replace(trim(new.staff_name), '\s+', ' ', 'g');

    -- Only auto-split already proper full names.
    -- Initial-style names are handled by the backfill updates below.
    if new.staff_name !~ '^[A-Z]\.\s+' and position(' ' in new.staff_name) > 0 then
      if nullif(trim(new.first_name), '') is null then
        new.first_name := split_part(new.staff_name, ' ', 1);
      end if;

      if nullif(trim(new.last_name), '') is null then
        new.last_name := regexp_replace(new.staff_name, '^\S+\s+', '');
      end if;
    end if;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_staff_identity(p_country_code text)
 RETURNS TABLE(first_name text, last_name text, staff_name text, country_code text)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_country_code text := upper(coalesce(trim(p_country_code), 'RS'));
  v_first_name text;
  v_last_name text;
begin
  v_first_name := public.pick_staff_first_name(v_country_code);
  v_last_name := public.pick_staff_last_name(v_country_code);

  return query
  select
    v_first_name,
    v_last_name,
    trim(v_first_name || ' ' || v_last_name),
    v_country_code;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_skill_tier_label(p_value integer)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
  if p_value is null then
    return 'Unknown';
  elsif p_value < 30 then
    return 'Poor';
  elsif p_value < 45 then
    return 'Basic';
  elsif p_value < 60 then
    return 'Competent';
  elsif p_value < 75 then
    return 'Strong';
  elsif p_value < 90 then
    return 'Elite';
  else
    return 'World Class';
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_staff_role_skill_profile(p_role_type text, p_expertise integer, p_experience integer, p_potential integer, p_leadership integer, p_efficiency integer, p_loyalty integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_role text := coalesce(trim(lower(p_role_type)), '');
begin
  if v_role = 'head_coach' then
    return jsonb_build_object(
      'roleSkills', jsonb_build_array(
        jsonb_build_object('key', 'training_methodology', 'label', 'Training Methodology', 'value', p_expertise, 'tier', public.staff_skill_tier_label(p_expertise)),
        jsonb_build_object('key', 'recovery_planning', 'label', 'Recovery Planning', 'value', p_efficiency, 'tier', public.staff_skill_tier_label(p_efficiency)),
        jsonb_build_object('key', 'youth_development', 'label', 'Youth Development', 'value', p_potential, 'tier', public.staff_skill_tier_label(p_potential))
      ),
      'supportSkills', jsonb_build_array(
        jsonb_build_object('key', 'experience', 'label', 'Experience', 'value', p_experience, 'tier', public.staff_skill_tier_label(p_experience)),
        jsonb_build_object('key', 'leadership', 'label', 'Leadership', 'value', p_leadership, 'tier', public.staff_skill_tier_label(p_leadership)),
        jsonb_build_object('key', 'loyalty', 'label', 'Loyalty', 'value', p_loyalty, 'tier', public.staff_skill_tier_label(p_loyalty))
      )
    );
  elsif v_role = 'team_doctor' then
    return jsonb_build_object(
      'roleSkills', jsonb_build_array(
        jsonb_build_object('key', 'diagnosis', 'label', 'Diagnosis', 'value', p_expertise, 'tier', public.staff_skill_tier_label(p_expertise)),
        jsonb_build_object('key', 'rehabilitation', 'label', 'Rehabilitation', 'value', p_efficiency, 'tier', public.staff_skill_tier_label(p_efficiency)),
        jsonb_build_object('key', 'injury_prevention', 'label', 'Injury Prevention', 'value', p_experience, 'tier', public.staff_skill_tier_label(p_experience))
      ),
      'supportSkills', jsonb_build_array(
        jsonb_build_object('key', 'leadership', 'label', 'Leadership', 'value', p_leadership, 'tier', public.staff_skill_tier_label(p_leadership)),
        jsonb_build_object('key', 'potential', 'label', 'Potential', 'value', p_potential, 'tier', public.staff_skill_tier_label(p_potential)),
        jsonb_build_object('key', 'loyalty', 'label', 'Loyalty', 'value', p_loyalty, 'tier', public.staff_skill_tier_label(p_loyalty))
      )
    );
  elsif v_role = 'mechanic' then
    return jsonb_build_object(
      'roleSkills', jsonb_build_array(
        jsonb_build_object('key', 'bike_setup', 'label', 'Bike Setup', 'value', p_expertise, 'tier', public.staff_skill_tier_label(p_expertise)),
        jsonb_build_object('key', 'reliability', 'label', 'Reliability', 'value', p_efficiency, 'tier', public.staff_skill_tier_label(p_efficiency)),
        jsonb_build_object('key', 'technical_adaptation', 'label', 'Technical Adaptation', 'value', p_potential, 'tier', public.staff_skill_tier_label(p_potential))
      ),
      'supportSkills', jsonb_build_array(
        jsonb_build_object('key', 'experience', 'label', 'Experience', 'value', p_experience, 'tier', public.staff_skill_tier_label(p_experience)),
        jsonb_build_object('key', 'leadership', 'label', 'Leadership', 'value', p_leadership, 'tier', public.staff_skill_tier_label(p_leadership)),
        jsonb_build_object('key', 'loyalty', 'label', 'Loyalty', 'value', p_loyalty, 'tier', public.staff_skill_tier_label(p_loyalty))
      )
    );
  elsif v_role = 'sport_director' then
    return jsonb_build_object(
      'roleSkills', jsonb_build_array(
        jsonb_build_object('key', 'race_tactics', 'label', 'Race Tactics', 'value', p_expertise, 'tier', public.staff_skill_tier_label(p_expertise)),
        jsonb_build_object('key', 'motivation', 'label', 'Motivation', 'value', p_leadership, 'tier', public.staff_skill_tier_label(p_leadership)),
        jsonb_build_object('key', 'organization', 'label', 'Organization', 'value', p_efficiency, 'tier', public.staff_skill_tier_label(p_efficiency))
      ),
      'supportSkills', jsonb_build_array(
        jsonb_build_object('key', 'experience', 'label', 'Experience', 'value', p_experience, 'tier', public.staff_skill_tier_label(p_experience)),
        jsonb_build_object('key', 'potential', 'label', 'Potential', 'value', p_potential, 'tier', public.staff_skill_tier_label(p_potential)),
        jsonb_build_object('key', 'loyalty', 'label', 'Loyalty', 'value', p_loyalty, 'tier', public.staff_skill_tier_label(p_loyalty))
      )
    );
  elsif v_role = 'scout_analyst' then
    return jsonb_build_object(
      'roleSkills', jsonb_build_array(
        jsonb_build_object('key', 'talent_evaluation', 'label', 'Talent Evaluation', 'value', p_expertise, 'tier', public.staff_skill_tier_label(p_expertise)),
        jsonb_build_object('key', 'scouting_experience', 'label', 'Scouting Experience', 'value', p_experience, 'tier', public.staff_skill_tier_label(p_experience)),
        jsonb_build_object('key', 'data_analysis', 'label', 'Data Analysis', 'value', p_efficiency, 'tier', public.staff_skill_tier_label(p_efficiency))
      ),
      'supportSkills', jsonb_build_array(
        jsonb_build_object('key', 'leadership', 'label', 'Leadership', 'value', p_leadership, 'tier', public.staff_skill_tier_label(p_leadership)),
        jsonb_build_object('key', 'potential', 'label', 'Potential', 'value', p_potential, 'tier', public.staff_skill_tier_label(p_potential)),
        jsonb_build_object('key', 'loyalty', 'label', 'Loyalty', 'value', p_loyalty, 'tier', public.staff_skill_tier_label(p_loyalty))
      )
    );
  else
    return jsonb_build_object(
      'roleSkills', '[]'::jsonb,
      'supportSkills', '[]'::jsonb
    );
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_random_int(p_min integer, p_max integer)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
begin
  if p_min is null or p_max is null then
    raise exception 'staff_random_int requires non-null bounds';
  end if;

  if p_max < p_min then
    raise exception 'staff_random_int invalid range: % > %', p_min, p_max;
  end if;

  return floor(random() * (p_max - p_min + 1) + p_min)::integer;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_default_team_scope(p_role_type text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_role text := lower(coalesce(trim(p_role_type), ''));
begin
  if v_role = 'sport_director' then
    return 'first_team';
  else
    return 'all';
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_roll_quality_tier()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  v_roll numeric := random();
begin
  -- 25% low, 45% standard, 22% high, 8% elite
  if v_roll < 0.25 then
    return 'low';
  elsif v_roll < 0.70 then
    return 'standard';
  elsif v_roll < 0.92 then
    return 'high';
  else
    return 'elite';
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public._evaluate_free_agent_offer_package(p_free_agent_id uuid, p_club_id uuid, p_offer_salary_weekly integer, p_offer_duration_seasons integer, p_offer_signing_bonus integer, p_offer_agent_fee integer)
 RETURNS TABLE(total_score integer, acceptance_percent integer, acceptance_band text, predicted_outcome text, summary_text text, primary_reason text, salary_score integer, duration_score integer, bonus_score integer, fee_score integer, tier_score integer, tier_gap integer, desired_tier text, club_tier text, hard_block boolean, reasons jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rider_id uuid;
  v_expected_salary integer := 0;
  v_min_acceptable_salary integer := 0;
  v_preferred_duration smallint := 1;
  v_market_value integer := 0;
  v_desired_tier text := 'amateur';
  v_club_tier text := 'amateur';
  v_age integer := 30;

  v_desired_rank integer := 1;
  v_club_rank integer := 1;
  v_tier_gap integer := 0;

  v_salary_anchor integer := 1;
  v_min_signing_bonus integer := 0;
  v_min_agent_fee integer := 0;

  v_overall_value integer := 50;
  v_potential_value integer := 50;
  v_experience_value integer := 0;

  v_profile_modifier integer := 0;
  v_veteran_relief integer := 0;
  v_elite_lower_tier_block boolean := false;

  v_salary_score integer := 0;
  v_duration_score integer := 0;
  v_bonus_score integer := 0;
  v_fee_score integer := 0;
  v_tier_score integer := 0;
  v_total_score integer := 0;

  v_acceptance_percent integer := 0;
  v_acceptance_band text := 'very_low';
  v_predicted_outcome text := 'decline';
  v_summary_text text := '';
  v_primary_reason text := '';
  v_hard_block boolean := false;
  v_reasons jsonb := '[]'::jsonb;
begin
  if p_free_agent_id is null then
    raise exception 'Free agent id is required';
  end if;

  if p_club_id is null then
    raise exception 'Club id is required';
  end if;

  if p_offer_salary_weekly is null or p_offer_salary_weekly <= 0 then
    raise exception 'Offer salary must be greater than 0';
  end if;

  if p_offer_duration_seasons is null or p_offer_duration_seasons < 1 then
    raise exception 'Offer duration must be at least 1 season';
  end if;

  if p_offer_signing_bonus is null or p_offer_signing_bonus < 0 then
    raise exception 'Signing bonus must be 0 or greater';
  end if;

  if p_offer_agent_fee is null or p_offer_agent_fee < 0 then
    raise exception 'Agent fee must be 0 or greater';
  end if;

  select
    fa.rider_id,
    coalesce(fa.expected_salary_weekly, 0),
    coalesce(fa.min_acceptable_salary_weekly, 0),
    greatest(coalesce(fa.preferred_duration_seasons, 1), 1),
    coalesce(fa.desired_tier, 'amateur'),
    coalesce(round(r.market_value)::integer, 0),
    coalesce(public.get_age_years_on_game_date(r.birth_date), 30),
    coalesce(r.overall, 50),
    coalesce(r.potential, 50)
  into
    v_rider_id,
    v_expected_salary,
    v_min_acceptable_salary,
    v_preferred_duration,
    v_desired_tier,
    v_market_value,
    v_age,
    v_overall_value,
    v_potential_value
  from public.rider_free_agents fa
  join public.riders r
    on r.id = fa.rider_id
  where fa.id = p_free_agent_id
  limit 1;

  v_experience_value := greatest(0, least(100, ((v_age - 18) * 4)));

  if v_rider_id is null then
    raise exception 'Free agent not found';
  end if;

  select coalesce(c.club_tier::text, 'amateur')
  into v_club_tier
  from public.clubs c
  where c.id = p_club_id
  limit 1;

  if v_club_tier is null then
    raise exception 'Club not found';
  end if;

  v_desired_rank :=
    case lower(coalesce(v_desired_tier, 'amateur'))
      when 'worldteam' then 4
      when 'proteam' then 3
      when 'continental' then 2
      else 1
    end;

  v_club_rank :=
    case lower(coalesce(v_club_tier, 'amateur'))
      when 'worldteam' then 4
      when 'proteam' then 3
      when 'continental' then 2
      else 1
    end;

  v_tier_gap := v_desired_rank - v_club_rank;

  v_salary_anchor := greatest(v_expected_salary, v_min_acceptable_salary, 1);
  v_min_signing_bonus := floor(greatest(v_market_value, 0) * 0.10);
  v_min_agent_fee := floor(greatest(v_market_value, 0) * 0.15);

  v_salary_score := case
    when p_offer_salary_weekly < v_min_acceptable_salary then 18
    when p_offer_salary_weekly >= ceil(v_salary_anchor * 1.20) then 72
    when p_offer_salary_weekly >= ceil(v_salary_anchor * 1.10) then 66
    when p_offer_salary_weekly >= v_salary_anchor then 60
    when p_offer_salary_weekly >= ceil(v_salary_anchor * 0.95) then 48
    else 34
  end;

  v_duration_score := case
    when p_offer_duration_seasons = v_preferred_duration then 18
    when abs(p_offer_duration_seasons - v_preferred_duration) = 1 then 12
    when abs(p_offer_duration_seasons - v_preferred_duration) = 2 then 6
    else 0
  end;

  v_bonus_score := case
    when v_min_signing_bonus <= 0 then 0
    when p_offer_signing_bonus >= ceil(v_min_signing_bonus * 1.50) then 6
    when p_offer_signing_bonus >= ceil(v_min_signing_bonus * 1.25) then 4
    when p_offer_signing_bonus >= ceil(v_min_signing_bonus * 1.10) then 2
    else 0
  end;

  v_fee_score := case
    when v_min_agent_fee <= 0 then 0
    when p_offer_agent_fee >= ceil(v_min_agent_fee * 1.50) then 6
    when p_offer_agent_fee >= ceil(v_min_agent_fee * 1.25) then 4
    when p_offer_agent_fee >= ceil(v_min_agent_fee * 1.10) then 2
    else 0
  end;

  v_tier_score := case
    when v_tier_gap <= 0 then 10
    when v_tier_gap = 1 then -18
    when v_tier_gap = 2 then -34
    else -52
  end;

  if v_tier_gap > 0 then
    if v_overall_value >= 78 then
      v_profile_modifier := v_profile_modifier - 18;
      v_reasons := v_reasons || jsonb_build_array(
        'This rider is too strong for the current club tier unless the package is exceptional.'
      );
    elsif v_overall_value >= 72 then
      v_profile_modifier := v_profile_modifier - 12;
      v_reasons := v_reasons || jsonb_build_array(
        'The rider''s overall level makes lower-tier signing difficult.'
      );
    elsif v_overall_value >= 66 then
      v_profile_modifier := v_profile_modifier - 6;
    end if;

    if v_age <= 25 and v_potential_value >= 75 then
      v_profile_modifier := v_profile_modifier - 16;
      v_reasons := v_reasons || jsonb_build_array(
        'Young high-potential riders strongly prefer bigger competitive steps.'
      );
    elsif v_age <= 29 and v_potential_value >= 70 then
      v_profile_modifier := v_profile_modifier - 10;
      v_reasons := v_reasons || jsonb_build_array(
        'The rider still has strong upside, which makes lower-tier signing harder.'
      );
    elsif v_age <= 32 and v_potential_value >= 65 then
      v_profile_modifier := v_profile_modifier - 5;
    end if;

    if v_age between 27 and 32 and v_overall_value >= 70 then
      v_profile_modifier := v_profile_modifier - 8;
      v_reasons := v_reasons || jsonb_build_array(
        'Prime-age established riders are difficult to attract below their competitive level.'
      );
    end if;

    if v_age >= 33 and v_overall_value >= 70 then
      if p_offer_salary_weekly >= ceil(v_expected_salary * 1.08)
         and p_offer_signing_bonus >= ceil(v_min_signing_bonus * 1.10)
         and p_offer_agent_fee >= ceil(v_min_agent_fee * 1.10) then
        v_veteran_relief := 8;
        v_reasons := v_reasons || jsonb_build_array(
          'The rider is older, so a strong money package helps more than it would for a younger rider.'
        );
      else
        v_profile_modifier := v_profile_modifier - 4;
        v_reasons := v_reasons || jsonb_build_array(
          'The rider is older, but still expects a strong financial reason to drop tier.'
        );
      end if;
    end if;

    if v_tier_gap >= 2 and (
      (v_age <= 30 and v_overall_value >= 74)
      or (v_age <= 27 and v_potential_value >= 76)
    ) then
      v_elite_lower_tier_block := true;
      v_hard_block := true;
      v_profile_modifier := v_profile_modifier - 12;
      v_reasons := v_reasons || jsonb_build_array(
        'This is an elite lower-tier target. Signing is extremely difficult without an exceptional offer.'
      );
    end if;
  end if;

  if v_tier_gap > 0 then
    v_reasons := v_reasons || jsonb_build_array(
      'Club tier is below the rider''s preferred level.'
    );
  end if;

  if p_offer_salary_weekly < v_min_acceptable_salary then
    v_reasons := v_reasons || jsonb_build_array(
      'Weekly salary is below the rider''s minimum.'
    );
  elsif p_offer_salary_weekly < v_expected_salary then
    v_reasons := v_reasons || jsonb_build_array(
      'Weekly salary is above minimum, but still below expectation.'
    );
  else
    v_reasons := v_reasons || jsonb_build_array(
      'Weekly salary meets or exceeds the rider''s expectation.'
    );
  end if;

  if p_offer_duration_seasons = v_preferred_duration then
    v_reasons := v_reasons || jsonb_build_array(
      'Contract duration matches the rider''s preference.'
    );
  elsif p_offer_duration_seasons < v_preferred_duration then
    v_reasons := v_reasons || jsonb_build_array(
      'Contract duration is shorter than the rider prefers.'
    );
  else
    v_reasons := v_reasons || jsonb_build_array(
      'Contract duration is longer than the rider prefers.'
    );
  end if;

  if p_offer_signing_bonus >= ceil(greatest(v_min_signing_bonus, 1) * 1.10) then
    v_reasons := v_reasons || jsonb_build_array(
      'Signing bonus is helping the offer slightly.'
    );
  end if;

  if p_offer_agent_fee >= ceil(greatest(v_min_agent_fee, 1) * 1.10) then
    v_reasons := v_reasons || jsonb_build_array(
      'Agent fee is helping the offer slightly.'
    );
  end if;

  v_total_score := greatest(
    0,
    least(
      100,
      v_salary_score +
      v_duration_score +
      v_bonus_score +
      v_fee_score +
      v_tier_score +
      v_profile_modifier + v_veteran_relief + public.team_policy_contract_happiness_bonus_v1(p_club_id)
    )
  );

  v_acceptance_percent := greatest(2, least(95, v_total_score - 8));

  v_acceptance_band := case
    when v_acceptance_percent < 20 then 'very_low'
    when v_acceptance_percent < 40 then 'low'
    when v_acceptance_percent < 60 then 'moderate'
    when v_acceptance_percent < 80 then 'high'
    else 'very_high'
  end;

  if p_offer_salary_weekly < v_min_acceptable_salary then
    v_predicted_outcome := 'counter';
    v_primary_reason := 'salary_too_low';
    v_summary_text := 'The package is unlikely to be accepted because salary is below the rider''s minimum.';
  elsif p_offer_duration_seasons < greatest(v_preferred_duration - 1, 1) then
    v_predicted_outcome := 'counter';
    v_primary_reason := 'contract_too_short';
    v_summary_text := 'The rider is likely to push back because the contract is too short.';
  elsif p_offer_duration_seasons > v_preferred_duration + 2 then
    v_predicted_outcome := 'counter';
    v_primary_reason := 'contract_too_long';
    v_summary_text := 'The rider is likely to push back because the contract is too long.';
  elsif v_elite_lower_tier_block
    and (
      v_total_score < 92
      or p_offer_salary_weekly < ceil(v_expected_salary * 1.15)
      or p_offer_signing_bonus < ceil(v_min_signing_bonus * 1.20)
      or p_offer_agent_fee < ceil(v_min_agent_fee * 1.20)
    ) then
    v_predicted_outcome := 'decline';
    v_primary_reason := 'club_tier_too_low';
    v_summary_text := 'This rider is far above the club''s current level. Even a strong offer may not be enough.';
  elsif v_tier_gap > 0
    and (
      v_total_score < 84
      or p_offer_salary_weekly < ceil(v_expected_salary * 1.08)
    ) then
    v_predicted_outcome := 'counter';
    v_primary_reason := 'club_tier_too_low';
    v_summary_text := 'The offer is respectable, but the club tier fit is still working against you.';
  elsif v_total_score >= 84 then
    v_predicted_outcome := 'accept';
    v_primary_reason := 'strong_package';
    v_summary_text := 'This package looks strong and has a good chance of being accepted.';
  elsif v_total_score >= 58 then
    v_predicted_outcome := 'counter';
    v_primary_reason := 'package_not_strong_enough';
    v_summary_text := 'The rider will probably continue negotiating, but the package still needs improvement.';
  else
    v_predicted_outcome := 'decline';
    v_primary_reason := 'weak_package';
    v_summary_text := 'This package looks too weak and is likely to be rejected or heavily countered.';
  end if;

  return query
  select
    v_total_score,
    v_acceptance_percent,
    v_acceptance_band,
    v_predicted_outcome,
    v_summary_text,
    v_primary_reason,
    v_salary_score,
    v_duration_score,
    v_bonus_score,
    v_fee_score,
    v_tier_score,
    v_tier_gap,
    v_desired_tier,
    v_club_tier,
    v_hard_block,
    v_reasons;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.preview_rider_free_agent_offer(p_offer_salary_weekly integer, p_offer_duration_seasons integer, p_offer_signing_bonus integer, p_offer_agent_fee integer, p_free_agent_id uuid DEFAULT NULL::uuid, p_negotiation_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_club_id uuid;
  v_free_agent_id uuid;
  v_eval record;
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  v_club_id := public._get_owned_main_club_id(v_uid);
  if v_club_id is null then
    raise exception 'Main club not found';
  end if;

  if p_free_agent_id is null and p_negotiation_id is null then
    raise exception 'Either free_agent_id or negotiation_id is required';
  end if;

  if p_free_agent_id is not null then
    v_free_agent_id := p_free_agent_id;
  else
    select n.free_agent_id
    into v_free_agent_id
    from public.rider_free_agent_negotiations n
    where n.id = p_negotiation_id
      and n.club_id = v_club_id
    limit 1;
  end if;

  if v_free_agent_id is null then
    raise exception 'Free agent could not be resolved';
  end if;

  select *
  into v_eval
  from public._evaluate_free_agent_offer_package(
    v_free_agent_id,
    v_club_id,
    p_offer_salary_weekly,
    p_offer_duration_seasons,
    p_offer_signing_bonus,
    p_offer_agent_fee
  )
  limit 1;

  return jsonb_build_object(
    'acceptance_percent', v_eval.acceptance_percent,
    'acceptance_band', v_eval.acceptance_band,
    'predicted_outcome', v_eval.predicted_outcome,
    'summary_text', v_eval.summary_text,
    'primary_reason', v_eval.primary_reason,
    'salary_score', v_eval.salary_score,
    'duration_score', v_eval.duration_score,
    'bonus_score', v_eval.bonus_score,
    'fee_score', v_eval.fee_score,
    'tier_score', v_eval.tier_score,
    'tier_gap', v_eval.tier_gap,
    'desired_tier', v_eval.desired_tier,
    'club_tier', v_eval.club_tier,
    'hard_block', v_eval.hard_block,
    'reasons', v_eval.reasons
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_primary_specialization_label(p_role_type text, p_expertise integer, p_experience integer, p_potential integer, p_leadership integer, p_efficiency integer, p_loyalty integer)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_role text := lower(coalesce(trim(p_role_type), ''));
begin
  if v_role = 'head_coach' then
    if p_expertise >= p_efficiency and p_expertise >= p_potential then
      return 'Training Methodology';
    elsif p_efficiency >= p_expertise and p_efficiency >= p_potential then
      return 'Recovery Planning';
    else
      return 'Youth Development';
    end if;

  elsif v_role = 'team_doctor' then
    if p_expertise >= p_efficiency and p_expertise >= p_experience then
      return 'Diagnosis';
    elsif p_efficiency >= p_expertise and p_efficiency >= p_experience then
      return 'Rehabilitation';
    else
      return 'Injury Prevention';
    end if;

  elsif v_role = 'mechanic' then
    if p_expertise >= p_efficiency and p_expertise >= p_potential then
      return 'Bike Setup';
    elsif p_efficiency >= p_expertise and p_efficiency >= p_potential then
      return 'Reliability';
    else
      return 'Technical Adaptation';
    end if;

  elsif v_role = 'sport_director' then
    if p_expertise >= p_leadership and p_expertise >= p_efficiency then
      return 'Race Tactics';
    elsif p_leadership >= p_expertise and p_leadership >= p_efficiency then
      return 'Motivation';
    else
      return 'Organization';
    end if;

  elsif v_role = 'scout_analyst' then
    if p_expertise >= p_experience and p_expertise >= p_efficiency then
      return 'Talent Evaluation';
    elsif p_experience >= p_expertise and p_experience >= p_efficiency then
      return 'Scouting Experience';
    else
      return 'Data Analysis';
    end if;
  end if;

  return 'General';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_role_quality_tier(p_role_type text, p_expertise integer, p_experience integer, p_potential integer, p_leadership integer, p_efficiency integer, p_loyalty integer)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_role text := lower(coalesce(trim(p_role_type), ''));
  v_avg integer;
begin
  if v_role = 'head_coach' then
    v_avg := round((coalesce(p_expertise,0) + coalesce(p_efficiency,0) + coalesce(p_potential,0)) / 3.0);
  elsif v_role = 'team_doctor' then
    v_avg := round((coalesce(p_expertise,0) + coalesce(p_efficiency,0) + coalesce(p_experience,0)) / 3.0);
  elsif v_role = 'mechanic' then
    v_avg := round((coalesce(p_expertise,0) + coalesce(p_efficiency,0) + coalesce(p_potential,0)) / 3.0);
  elsif v_role = 'sport_director' then
    v_avg := round((coalesce(p_expertise,0) + coalesce(p_leadership,0) + coalesce(p_efficiency,0)) / 3.0);
  elsif v_role = 'scout_analyst' then
    v_avg := round((coalesce(p_expertise,0) + coalesce(p_experience,0) + coalesce(p_efficiency,0)) / 3.0);
  else
    v_avg := round((
      coalesce(p_expertise,0) +
      coalesce(p_experience,0) +
      coalesce(p_potential,0) +
      coalesce(p_leadership,0) +
      coalesce(p_efficiency,0) +
      coalesce(p_loyalty,0)
    ) / 6.0);
  end if;

  return public.staff_skill_tier_label(v_avg);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_market_pick_role()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_roll integer;
  v_total integer;
begin
  with role_weights as (
    select *
    from (
      values
        ('head_coach'::text, public.staff_market_role_weight('head_coach')),
        ('trainer'::text, public.staff_market_role_weight('trainer')),
        ('team_doctor'::text, public.staff_market_role_weight('team_doctor')),
        ('physio'::text, public.staff_market_role_weight('physio')),
        ('mechanic'::text, public.staff_market_role_weight('mechanic')),
        ('scout_analyst'::text, public.staff_market_role_weight('scout_analyst')),
        ('nutritionist'::text, public.staff_market_role_weight('nutritionist')),
        ('sport_director'::text, public.staff_market_role_weight('sport_director')),
        ('u23_head_coach'::text, public.staff_market_role_weight('u23_head_coach'))
    ) as x(role_type, weight)
    where weight > 0
  )
  select sum(weight)::integer
  into v_total
  from role_weights;

  v_roll := floor(random() * v_total)::integer + 1;

  return (
    with role_weights as (
      select *
      from (
        values
          ('head_coach'::text, public.staff_market_role_weight('head_coach')),
          ('trainer'::text, public.staff_market_role_weight('trainer')),
          ('team_doctor'::text, public.staff_market_role_weight('team_doctor')),
          ('physio'::text, public.staff_market_role_weight('physio')),
          ('mechanic'::text, public.staff_market_role_weight('mechanic')),
          ('scout_analyst'::text, public.staff_market_role_weight('scout_analyst')),
          ('nutritionist'::text, public.staff_market_role_weight('nutritionist')),
          ('sport_director'::text, public.staff_market_role_weight('sport_director')),
          ('u23_head_coach'::text, public.staff_market_role_weight('u23_head_coach'))
      ) as x(role_type, weight)
      where weight > 0
    ),
    weighted as (
      select
        role_type,
        weight,
        sum(weight) over (order by role_type) as running_weight
      from role_weights
    )
    select role_type
    from weighted
    where running_weight >= v_roll
    order by running_weight
    limit 1
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_market_expire_due_candidates()
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare
  v_game_ts timestamp without time zone;
  v_expired_count integer := 0;
begin
  select public.get_current_game_timestamp() at time zone 'UTC'
  into v_game_ts;

  if v_game_ts is null then
    raise exception 'Current game timestamp could not be resolved.';
  end if;

  update public.staff_candidates
  set
    is_available = false,
    updated_at = now(),
    notes = coalesce(notes, '{}'::jsonb) || jsonb_build_object(
      'market_exit_reason', 'expired',
      'market_expired_at_game_ts', v_game_ts
    )
  where is_available = true
    and expires_at_game_ts is not null
    and expires_at_game_ts <= v_game_ts;

  get diagnostics v_expired_count = row_count;
  return v_expired_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_market_generate_candidates(p_generate_count integer DEFAULT 20, p_lifetime_hours integer DEFAULT 48)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare
  v_game_ts timestamp without time zone;
  v_inserted_count integer := 0;
  v_attempt_count integer := 0;
  v_new_row record;
begin
  if p_generate_count <= 0 then
    return 0;
  end if;

  if p_lifetime_hours <= 0 then
    raise exception 'p_lifetime_hours must be > 0';
  end if;

  select public.get_current_game_timestamp() at time zone 'UTC'
  into v_game_ts;

  if v_game_ts is null then
    raise exception 'Current game timestamp could not be resolved.';
  end if;

  while v_inserted_count < p_generate_count
    and v_attempt_count < (p_generate_count * 20)
  loop
    v_attempt_count := v_attempt_count + 1;

    begin
      select *
      into v_new_row
      from public.insert_generated_staff_candidate(
        public.staff_market_pick_role(),
        public.staff_market_pick_country_for_generation(),
        null
      );

      update public.staff_candidates
      set
        listed_at_game_ts = v_game_ts,
        expires_at_game_ts = v_game_ts + make_interval(hours => p_lifetime_hours),
        notes = coalesce(notes, '{}'::jsonb) || jsonb_build_object(
          'market_source', 'rolling_daily_market',
          'market_lifetime_hours', p_lifetime_hours,
          'market_listed_at_game_ts', v_game_ts
        )
      where id = v_new_row.id;

      v_inserted_count := v_inserted_count + 1;

    exception
      when unique_violation then
        null;
    end;
  end loop;

  return v_inserted_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_market_region_for_club(p_club_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_club record;
  v_tier text;
begin
  select
    c.id,
    c.country_code,
    c.club_tier,
    c.tier2_division,
    c.tier3_division,
    c.amateur_division
  into v_club
  from public.clubs c
  where c.id = p_club_id
    and c.deleted_at is null
  limit 1;

  if v_club is null then
    return null;
  end if;

  v_tier := lower(coalesce(v_club.club_tier::text, ''));

  -- Tier 1 / Tier 2 = global visibility
  if v_tier in ('worldteam', 'proteam') then
    return null;
  end if;

  -- Tier 3 = regional visibility by continental division
  if v_tier = 'continental' then
    return case v_club.tier3_division
      when 'Continental Europe' then 'europe'
      when 'Continental America' then 'america'
      when 'Continental Asia' then 'asia'
      when 'Continental Africa' then 'africa'
      when 'Continental Oceania' then 'oceania'
      else public.staff_market_region_from_country(v_club.country_code)
    end;
  end if;

  -- Tier 4 = regional visibility by amateur division
  if v_tier = 'amateur' then
    return case v_club.amateur_division
      when 'North America' then 'america'
      when 'South America' then 'america'

      when 'Western Europe' then 'europe'
      when 'Central Europe' then 'europe'
      when 'Southern & Balkan Europe' then 'europe'
      when 'Northern & Eastern Europe' then 'europe'

      when 'West & North Africa' then 'africa'
      when 'Central & South Africa' then 'africa'

      when 'West & Central Asia' then 'asia'
      when 'South Asia' then 'asia'
      when 'East & Southeast Asia' then 'asia'

      when 'Oceania' then 'oceania'
      else public.staff_market_region_from_country(v_club.country_code)
    end;
  end if;

  return public.staff_market_region_from_country(v_club.country_code);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_market_group_for_club(p_club_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_club record;
  v_tier text;
begin
  select
    c.id,
    c.country_code,
    c.club_tier
  into v_club
  from public.clubs c
  where c.id = p_club_id
    and c.deleted_at is null
  limit 1;

  if v_club is null then
    return null;
  end if;

  v_tier := lower(coalesce(v_club.club_tier::text, ''));

  -- Tier 1 / Tier 2 = global visibility
  if v_tier in ('worldteam', 'proteam') then
    return null;
  end if;

  -- Tier 3 / Tier 4 = market-group visibility
  return public.staff_market_group_for_country(v_club.country_code);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_market_policy_for_club(p_club_id uuid)
 RETURNS TABLE(club_id uuid, club_tier text, country_code text, visibility_scope text, visibility_group_code text, generation_scope text, generation_group_code text)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_club record;
  v_tier text;
  v_group_code text;
begin
  select
    c.id,
    c.club_tier::text as club_tier_text,
    c.country_code
  into v_club
  from public.clubs c
  where c.id = p_club_id
    and c.deleted_at is null
  limit 1;

  if v_club is null then
    return;
  end if;

  v_tier := lower(coalesce(v_club.club_tier_text, ''));
  v_group_code := public.staff_market_group_for_country(v_club.country_code);

  if v_tier in ('worldteam', 'proteam') then
    return query
    select
      v_club.id,
      v_club.club_tier_text,
      v_club.country_code,
      'global'::text,
      null::text,
      'global'::text,
      null::text;
  else
    return query
    select
      v_club.id,
      v_club.club_tier_text,
      v_club.country_code,
      'group'::text,
      v_group_code,
      'global'::text,
      null::text;
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_market_candidate_visible_to_club(p_club_id uuid, p_candidate_country_code text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_policy record;
  v_candidate_group text;
begin
  select *
  into v_policy
  from public.staff_market_policy_for_club(p_club_id)
  limit 1;

  if v_policy is null then
    return false;
  end if;

  if v_policy.visibility_scope = 'global' then
    return true;
  end if;

  v_candidate_group := public.staff_market_group_for_country(p_candidate_country_code);

  if v_candidate_group is null then
    return false;
  end if;

  return v_candidate_group = v_policy.visibility_group_code;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_market_pick_country_for_generation()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  v_group_code text;
  v_country_code text;
begin
  v_group_code := public.staff_market_pick_generation_group();

  if v_group_code is not null then
    v_country_code := public.staff_market_pick_country_from_group(v_group_code);
  end if;

  if v_country_code is null or btrim(v_country_code) = '' then
    v_country_code := public.staff_market_pick_country();
  end if;

  return upper(v_country_code);
end;
$function$
;

CREATE OR REPLACE FUNCTION public._evaluate_rider_transfer_offer_package(p_negotiation_id uuid, p_offer_salary_weekly integer, p_offer_duration_seasons integer, p_offer_signing_bonus integer, p_offer_agent_fee integer)
 RETURNS TABLE(total_score integer, acceptance_percent integer, acceptance_band text, predicted_outcome text, summary_text text, primary_reason text, salary_score integer, duration_score integer, bonus_score integer, fee_score integer, tier_score integer, tier_gap integer, desired_tier text, club_tier text, hard_block boolean, reasons jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare
  v_rider_id uuid;
  v_buyer_club_id uuid;
  v_seller_club_id uuid;

  v_current_salary integer := 0;
  v_expected_salary integer := 0;
  v_min_acceptable_salary integer := 0;
  v_preferred_duration smallint := 1;
  v_market_value integer := 0;
  v_age integer := 30;
  v_overall_value integer := 50;
  v_potential_value integer := 50;

  v_desired_tier text := 'amateur';
  v_club_tier text := 'amateur';

  v_desired_rank integer := 1;
  v_club_rank integer := 1;
  v_tier_gap integer := 0;

  v_salary_anchor integer := 1;
  v_bonus_anchor integer := 0;
  v_fee_anchor integer := 0;

  v_profile_modifier integer := 0;
  v_veteran_relief integer := 0;
  v_elite_lower_tier_block boolean := false;

  v_salary_score integer := 0;
  v_duration_score integer := 0;
  v_bonus_score integer := 0;
  v_fee_score integer := 0;
  v_tier_score integer := 0;
  v_total_score integer := 0;

  v_acceptance_percent integer := 0;
  v_acceptance_band text := 'very_low';
  v_predicted_outcome text := 'decline';
  v_summary_text text := '';
  v_primary_reason text := '';
  v_hard_block boolean := false;
  v_reasons jsonb := '[]'::jsonb;
begin
  if p_negotiation_id is null then
    raise exception 'Negotiation id is required';
  end if;

  if p_offer_salary_weekly is null or p_offer_salary_weekly <= 0 then
    raise exception 'Offer salary must be greater than 0';
  end if;

  if p_offer_duration_seasons is null or p_offer_duration_seasons < 1 then
    raise exception 'Offer duration must be at least 1 season';
  end if;

  if p_offer_signing_bonus is null or p_offer_signing_bonus < 0 then
    raise exception 'Signing bonus must be 0 or greater';
  end if;

  if p_offer_agent_fee is null or p_offer_agent_fee < 0 then
    raise exception 'Agent fee must be 0 or greater';
  end if;

  select
    n.rider_id,
    n.buyer_club_id,
    n.seller_club_id,
    coalesce(n.current_salary_weekly, 0),
    coalesce(n.expected_salary_weekly, 0),
    coalesce(n.min_acceptable_salary_weekly, 0),
    greatest(coalesce(n.preferred_duration_seasons, 1), 1),
    coalesce(round(r.market_value)::integer, 0),
    coalesce(public.get_age_years_on_game_date(r.birth_date), 30),
    coalesce(r.overall, 50),
    coalesce(r.potential, 50),
    coalesce(bc.club_tier::text, 'amateur'),
    coalesce(sc.club_tier::text, '')
  into
    v_rider_id,
    v_buyer_club_id,
    v_seller_club_id,
    v_current_salary,
    v_expected_salary,
    v_min_acceptable_salary,
    v_preferred_duration,
    v_market_value,
    v_age,
    v_overall_value,
    v_potential_value,
    v_club_tier,
    v_desired_tier
  from public.rider_transfer_negotiations n
  join public.riders r
    on r.id = n.rider_id
  left join public.clubs bc
    on bc.id = n.buyer_club_id
  left join public.clubs sc
    on sc.id = n.seller_club_id
  where n.id = p_negotiation_id
  limit 1;

  if v_rider_id is null then
    raise exception 'Transfer negotiation not found';
  end if;

  if coalesce(v_desired_tier, '') = '' then
    v_desired_tier :=
      case
        when v_overall_value >= 78 then 'worldteam'
        when v_overall_value >= 68 then 'proteam'
        when v_overall_value >= 58 then 'continental'
        else 'amateur'
      end;
  end if;

  v_desired_rank :=
    case lower(coalesce(v_desired_tier, 'amateur'))
      when 'worldteam' then 4
      when 'proteam' then 3
      when 'continental' then 2
      else 1
    end;

  v_club_rank :=
    case lower(coalesce(v_club_tier, 'amateur'))
      when 'worldteam' then 4
      when 'proteam' then 3
      when 'continental' then 2
      else 1
    end;

  v_tier_gap := v_desired_rank - v_club_rank;

  v_salary_anchor := greatest(
    v_current_salary,
    v_expected_salary,
    v_min_acceptable_salary,
    1
  );

  /*
    Transfer negotiations:
    - signing bonus / agent fee are optional
    - no minimum
    - they should help, but only as support to salary + club fit
  */
  v_bonus_anchor := greatest(500, floor(greatest(v_market_value, 0) * 0.03));
  v_fee_anchor := greatest(500, floor(greatest(v_market_value, 0) * 0.04));

  v_salary_score := case
    when p_offer_salary_weekly < ceil(v_salary_anchor * 0.55) then 4
    when p_offer_salary_weekly < ceil(v_salary_anchor * 0.70) then 10
    when p_offer_salary_weekly < ceil(v_salary_anchor * 0.85) then 18
    when p_offer_salary_weekly < v_min_acceptable_salary then 28
    when p_offer_salary_weekly < ceil(v_salary_anchor * 0.98) then 42
    when p_offer_salary_weekly < ceil(v_salary_anchor * 1.05) then 52
    when p_offer_salary_weekly < ceil(v_salary_anchor * 1.12) then 60
    when p_offer_salary_weekly < ceil(v_salary_anchor * 1.22) then 68
    else 74
  end;

  v_duration_score := case
    when p_offer_duration_seasons = v_preferred_duration then 18
    when abs(p_offer_duration_seasons - v_preferred_duration) = 1 then 12
    when abs(p_offer_duration_seasons - v_preferred_duration) = 2 then 6
    else 0
  end;

  v_bonus_score := case
    when p_offer_signing_bonus >= v_bonus_anchor * 4 then 8
    when p_offer_signing_bonus >= v_bonus_anchor * 2 then 5
    when p_offer_signing_bonus >= v_bonus_anchor then 2
    else 0
  end;

  v_fee_score := case
    when p_offer_agent_fee >= v_fee_anchor * 4 then 8
    when p_offer_agent_fee >= v_fee_anchor * 2 then 5
    when p_offer_agent_fee >= v_fee_anchor then 2
    else 0
  end;

  v_tier_score := case
    when v_tier_gap <= 0 then 6
    when v_tier_gap = 1 then -18
    when v_tier_gap = 2 then -34
    else -52
  end;

  if v_tier_gap > 0 then
    if v_overall_value >= 78 then
      v_profile_modifier := v_profile_modifier - 18;
      v_reasons := v_reasons || jsonb_build_array(
        'This rider is too strong for the current club tier unless the package is exceptional.'
      );
    elsif v_overall_value >= 72 then
      v_profile_modifier := v_profile_modifier - 12;
      v_reasons := v_reasons || jsonb_build_array(
        'The rider''s overall level makes this lower-tier move difficult.'
      );
    elsif v_overall_value >= 66 then
      v_profile_modifier := v_profile_modifier - 6;
    end if;

    if v_age <= 25 and v_potential_value >= 75 then
      v_profile_modifier := v_profile_modifier - 16;
      v_reasons := v_reasons || jsonb_build_array(
        'Young high-potential riders strongly prefer stronger sporting projects.'
      );
    elsif v_age <= 29 and v_potential_value >= 70 then
      v_profile_modifier := v_profile_modifier - 10;
      v_reasons := v_reasons || jsonb_build_array(
        'The rider still has strong upside, which makes this move harder.'
      );
    elsif v_age <= 32 and v_potential_value >= 65 then
      v_profile_modifier := v_profile_modifier - 5;
    end if;

    if v_age between 27 and 32 and v_overall_value >= 70 then
      v_profile_modifier := v_profile_modifier - 8;
      v_reasons := v_reasons || jsonb_build_array(
        'Prime-age established riders are difficult to attract below their competitive level.'
      );
    end if;

    if v_age >= 33 and v_overall_value >= 70 then
      if p_offer_salary_weekly >= ceil(v_expected_salary * 1.08)
         and (p_offer_signing_bonus + p_offer_agent_fee) >= (v_bonus_anchor + v_fee_anchor) * 2 then
        v_veteran_relief := 8;
        v_reasons := v_reasons || jsonb_build_array(
          'The rider is older, so a strong financial package can make the move more realistic.'
        );
      else
        v_profile_modifier := v_profile_modifier - 4;
        v_reasons := v_reasons || jsonb_build_array(
          'The rider is older, but still expects a strong financial reason to drop tier.'
        );
      end if;
    end if;

    if v_tier_gap >= 2 and (
      (v_age <= 30 and v_overall_value >= 74)
      or (v_age <= 27 and v_potential_value >= 76)
    ) then
      v_elite_lower_tier_block := true;
      v_hard_block := true;
      v_profile_modifier := v_profile_modifier - 12;
      v_reasons := v_reasons || jsonb_build_array(
        'This is an elite lower-tier target. Signing is extremely difficult without an exceptional package.'
      );
    end if;

    v_reasons := v_reasons || jsonb_build_array(
      'Buyer club tier is below the rider''s current competitive level.'
    );
  end if;

  if p_offer_salary_weekly < v_min_acceptable_salary then
    v_reasons := v_reasons || jsonb_build_array(
      'Weekly salary is below the rider''s minimum.'
    );
  elsif p_offer_salary_weekly < v_expected_salary then
    v_reasons := v_reasons || jsonb_build_array(
      'Weekly salary is above minimum, but still below expectation.'
    );
  else
    v_reasons := v_reasons || jsonb_build_array(
      'Weekly salary meets or exceeds the rider''s expectation.'
    );
  end if;

  if p_offer_duration_seasons = v_preferred_duration then
    v_reasons := v_reasons || jsonb_build_array(
      'Contract duration matches the rider''s preference.'
    );
  elsif p_offer_duration_seasons < v_preferred_duration then
    v_reasons := v_reasons || jsonb_build_array(
      'Contract duration is shorter than the rider prefers.'
    );
  else
    v_reasons := v_reasons || jsonb_build_array(
      'Contract duration is longer than the rider prefers.'
    );
  end if;

  if p_offer_signing_bonus > 0 then
    v_reasons := v_reasons || jsonb_build_array(
      'Signing bonus is helping the package.'
    );
  end if;

  if p_offer_agent_fee > 0 then
    v_reasons := v_reasons || jsonb_build_array(
      'Agent fee is helping the package.'
    );
  end if;

  v_total_score := greatest(
    0,
    least(
      100,
      v_salary_score +
      v_duration_score +
      v_bonus_score +
      v_fee_score +
      v_tier_score +
      v_profile_modifier + v_veteran_relief + public.team_policy_contract_happiness_bonus_v1(v_buyer_club_id)
    )
  );

  v_acceptance_percent := greatest(2, least(95, v_total_score - 8));

  v_acceptance_band := case
    when v_acceptance_percent < 20 then 'very_low'
    when v_acceptance_percent < 40 then 'low'
    when v_acceptance_percent < 60 then 'moderate'
    when v_acceptance_percent < 80 then 'high'
    else 'very_high'
  end;

  if p_offer_salary_weekly < greatest(1, floor(v_min_acceptable_salary * 0.85)::integer) then
    v_predicted_outcome := 'decline';
    v_primary_reason := 'salary_too_low';
    v_summary_text := 'The package is very unlikely to work because salary is far below the rider''s minimum.';

  elsif p_offer_salary_weekly < v_min_acceptable_salary then
    v_predicted_outcome := 'counter';
    v_primary_reason := 'salary_too_low';
    v_summary_text := 'The package is unlikely to be accepted because salary is below the rider''s minimum.';

  elsif p_offer_duration_seasons < greatest(v_preferred_duration - 1, 1) then
    v_predicted_outcome := 'counter';
    v_primary_reason := 'contract_too_short';
    v_summary_text := 'The rider is likely to push back because the contract is too short.';

  elsif p_offer_duration_seasons > v_preferred_duration + 2 then
    v_predicted_outcome := 'counter';
    v_primary_reason := 'contract_too_long';
    v_summary_text := 'The rider is likely to push back because the contract is too long.';

  elsif v_elite_lower_tier_block
    and (
      v_total_score < 92
      or p_offer_salary_weekly < ceil(v_expected_salary * 1.15)
      or (p_offer_signing_bonus + p_offer_agent_fee) < (v_bonus_anchor + v_fee_anchor) * 3
    ) then
    v_predicted_outcome := 'decline';
    v_primary_reason := 'club_tier_too_low';
    v_summary_text := 'This rider is far above the club''s current level. Even a strong package may not be enough.';

  elsif v_tier_gap > 0
    and (
      v_total_score < 84
      or p_offer_salary_weekly < ceil(v_expected_salary * 1.08)
    ) then
    v_predicted_outcome := 'counter';
    v_primary_reason := 'club_tier_too_low';
    v_summary_text := 'The offer is respectable, but the club tier fit is still working against you.';

  elsif v_total_score >= 84 then
    v_predicted_outcome := 'accept';
    v_primary_reason := 'strong_package';
    v_summary_text := 'This package looks strong and has a good chance of being accepted.';

  elsif v_total_score >= 58 then
    v_predicted_outcome := 'counter';
    v_primary_reason := 'package_not_strong_enough';
    v_summary_text := 'The rider will probably continue negotiating, but the package still needs improvement.';

  else
    v_predicted_outcome := 'decline';
    v_primary_reason := 'weak_package';
    v_summary_text := 'This package looks too weak and is likely to be rejected or heavily countered.';
  end if;

  return query
  select
    v_total_score,
    v_acceptance_percent,
    v_acceptance_band,
    v_predicted_outcome,
    v_summary_text,
    v_primary_reason,
    v_salary_score,
    v_duration_score,
    v_bonus_score,
    v_fee_score,
    v_tier_score,
    v_tier_gap,
    v_desired_tier,
    v_club_tier,
    v_hard_block,
    v_reasons;
end;$function$
;

CREATE OR REPLACE FUNCTION public.preview_rider_transfer_contract_offer(p_negotiation_id uuid, p_offer_salary_weekly integer, p_offer_duration_seasons integer, p_offer_signing_bonus integer, p_offer_agent_fee integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_eval record;
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  select *
  into v_eval
  from public._evaluate_rider_transfer_offer_package(
    p_negotiation_id,
    p_offer_salary_weekly,
    p_offer_duration_seasons,
    p_offer_signing_bonus,
    p_offer_agent_fee
  )
  limit 1;

  return jsonb_build_object(
    'acceptance_percent', v_eval.acceptance_percent,
    'acceptance_band', v_eval.acceptance_band,
    'predicted_outcome', v_eval.predicted_outcome,
    'summary_text', v_eval.summary_text,
    'primary_reason', v_eval.primary_reason,
    'salary_score', v_eval.salary_score,
    'duration_score', v_eval.duration_score,
    'bonus_score', v_eval.bonus_score,
    'fee_score', v_eval.fee_score,
    'tier_score', v_eval.tier_score,
    'tier_gap', v_eval.tier_gap,
    'desired_tier', v_eval.desired_tier,
    'club_tier', v_eval.club_tier,
    'hard_block', v_eval.hard_block,
    'reasons', v_eval.reasons
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_rider_transfer_contract_offer(p_negotiation_id uuid, p_offer_salary_weekly integer, p_offer_duration_seasons smallint, p_offer_signing_bonus integer, p_offer_agent_fee integer)
 RETURNS TABLE(negotiation_id uuid, offer_id uuid, rider_id uuid, buyer_club_id uuid, offer_salary_weekly integer, offer_duration_seasons smallint, accepted boolean, status text, message text, transfer_transaction_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_neg public.rider_transfer_negotiations%rowtype;
  v_now_game_date date;
  v_accepted boolean := false;
  v_hard_decline boolean := false;
  v_tx uuid := null;

  v_buyer_owner_user_id public.clubs.owner_user_id%type;
  v_seller_club_name text;
  v_buyer_club_name text;
  v_rider_name text;

  v_preview record;
  v_preview_outcome text := 'counter';
  v_preview_reason text := 'salary_or_duration_not_competitive';
  v_preview_summary text := 'Rider has not accepted yet. Improve salary, contract length, signing bonus and/or agent fee.';
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_offer_salary_weekly is null or p_offer_salary_weekly <= 0 then
    raise exception 'Salary offer must be > 0';
  end if;

  if p_offer_duration_seasons is null or p_offer_duration_seasons < 1 or p_offer_duration_seasons > 5 then
    raise exception 'Contract duration must be between 1 and 5 seasons';
  end if;

  if p_offer_signing_bonus is null or p_offer_signing_bonus < 0 then
    raise exception 'Signing bonus must be 0 or greater';
  end if;

  if p_offer_agent_fee is null or p_offer_agent_fee < 0 then
    raise exception 'Agent fee must be 0 or greater';
  end if;

  select *
  into v_neg
  from public.rider_transfer_negotiations n
  where n.id = p_negotiation_id
  for update;

  if not found then
    raise exception 'Transfer negotiation not found';
  end if;

  select
    coalesce(
      to_jsonb(c)->>'name',
      to_jsonb(c)->>'club_name',
      to_jsonb(c)->>'display_name',
      c.id::text
    )
  into v_seller_club_name
  from public.clubs c
  where c.id = v_neg.seller_club_id;

  select
    c.owner_user_id,
    coalesce(
      to_jsonb(c)->>'name',
      to_jsonb(c)->>'club_name',
      to_jsonb(c)->>'display_name',
      c.id::text
    )
  into
    v_buyer_owner_user_id,
    v_buyer_club_name
  from public.clubs c
  where c.id = v_neg.buyer_club_id;

  select
    coalesce(
      to_jsonb(r)->>'name',
      to_jsonb(r)->>'rider_name',
      to_jsonb(r)->>'display_name',
      to_jsonb(r)->>'full_name',
      r.id::text
    )
  into v_rider_name
  from public.riders r
  where r.id = v_neg.rider_id;

  v_seller_club_name := coalesce(v_seller_club_name, v_neg.seller_club_id::text);
  v_buyer_club_name := coalesce(v_buyer_club_name, v_neg.buyer_club_id::text);
  v_rider_name := coalesce(v_rider_name, v_neg.rider_id::text);

  if v_neg.status <> 'open' then
    raise exception 'Only open transfer negotiations can receive rider contract offers';
  end if;

  if not (
    exists (
      select 1
      from public.clubs c
      where c.id = v_neg.buyer_club_id
        and c.owner_user_id = auth.uid()
    )
    or exists (
      select 1
      from public.club_memberships cm
      where cm.club_id = v_neg.buyer_club_id
        and cm.user_id = auth.uid()
    )
  ) then
    raise exception 'Not allowed to negotiate for this buyer club';
  end if;

  v_now_game_date := public.get_current_game_date_date();

  if v_neg.expires_on_game_date < v_now_game_date then
    update public.rider_transfer_negotiations n
    set
      status = 'expired',
      closed_reason = 'negotiation_expired'
    where n.id = v_neg.id
      and n.status = 'open';

    update public.rider_transfer_offers o
    set
      status = 'expired',
      auto_block_reason = 'rider_negotiation_expired',
      metadata = coalesce(o.metadata, '{}'::jsonb) || jsonb_build_object(
        'expired_at', now(),
        'expired_reason', 'rider_negotiation_expired'
      )
    where o.id = v_neg.offer_id
      and o.status = 'club_accepted';

    update public.rider_transfer_listings l
    set status = 'listed'
    where l.id = v_neg.listing_id
      and l.status = 'club_accepted'
      and (l.expires_on_game_date is null or l.expires_on_game_date >= v_now_game_date);

    perform public.log_rider_transfer_event(
      p_event_type      => 'negotiation_expired',
      p_rider_id        => v_neg.rider_id,
      p_listing_id      => v_neg.listing_id,
      p_offer_id        => v_neg.offer_id,
      p_negotiation_id  => v_neg.id,
      p_seller_club_id  => v_neg.seller_club_id,
      p_buyer_club_id   => v_neg.buyer_club_id,
      p_event_game_date => v_now_game_date,
      p_payload         => jsonb_build_object('reason', 'negotiation_expired')
    );

    raise exception 'Negotiation has expired';
  end if;

  if v_neg.locked_until is not null and v_neg.locked_until > now() then
    raise exception 'Negotiation is temporarily locked until %', v_neg.locked_until;
  end if;

  update public.rider_transfer_negotiations n
  set
    offer_salary_weekly = p_offer_salary_weekly,
    offer_duration_seasons = p_offer_duration_seasons,
    offer_signing_bonus = p_offer_signing_bonus,
    offer_agent_fee = p_offer_agent_fee,
    attempt_count = n.attempt_count + 1,
    notes_json = coalesce(n.notes_json, '{}'::jsonb) || jsonb_build_object(
      'last_offer_at', now(),
      'last_offer_by', auth.uid(),
      'last_offer_signing_bonus', p_offer_signing_bonus,
      'last_offer_agent_fee', p_offer_agent_fee
    )
  where n.id = v_neg.id
  returning *
  into v_neg;

  /*
    IMPORTANT:
    This assumes the helper from the previous step already exists.
    If your helper name/signature is slightly different, only adjust this one block.
  */
  select *
  into v_preview
  from public._evaluate_rider_transfer_offer_package(
    v_neg.id,
    p_offer_salary_weekly,
    p_offer_duration_seasons,
    p_offer_signing_bonus,
    p_offer_agent_fee
  )
  limit 1;

  v_preview_outcome := coalesce(v_preview.predicted_outcome, 'counter');
  v_preview_reason := coalesce(v_preview.primary_reason, 'salary_or_duration_not_competitive');
  v_preview_summary := coalesce(
    v_preview.summary_text,
    'Rider has not accepted yet. Improve salary, contract length, signing bonus and/or agent fee.'
  );

  perform public.log_rider_transfer_event(
    p_event_type      => 'contract_terms_submitted',
    p_rider_id        => v_neg.rider_id,
    p_listing_id      => v_neg.listing_id,
    p_offer_id        => v_neg.offer_id,
    p_negotiation_id  => v_neg.id,
    p_seller_club_id  => v_neg.seller_club_id,
    p_buyer_club_id   => v_neg.buyer_club_id,
    p_actor_user_id   => auth.uid(),
    p_event_game_date => v_now_game_date,
    p_payload         => jsonb_build_object(
      'offer_salary_weekly', p_offer_salary_weekly,
      'offer_duration_seasons', p_offer_duration_seasons,
      'offer_signing_bonus', p_offer_signing_bonus,
      'offer_agent_fee', p_offer_agent_fee,
      'attempt_count', v_neg.attempt_count,
      'preview_outcome', v_preview_outcome,
      'preview_reason', v_preview_reason,
      'preview_summary', v_preview_summary,
      'acceptance_percent', coalesce(v_preview.acceptance_percent, 0),
      'acceptance_band', coalesce(v_preview.acceptance_band, 'unknown')
    )
  );

  v_accepted := (v_preview_outcome = 'accept');

  v_hard_decline :=
    (v_preview_outcome = 'decline')
    or v_neg.attempt_count >= coalesce(v_neg.max_attempts, 999999);

  if v_accepted then
    update public.rider_transfer_negotiations n
    set
      status = 'accepted',
      locked_until = null,
      closed_reason = null,
      notes_json = coalesce(n.notes_json, '{}'::jsonb) || jsonb_build_object(
        'rider_accepted_terms_at', now(),
        'accepted_signing_bonus', p_offer_signing_bonus,
        'accepted_agent_fee', p_offer_agent_fee
      )
    where n.id = v_neg.id
    returning *
    into v_neg;

    v_tx := public._complete_rider_transfer_after_negotiation_internal(v_neg.id);

    perform public.log_rider_transfer_event(
      p_event_type      => 'transfer_completed_after_rider_acceptance',
      p_rider_id        => v_neg.rider_id,
      p_listing_id      => v_neg.listing_id,
      p_offer_id        => v_neg.offer_id,
      p_negotiation_id  => v_neg.id,
      p_seller_club_id  => v_neg.seller_club_id,
      p_buyer_club_id   => v_neg.buyer_club_id,
      p_actor_user_id   => auth.uid(),
      p_event_game_date => v_now_game_date,
      p_payload         => jsonb_build_object(
        'offer_salary_weekly', p_offer_salary_weekly,
        'offer_duration_seasons', p_offer_duration_seasons,
        'offer_signing_bonus', p_offer_signing_bonus,
        'offer_agent_fee', p_offer_agent_fee,
        'transfer_transaction_id', v_tx
      )
    );

    return query
    select
      v_neg.id,
      v_neg.offer_id,
      v_neg.rider_id,
      v_neg.buyer_club_id,
      p_offer_salary_weekly,
      p_offer_duration_seasons,
      true,
      'completed'::text,
      'Rider accepted the contract terms. Transfer completed.'::text,
      v_tx;
    return;
  end if;

  if v_hard_decline then
    update public.rider_transfer_negotiations n
    set
      status = 'declined',
      locked_until = null,
      closed_reason = v_preview_reason,
      notes_json = coalesce(n.notes_json, '{}'::jsonb) || jsonb_build_object(
        'rider_declined_at', now(),
        'decline_reason', v_preview_reason
      )
    where n.id = v_neg.id
    returning *
    into v_neg;

    update public.rider_transfer_offers o
    set
      status = 'rider_declined',
      auto_block_reason = 'rider_declined_terms',
      metadata = coalesce(o.metadata, '{}'::jsonb) || jsonb_build_object(
        'rider_declined_at', now(),
        'rider_decline_reason', v_preview_reason
      )
    where o.id = v_neg.offer_id
      and o.status in ('open', 'club_accepted');

    update public.rider_transfer_listings l
    set status = 'listed'
    where l.id = v_neg.listing_id
      and l.status = 'club_accepted'
      and (l.expires_on_game_date is null or l.expires_on_game_date >= v_now_game_date);

    perform public.log_rider_transfer_event(
      p_event_type      => 'rider_declined_terms',
      p_rider_id        => v_neg.rider_id,
      p_listing_id      => v_neg.listing_id,
      p_offer_id        => v_neg.offer_id,
      p_negotiation_id  => v_neg.id,
      p_seller_club_id  => v_neg.seller_club_id,
      p_buyer_club_id   => v_neg.buyer_club_id,
      p_actor_user_id   => auth.uid(),
      p_event_game_date => v_now_game_date,
      p_payload         => jsonb_build_object(
        'offer_salary_weekly', p_offer_salary_weekly,
        'offer_duration_seasons', p_offer_duration_seasons,
        'offer_signing_bonus', p_offer_signing_bonus,
        'offer_agent_fee', p_offer_agent_fee,
        'reason', v_preview_reason,
        'summary', v_preview_summary
      )
    );

    if v_buyer_owner_user_id is not null then
      perform public.create_transfer_notification(
        p_user_id => v_buyer_owner_user_id,
        p_type_code => 'RIDER_NEGOTIATION_DECLINED',
        p_title => 'Rider declined transfer',
        p_message => format('%s rejected your contract terms.', v_rider_name),
        p_offer_id => v_neg.offer_id,
        p_listing_id => v_neg.listing_id,
        p_negotiation_id => v_neg.id,
        p_rider_id => v_neg.rider_id,
        p_action_url => format('/#/dashboard/transfers/negotiations/%s', v_neg.id),
        p_payload_json => jsonb_build_object(
          'offer_id', v_neg.offer_id,
          'listing_id', v_neg.listing_id,
          'negotiation_id', v_neg.id,
          'rider_id', v_neg.rider_id,
          'rider_name', v_rider_name,
          'seller_club_name', v_seller_club_name,
          'buyer_club_name', v_buyer_club_name,
          'offer_salary_weekly', p_offer_salary_weekly,
          'offer_duration_seasons', p_offer_duration_seasons,
          'offer_signing_bonus', p_offer_signing_bonus,
          'offer_agent_fee', p_offer_agent_fee,
          'reason', v_preview_reason,
          'status', 'declined'
        )
      );
    end if;

    return query
    select
      v_neg.id,
      v_neg.offer_id,
      v_neg.rider_id,
      v_neg.buyer_club_id,
      p_offer_salary_weekly,
      p_offer_duration_seasons,
      false,
      'declined'::text,
      'Rider refused the contract terms.'::text,
      null::uuid;
    return;
  end if;

  update public.rider_transfer_negotiations n
  set
    locked_until = now() + interval '10 minutes',
    notes_json = coalesce(n.notes_json, '{}'::jsonb) || jsonb_build_object(
      'soft_reject_at', now(),
      'preview_reason', v_preview_reason,
      'preview_summary', v_preview_summary
    )
  where n.id = v_neg.id
  returning *
  into v_neg;

  perform public.log_rider_transfer_event(
    p_event_type      => 'negotiation_still_open',
    p_rider_id        => v_neg.rider_id,
    p_listing_id      => v_neg.listing_id,
    p_offer_id        => v_neg.offer_id,
    p_negotiation_id  => v_neg.id,
    p_seller_club_id  => v_neg.seller_club_id,
    p_buyer_club_id   => v_neg.buyer_club_id,
    p_actor_user_id   => auth.uid(),
    p_event_game_date => v_now_game_date,
    p_payload         => jsonb_build_object(
      'offer_salary_weekly', p_offer_salary_weekly,
      'offer_duration_seasons', p_offer_duration_seasons,
      'offer_signing_bonus', p_offer_signing_bonus,
      'offer_agent_fee', p_offer_agent_fee,
      'locked_until', v_neg.locked_until,
      'preview_reason', v_preview_reason,
      'preview_summary', v_preview_summary
    )
  );

  return query
  select
    v_neg.id,
    v_neg.offer_id,
    v_neg.rider_id,
    v_neg.buyer_club_id,
    p_offer_salary_weekly,
    p_offer_duration_seasons,
    false,
    'open'::text,
    v_preview_summary,
    null::uuid;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_rider_transfer_contract_offer(p_negotiation_id uuid, p_offer_salary_weekly integer, p_offer_duration_seasons smallint)
 RETURNS TABLE(negotiation_id uuid, offer_id uuid, rider_id uuid, buyer_club_id uuid, offer_salary_weekly integer, offer_duration_seasons smallint, accepted boolean, status text, message text, transfer_transaction_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  return query
  select *
  from public.submit_rider_transfer_contract_offer(
    p_negotiation_id,
    p_offer_salary_weekly,
    p_offer_duration_seasons,
    0,
    0
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_club_staff_role_limits(p_club_id uuid)
 RETURNS TABLE(role_type text, limit_count integer, active_count integer, open_slots integer, can_hire boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return query
  select
    g.role_type,
    g.limit_count,
    g.active_count,
    g.open_slots,
    g.can_hire
  from public.get_staff_role_capacity_overview_for_club(p_club_id) g
  order by
    case g.role_type
      when 'head_coach' then 10
      when 'trainer' then 20
      when 'team_doctor' then 30
      when 'physio' then 40
      when 'nutritionist' then 50
      when 'mechanic' then 60
      when 'sport_director' then 70
      when 'scout_analyst' then 80
      when 'u23_head_coach' then 90
      else 999
    end;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.hire_staff_candidate(p_candidate_id uuid, p_contract_days integer DEFAULT 0)
 RETURNS TABLE(staff_id uuid, club_id uuid, role_type text, staff_name text, salary_weekly integer, contract_expires_at date)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$declare
  v_user_id uuid;
  v_club_id uuid;
  v_candidate public.staff_candidates%rowtype;
  v_staff_id uuid;
  v_contract_expires_at date;

  v_limit_count integer;
  v_active_count integer;
  v_can_hire boolean;

  v_team_scope text;
  v_current_season integer;
  v_target_season integer;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'Not authenticated.';
  end if;

  if p_contract_days is null or p_contract_days not in (0, 1) then
    raise exception 'Contract term must be 0 (current season end) or 1 (next season end).';
  end if;

  select gs.season_number
  into v_current_season
  from public.game_state gs
  where gs.id = true
  limit 1;

  if v_current_season is null then
    raise exception 'Current game season not found.';
  end if;

  select c.id
  into v_club_id
  from public.clubs c
  where c.owner_user_id = v_user_id
    and c.deleted_at is null
    and c.parent_club_id is null
    and coalesce(c.club_type, 'main') <> 'developing'
  order by c.created_at asc
  limit 1;

  if v_club_id is null then
    raise exception 'Main club not found.';
  end if;

  select *
  into v_candidate
  from public.staff_candidates sc
  where sc.id = p_candidate_id
    and sc.is_available = true
  for update;

  if not found then
    raise exception 'Candidate not found or no longer available.';
  end if;

  if v_candidate.role_type = 'u23_head_coach'
     and not public.current_user_has_premium_v1() then
    raise exception 'Premium membership is required to hire a U23 Head Coach.';
  end if;

  perform pg_advisory_xact_lock(
    hashtext('hire_staff:' || v_club_id::text || ':' || v_candidate.role_type)
  );

  select
    g.limit_count,
    g.active_count,
    g.can_hire
  into
    v_limit_count,
    v_active_count,
    v_can_hire
  from public.get_staff_role_capacity_overview_for_club(v_club_id) g
  where g.role_type = v_candidate.role_type
  limit 1;

  if v_limit_count is null then
    raise exception 'Unsupported staff role: %', v_candidate.role_type;
  end if;

  if not coalesce(v_can_hire, false) then
    raise exception '% staff limit reached (%/% active).',
      v_candidate.role_type,
      v_active_count,
      v_limit_count;
  end if;

  v_team_scope :=
    case coalesce(v_candidate.notes ->> 'team_scope_hint', 'all')
      when 'first_team' then 'first_team'
      when 'u23' then 'u23'
      else 'all'
    end;

  v_target_season := v_current_season + p_contract_days;

  v_contract_expires_at := make_date(
    1999 + v_target_season,
    12,
    31
  );

  insert into public.club_staff (
    club_id,
    role_type,
    specialization,
    team_scope,
    staff_name,
    first_name,
    last_name,
    country_code,
    expertise,
    experience,
    potential,
    leadership,
    efficiency,
    loyalty,
    salary_weekly,
    contract_expires_at,
    birth_date,
    is_active,
    notes
  )
  values (
    v_club_id,
    v_candidate.role_type,
    v_candidate.specialization,
    v_team_scope,
    v_candidate.staff_name,
    v_candidate.first_name,
    v_candidate.last_name,
    v_candidate.country_code,
    v_candidate.expertise,
    v_candidate.experience,
    v_candidate.potential,
    v_candidate.leadership,
    v_candidate.efficiency,
    v_candidate.loyalty,
    v_candidate.salary_weekly,
    v_contract_expires_at,
    v_candidate.birth_date,
    true,
    coalesce(v_candidate.notes, '{}'::jsonb) || jsonb_build_object(
      'hired_from_candidate_id', v_candidate.id,
      'hired_at', now(),
      'contract_term_mode', case
        when p_contract_days = 0 then 'current_season_end'
        else 'next_season_end'
      end
    )
  )
  returning id into v_staff_id;

  update public.staff_candidates
  set is_available = false
  where id = v_candidate.id;

  perform public.create_game_notification_for_user_checked(
    v_user_id,
    'STAFF_HIRED',
    'Staff hired: ' || v_candidate.staff_name,
    v_candidate.staff_name || ' has joined your club as ' || replace(v_candidate.role_type::text, '_', ' ') || '.',
    '/dashboard/staff',
    jsonb_build_object(
      'staff_id', v_staff_id,
      'candidate_id', v_candidate.id,
      'club_id', v_club_id,
      'staff_name', v_candidate.staff_name,
      'role_type', v_candidate.role_type,
      'birth_date', v_candidate.birth_date,
      'salary_weekly', v_candidate.salary_weekly,
      'contract_expires_at', v_contract_expires_at
    )
  );

  return query
  select
    v_staff_id,
    v_club_id,
    v_candidate.role_type,
    v_candidate.staff_name,
    v_candidate.salary_weekly,
    v_contract_expires_at;
end;$function$
;

CREATE OR REPLACE FUNCTION public.get_available_scout_staff_for_rider(p_rider_id uuid, p_requesting_user_id uuid)
 RETURNS TABLE(scout_staff_id uuid, scout_name text, role_type text, expertise integer, experience integer, potential integer, leadership integer, efficiency integer, loyalty integer, scouting_level integer, precision_score numeric, speed_score numeric, precision_tier text, estimated_duration_hours integer, free_reports_per_day integer, free_reports_used_today integer, free_reports_left_today integer, next_report_coin_cost integer, wallet_balance integer, on_active_course boolean, can_scout boolean, blocking_reason text, has_active_scouting_task boolean, active_scouting_task_label text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$declare
  v_club_id uuid;
  v_game_ts timestamp without time zone;
  v_game_date date;
begin
  v_club_id := public.resolve_main_club_id_for_user(p_requesting_user_id);
  v_game_ts := public.get_current_game_timestamp();
  v_game_date := v_game_ts::date;

  return query
  select
    cs.id::uuid,
    cs.staff_name::text,
    cs.role_type::text,
    cs.expertise::integer,
    cs.experience::integer,
    cs.potential::integer,
    cs.leadership::integer,
    cs.efficiency::integer,
    cs.loyalty::integer,
    coalesce(ci.scouting_level, 0)::integer,

    calc.precision_score::numeric,
    calc.speed_score::numeric,
    calc.precision_tier::text,
    calc.duration_hours::integer,

    1::integer,
    coalesce(sdu.free_reports_used, 0)::integer,
    greatest(0, 1 - coalesce(sdu.free_reports_used, 0))::integer,
    case when coalesce(sdu.free_reports_used, 0) >= 1 then 3 else 0 end::integer,
    coalesce(uw.balance, 0)::integer,

    exists (
      select 1
      from public.staff_courses sc
      where sc.staff_id = cs.id
        and sc.status = 'active'
    )::boolean,

    case
      when busy.task_id is not null then false
      when exists (
        select 1
        from public.staff_courses sc
        where sc.staff_id = cs.id
          and sc.status = 'active'
      ) then false
      else true
    end::boolean,

    case
      when busy.task_id is not null then 'Selected scout is already assigned to another scouting task.'
      when exists (
        select 1
        from public.staff_courses sc
        where sc.staff_id = cs.id
          and sc.status = 'active'
      ) then 'This scout is currently on an active course.'
      else null
    end::text,

    (busy.task_id is not null)::boolean,

    case
      when busy.task_id is null then null
      else (
        'Scouting rider: ' ||
        coalesce(busy.rider_name, 'Unknown rider') ||
        ' • Completes: Season ' ||
        public.season_from_game_date(busy.completes_at_game_ts::date)::text ||
        ' - ' ||
        to_char(busy.completes_at_game_ts, 'Mon DD HH24:MI')
      )
    end::text

  from public.club_staff cs
  left join public.club_infrastructure ci
    on ci.club_id = cs.club_id
  left join public.staff_scout_daily_usage sdu
    on sdu.club_id = cs.club_id
   and sdu.staff_id = cs.id
   and sdu.game_date = v_game_date
  left join public.user_wallets uw
    on uw.user_id = p_requesting_user_id
  cross join lateral public.calculate_scout_precision_and_duration(
    cs.expertise,
    cs.experience,
    cs.potential,
    cs.leadership,
    least(100, cs.efficiency + public.team_policy_staff_quality_bonus_v1(v_club_id)), cs.loyalty,
    coalesce(ci.scouting_level, 0)
  ) calc
  left join lateral (
    select
      rst.id as task_id,
      rst.completes_at_game_ts,
      coalesce(
        nullif(r.display_name, ''),
        trim(concat_ws(' ', r.first_name, r.last_name))
      )::text as rider_name
    from public.rider_scout_tasks rst
    left join public.riders r
      on r.id = rst.rider_id
    where rst.scout_staff_id = cs.id
      and rst.status in ('queued', 'in_progress')
    order by rst.completes_at_game_ts asc
    limit 1
  ) busy on true
  where cs.club_id = v_club_id
    and cs.role_type = 'scout_analyst'
    and cs.is_active = true
  order by cs.staff_name asc;
end;$function$
;

CREATE OR REPLACE FUNCTION public.finance_run_due_monthly_tax_audits(p_notify boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_current_season integer;
  v_current_month integer;
  v_current_day integer;
  v_audit_season integer;
  v_audit_month integer;
  v_period_start date;
  v_period_end date;
  r record;
  v_result jsonb;
  v_rebate_result jsonb;
  v_maintenance_result jsonb;
  v_results jsonb := '[]'::jsonb;
  v_count integer := 0;
begin
  select gs.season_number,gs.month_number,gs.day_number
  into v_current_season,v_current_month,v_current_day
  from public.game_state gs where gs.id=true limit 1;

  if v_current_season is null or v_current_month is null or v_current_day is null then
    raise exception 'game_state date is missing';
  end if;

  if v_current_day<>1 then
    return jsonb_build_object('status','not_due','current_season',v_current_season,'current_month',v_current_month,'current_day',v_current_day);
  end if;

  v_maintenance_result := public.finance_process_monthly_club_house_maintenance_v1();
  perform public.finance_process_monthly_training_center_maintenance_v1();
  perform public.finance_process_monthly_medical_center_maintenance_v1();
  perform public.finance_process_monthly_youth_academy_maintenance_v1();
  perform public.finance_process_monthly_mechanics_workshop_maintenance_v1();
  perform public.finance_process_monthly_scouting_office_maintenance_v1();

  if v_current_month=1 then v_audit_season:=v_current_season-1; v_audit_month:=12;
  else v_audit_season:=v_current_season; v_audit_month:=v_current_month-1; end if;

  if v_audit_season<1 then
    return jsonb_build_object('status','no_previous_month','current_season',v_current_season,'current_month',v_current_month,'current_day',v_current_day,'club_house_maintenance',v_maintenance_result);
  end if;

  v_period_start:=make_date(1999+v_audit_season,v_audit_month,1);
  v_period_end:=(make_date(1999+v_audit_season,v_audit_month,1)+interval '1 month'-interval '1 day')::date;

  for r in
    select distinct c.id as club_id
    from public.clubs c
    where c.deleted_at is null and (
      exists (
        select 1 from finance.transactions t
        join finance.entries e on e.transaction_id=t.id
        join finance.accounts a on a.id=e.account_id
        join finance.transaction_types tt on tt.code=t.type
        where a.club_id=c.id and a.currency='CASH' and a.kind='main' and e.amount>0 and tt.is_taxable=true
          and jsonb_typeof(t.metadata->'game_date')='object'
          and make_date(1999+((t.metadata->'game_date'->>'season')::int),(t.metadata->'game_date'->>'month')::int,(t.metadata->'game_date'->>'day')::int) between v_period_start and v_period_end
      ) or exists (
        select 1 from finance.transactions tax_t
        join finance.entries e on e.transaction_id=tax_t.id
        join finance.accounts a on a.id=e.account_id
        join finance.transactions src on tax_t.metadata->>'source_transaction_id'=src.id::text
        where a.club_id=c.id and a.currency='CASH' and a.kind='main' and e.amount<0 and tax_t.type='tax_withholding'
          and jsonb_typeof(src.metadata->'game_date')='object'
          and make_date(1999+((src.metadata->'game_date'->>'season')::int),(src.metadata->'game_date'->>'month')::int,(src.metadata->'game_date'->>'day')::int) between v_period_start and v_period_end
      )
    )
  loop
    v_result := public.finance_run_monthly_tax_audit_for_club(r.club_id,v_period_start,v_period_end,p_notify);
    v_rebate_result := public.finance_apply_club_house_tax_rebate_v1(r.club_id,v_period_start,v_period_end);
    v_count:=v_count+1;
    v_results:=v_results||jsonb_build_array(v_result||jsonb_build_object('club_house_tax_rebate',v_rebate_result));
  end loop;

  return jsonb_build_object('status','completed','period_start',v_period_start,'period_end',v_period_end,'audited_club_count',v_count,'club_results',v_results,'club_house_maintenance',v_maintenance_result);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_get_club_tax_position_for_period(p_club_id uuid, p_period_start date, p_period_end date)
 RETURNS TABLE(period_start date, period_end date, taxable_income_gross bigint, expected_tax bigint, already_withheld bigint, adjustment_amount bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid;
begin
  v_uid := auth.uid();

  if v_uid is null then
    raise exception 'Not authenticated.';
  end if;

  if not finance.is_club_member_or_owner(p_club_id, v_uid) then
    raise exception 'Not allowed to read tax position for this club.';
  end if;

  return query
  with taxable_source_transactions as (
    select
      t.id as transaction_id,
      t.type,
      tt.tax_rate_bps,
      sum(e.amount)::bigint as gross_amount,
      make_date(
        1999 + ((t.metadata -> 'game_date' ->> 'season')::int),
        (t.metadata -> 'game_date' ->> 'month')::int,
        (t.metadata -> 'game_date' ->> 'day')::int
      ) as game_day
    from finance.transactions t
    join finance.entries e on e.transaction_id = t.id
    join finance.accounts a on a.id = e.account_id
    join finance.transaction_types tt on tt.code = t.type
    where a.club_id = p_club_id
      and a.currency = 'CASH'
      and a.kind = 'main'
      and e.amount > 0
      and tt.is_taxable = true
      and jsonb_typeof(t.metadata -> 'game_date') = 'object'
    group by t.id, t.type, tt.tax_rate_bps, t.metadata
  ),
  withholding_rows as (
    select
      tax_t.id as tax_transaction_id,
      src.id as source_transaction_id,
      abs(e.amount)::bigint as withheld_amount,
      make_date(
        1999 + ((src.metadata -> 'game_date' ->> 'season')::int),
        (src.metadata -> 'game_date' ->> 'month')::int,
        (src.metadata -> 'game_date' ->> 'day')::int
      ) as source_game_day
    from finance.transactions tax_t
    join finance.entries e on e.transaction_id = tax_t.id
    join finance.accounts a on a.id = e.account_id
    join finance.transactions src
      on tax_t.metadata ->> 'source_transaction_id' = src.id::text
    where a.club_id = p_club_id
      and a.currency = 'CASH'
      and a.kind = 'main'
      and e.amount < 0
      and tax_t.type = 'tax_withholding'
      and jsonb_typeof(src.metadata -> 'game_date') = 'object'
  ),
  totals as (
    select
      coalesce((
        select sum(gross_amount)::bigint
        from taxable_source_transactions
        where game_day between p_period_start and p_period_end
      ), 0)::bigint as taxable_income_gross,

      coalesce((
        select sum(round((gross_amount::numeric * tax_rate_bps::numeric) / 10000.0)::bigint)::bigint
        from taxable_source_transactions
        where game_day between p_period_start and p_period_end
      ), 0)::bigint as expected_tax,

      coalesce((
        select sum(withheld_amount)::bigint
        from withholding_rows
        where source_game_day between p_period_start and p_period_end
      ), 0)::bigint as already_withheld
  )
  select
    p_period_start,
    p_period_end,
    t.taxable_income_gross,
    t.expected_tax,
    t.already_withheld,
    (t.already_withheld - t.expected_tax)::bigint as adjustment_amount
  from totals t;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_retirement_announcement_game_date(p_birth_date date, p_season_number integer, p_subject_id uuid)
 RETURNS date
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_game_year integer;
  v_base_date date;
  v_offset_days integer;
  v_result date;
  v_season_start date;
  v_latest_date date;
  v_current_season integer;
  v_current_game_date date;
begin
  if p_birth_date is null then
    raise exception 'Birth date is required for retirement announcement date.';
  end if;

  v_game_year := 1999 + p_season_number;

  v_season_start := make_date(v_game_year, 1, 1);
  v_latest_date := make_date(v_game_year, 12, 15);

  v_base_date :=
    make_date(v_game_year, 1, 1)
    + ((extract(doy from p_birth_date)::integer - 1) * interval '1 day');

  v_offset_days :=
    (abs(hashtext(p_subject_id::text || ':retirement:' || p_season_number::text)::bigint) % 41)::integer - 20;

  v_result := (v_base_date + make_interval(days => v_offset_days))::date;

  select gs.season_number, public.get_current_game_date_date()
  into v_current_season, v_current_game_date
  from public.game_state gs
  where gs.id = true
  limit 1;

  -- If we are generating for the already-running season and the birthday-window date is already past,
  -- spread the announcement over the next 1-40 game days instead of announcing everything today.
  if v_current_season = p_season_number
     and v_current_game_date is not null
     and v_result < v_current_game_date then

    if v_current_game_date > v_latest_date then
      v_latest_date := v_current_game_date;
    end if;

    v_offset_days :=
      (abs(hashtext(p_subject_id::text || ':retirement-catchup:' || p_season_number::text)::bigint) % 40)::integer + 1;

    v_result := (v_current_game_date + make_interval(days => v_offset_days))::date;
  end if;

  return least(greatest(v_result, v_season_start), v_latest_date);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_retirement_decisions_for_season(p_season_number integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_season integer;
  v_effective_game_date date;
  v_rider_inserted integer := 0;
  v_staff_inserted integer := 0;
begin
  if p_season_number is null then
    select gs.season_number
    into v_season
    from public.game_state gs
    where gs.id = true
    limit 1;
  else
    v_season := p_season_number;
  end if;

  if v_season is null then
    raise exception 'Season number not found.';
  end if;

  v_effective_game_date := make_date(1999 + v_season, 12, 31);

  with rider_candidates as (
    select
      r.id as subject_id,
      roster.club_id,
      c.owner_user_id,
      coalesce(
        nullif(trim(r.display_name), ''),
        nullif(trim(concat_ws(' ', r.first_name, r.last_name)), ''),
        'Unknown rider'
      ) as display_name,
      r.role::text as role_label,
      r.birth_date,
      greatest(0, extract(year from age(v_effective_game_date, r.birth_date))::integer) as age_years
    from public.riders r
    left join lateral (
      select cr.club_id
      from public.club_riders cr
      where cr.rider_id = r.id
      limit 1
    ) roster on true
    left join public.clubs c
      on c.id = roster.club_id
     and c.deleted_at is null
    where r.birth_date is not null
      and coalesce(r.availability_status, '') <> 'retired'
      and not exists (
        select 1
        from public.retirement_decisions old_rd
        where old_rd.subject_type = 'rider'
          and old_rd.subject_id = r.id
          and old_rd.status = 'finalized'
      )
  ),
  rider_rolls as (
    select
      rc.*,
      public.get_retirement_band('rider', rc.age_years) as retirement_band,
      public.get_retirement_chance_bps('rider', rc.age_years) as retirement_chance_bps,
      ((abs(hashtext(rc.subject_id::text || ':retirement-roll:' || v_season::text)::bigint) % 10000) + 1)::integer as retirement_roll
    from rider_candidates rc
  ),
  inserted as (
    insert into public.retirement_decisions (
      subject_type,
      subject_id,
      club_id,
      owner_user_id,
      display_name,
      role_label,
      season_number,
      age_years,
      retirement_band,
      retirement_chance_bps,
      retirement_roll,
      announcement_game_date,
      effective_game_date,
      status,
      payload
    )
    select
      'rider',
      rr.subject_id,
      rr.club_id,
      rr.owner_user_id,
      rr.display_name,
      rr.role_label,
      v_season,
      rr.age_years,
      rr.retirement_band,
      rr.retirement_chance_bps,
      rr.retirement_roll,
      public.get_retirement_announcement_game_date(rr.birth_date, v_season, rr.subject_id),
      v_effective_game_date,
      'planned',
      jsonb_build_object(
        'source_table', 'riders',
        'birth_date', rr.birth_date,
        'effective_game_date', v_effective_game_date
      )
    from rider_rolls rr
    where rr.retirement_chance_bps > 0
      and rr.retirement_roll <= rr.retirement_chance_bps
    on conflict (subject_type, subject_id, season_number) do nothing
    returning 1
  )
  select count(*) into v_rider_inserted
  from inserted;

  with staff_source as (
    select
      cs.id as subject_id,
      cs.club_id,
      c.owner_user_id,
      coalesce(nullif(trim(cs.staff_name), ''), 'Unknown staff') as display_name,
      replace(cs.role_type::text, '_', ' ') as role_label,
      cs.birth_date,
      'club_staff'::text as source_table
    from public.club_staff cs
    left join public.clubs c
      on c.id = cs.club_id
     and c.deleted_at is null
    where cs.birth_date is not null
      and coalesce(cs.is_active, false) = true

    union all

    select
      sc.id as subject_id,
      null::uuid as club_id,
      null::uuid as owner_user_id,
      coalesce(nullif(trim(sc.staff_name), ''), 'Unknown staff') as display_name,
      replace(sc.role_type::text, '_', ' ') as role_label,
      sc.birth_date,
      'staff_candidates'::text as source_table
    from public.staff_candidates sc
    where sc.birth_date is not null
      and coalesce(sc.is_available, false) = true
  ),
  staff_rolls as (
    select
      ss.*,
      greatest(0, extract(year from age(v_effective_game_date, ss.birth_date))::integer) as age_years,
      public.get_retirement_band(
        'staff',
        greatest(0, extract(year from age(v_effective_game_date, ss.birth_date))::integer)
      ) as retirement_band,
      public.get_retirement_chance_bps(
        'staff',
        greatest(0, extract(year from age(v_effective_game_date, ss.birth_date))::integer)
      ) as retirement_chance_bps,
      ((abs(hashtext(ss.subject_id::text || ':retirement-roll:' || v_season::text)::bigint) % 10000) + 1)::integer as retirement_roll
    from staff_source ss
  ),
  inserted as (
    insert into public.retirement_decisions (
      subject_type,
      subject_id,
      club_id,
      owner_user_id,
      display_name,
      role_label,
      season_number,
      age_years,
      retirement_band,
      retirement_chance_bps,
      retirement_roll,
      announcement_game_date,
      effective_game_date,
      status,
      payload
    )
    select
      'staff',
      sr.subject_id,
      sr.club_id,
      sr.owner_user_id,
      sr.display_name,
      sr.role_label,
      v_season,
      sr.age_years,
      sr.retirement_band,
      sr.retirement_chance_bps,
      sr.retirement_roll,
      public.get_retirement_announcement_game_date(sr.birth_date, v_season, sr.subject_id),
      v_effective_game_date,
      'planned',
      jsonb_build_object(
        'source_table', sr.source_table,
        'birth_date', sr.birth_date,
        'effective_game_date', v_effective_game_date
      )
    from staff_rolls sr
    where sr.retirement_chance_bps > 0
      and sr.retirement_roll <= sr.retirement_chance_bps
    on conflict (subject_type, subject_id, season_number) do nothing
    returning 1
  )
  select count(*) into v_staff_inserted
  from inserted;

  return jsonb_build_object(
    'status', 'completed',
    'season_number', v_season,
    'effective_game_date', v_effective_game_date,
    'rider_decisions_created', v_rider_inserted,
    'staff_decisions_created', v_staff_inserted
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.announce_due_retirement_decisions()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_today date;
  v_decision record;
  v_announced_count integer := 0;
  v_notification_count integer := 0;
  v_title text;
  v_message text;
  v_action_url text;
begin
  v_today := public.get_current_game_date_date();

  for v_decision in
    select *
    from public.retirement_decisions rd
    where rd.status = 'planned'
      and rd.announcement_game_date <= v_today
    order by rd.announcement_game_date asc, rd.display_name asc
    for update skip locked
  loop
    update public.retirement_decisions
    set
      status = 'announced',
      announced_at = now()
    where id = v_decision.id;

    v_announced_count := v_announced_count + 1;

    if v_decision.owner_user_id is not null then
      v_title :=
        case
          when v_decision.subject_type = 'rider' then 'Rider retirement announced'
          else 'Staff retirement announced'
        end;

      v_message := format(
        '%s has decided to retire at the end of Season %s.',
        v_decision.display_name,
        v_decision.season_number
      );

      v_action_url :=
        case
          when v_decision.subject_type = 'rider' then '/dashboard/squad'
          else '/dashboard/staff'
        end;

      begin
        perform public.create_game_notification_for_user_checked(
          v_decision.owner_user_id,
          'RETIREMENT_ANNOUNCED',
          v_title,
          v_message,
          v_action_url,
          jsonb_build_object(
            'retirement_decision_id', v_decision.id,
            'subject_type', v_decision.subject_type,
            'subject_id', v_decision.subject_id,
            'club_id', v_decision.club_id,
            'display_name', v_decision.display_name,
            'role_label', v_decision.role_label,
            'season_number', v_decision.season_number,
            'age_years', v_decision.age_years,
            'retirement_band', v_decision.retirement_band,
            'announcement_game_date', v_decision.announcement_game_date,
            'effective_game_date', v_decision.effective_game_date
          )
        );

        v_notification_count := v_notification_count + 1;
      exception when others then
        raise notice 'Retirement announcement notification failed for decision %: %', v_decision.id, sqlerrm;
      end;
    end if;
  end loop;

  return jsonb_build_object(
    'status', 'completed',
    'game_date', v_today,
    'announced_count', v_announced_count,
    'notification_count', v_notification_count
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finalize_retirements_for_season(p_season_number integer, p_force boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare
  v_today date;
  v_effective_game_date date;
  v_owner record;

  v_roster_removed integer := 0;
  v_riders_marked_retired integer := 0;
  v_free_agents_removed integer := 0;
  v_club_staff_inactivated integer := 0;
  v_staff_candidates_removed integer := 0;
  v_decisions_finalized integer := 0;
  v_summary_notifications integer := 0;

  v_retired_riders jsonb := '[]'::jsonb;
  v_retired_staff jsonb := '[]'::jsonb;
  v_retired_rider_names text[] := array[]::text[];
  v_retired_staff_names text[] := array[]::text[];
  v_retired_riders_count integer := 0;
  v_retired_staff_count integer := 0;
begin
  if p_season_number is null then
    raise exception 'Season number is required.';
  end if;

  v_today := public.get_current_game_date_date();
  v_effective_game_date := make_date(1999 + p_season_number, 12, 31);

  if not p_force and v_today < v_effective_game_date then
    raise exception 'Cannot finalize Season % retirements before %. Current game date is %.',
      p_season_number, v_effective_game_date, v_today;
  end if;

  for v_owner in
    select
      rd.owner_user_id,
      string_agg(rd.display_name, ', ' order by rd.display_name)
        filter (where rd.subject_type = 'rider') as rider_names,
      string_agg(rd.display_name, ', ' order by rd.display_name)
        filter (where rd.subject_type = 'staff') as staff_names,
      jsonb_agg(
        jsonb_build_object(
          'id', rd.subject_id,
          'name', rd.display_name,
          'display_name', rd.display_name,
          'age', rd.age_years,
          'age_years', rd.age_years,
          'role', rd.role_label,
          'role_label', rd.role_label,
          'retirement_band', rd.retirement_band
        )
        order by rd.display_name
      ) filter (where rd.subject_type = 'rider') as riders,
      jsonb_agg(
        jsonb_build_object(
          'id', rd.subject_id,
          'name', rd.display_name,
          'display_name', rd.display_name,
          'age', rd.age_years,
          'age_years', rd.age_years,
          'role', rd.role_label,
          'role_label', rd.role_label,
          'retirement_band', rd.retirement_band
        )
        order by rd.display_name
      ) filter (where rd.subject_type = 'staff') as staff
    from public.retirement_decisions rd
    where rd.season_number = p_season_number
      and rd.status in ('planned', 'announced')
      and rd.owner_user_id is not null
    group by rd.owner_user_id
  loop
    begin
      v_retired_riders := coalesce(v_owner.riders, '[]'::jsonb);
      v_retired_staff := coalesce(v_owner.staff, '[]'::jsonb);

      select coalesce(array_agg(name_value order by name_value), array[]::text[])
      into v_retired_rider_names
      from (
        select nullif(trim(rider_item->>'display_name'), '') as name_value
        from jsonb_array_elements(coalesce(v_retired_riders, '[]'::jsonb)) as rider_item
      ) names
      where name_value is not null;

      select coalesce(array_agg(name_value order by name_value), array[]::text[])
      into v_retired_staff_names
      from (
        select nullif(trim(staff_item->>'display_name'), '') as name_value
        from jsonb_array_elements(coalesce(v_retired_staff, '[]'::jsonb)) as staff_item
      ) names
      where name_value is not null;

      v_retired_riders_count := jsonb_array_length(coalesce(v_retired_riders, '[]'::jsonb));
      v_retired_staff_count := jsonb_array_length(coalesce(v_retired_staff, '[]'::jsonb));

      perform public.create_game_notification_for_user_checked(
        v_owner.owner_user_id,
        'SEASON_RETIREMENTS_CONFIRMED',
        'Season retirements confirmed',
        format(
          'Season % retirements confirmed. Riders: %s. Staff: %s.',
          p_season_number,
          coalesce(v_owner.rider_names, 'None'),
          coalesce(v_owner.staff_names, 'None')
        ),
        '/dashboard/staff',
        jsonb_build_object(
          'season_number', p_season_number,
          'riders', coalesce(v_retired_riders, '[]'::jsonb),
          'staff', coalesce(v_retired_staff, '[]'::jsonb),
          'retired_rider_names', to_jsonb(v_retired_rider_names),
          'retired_staff_names', to_jsonb(v_retired_staff_names),
          'retired_riders_count', v_retired_riders_count,
          'retired_staff_count', v_retired_staff_count
        )
      );

      v_summary_notifications := v_summary_notifications + 1;
    exception when others then
      raise notice 'Season retirement summary notification failed for user %: %', v_owner.owner_user_id, sqlerrm;
    end;
  end loop;

  delete from public.club_riders cr
  using public.retirement_decisions rd
  where rd.subject_type = 'rider'
    and rd.subject_id = cr.rider_id
    and rd.season_number = p_season_number
    and rd.status in ('planned', 'announced');

  get diagnostics v_roster_removed = row_count;

  begin
    update public.riders r
    set availability_status = 'retired'
    where exists (
      select 1
      from public.retirement_decisions rd
      where rd.subject_type = 'rider'
        and rd.subject_id = r.id
        and rd.season_number = p_season_number
        and rd.status in ('planned', 'announced')
    );

    get diagnostics v_riders_marked_retired = row_count;
  exception when others then
    raise notice 'Could not mark riders availability_status as retired: %', sqlerrm;
    v_riders_marked_retired := 0;
  end;

  begin
    update public.rider_free_agents fa
    set status = 'retired'
    where exists (
      select 1
      from public.retirement_decisions rd
      where rd.subject_type = 'rider'
        and rd.subject_id = fa.rider_id
        and rd.season_number = p_season_number
        and rd.status in ('planned', 'announced')
    );

    get diagnostics v_free_agents_removed = row_count;
  exception when others then
    raise notice 'Could not mark rider_free_agents as retired. Trying expired instead: %', sqlerrm;

    begin
      update public.rider_free_agents fa
      set status = 'expired'
      where exists (
        select 1
        from public.retirement_decisions rd
        where rd.subject_type = 'rider'
          and rd.subject_id = fa.rider_id
          and rd.season_number = p_season_number
          and rd.status in ('planned', 'announced')
      );

      get diagnostics v_free_agents_removed = row_count;
    exception when others then
      raise notice 'Could not mark rider_free_agents as expired either: %', sqlerrm;
      v_free_agents_removed := 0;
    end;
  end;

  update public.club_staff cs
  set is_active = false
  where exists (
    select 1
    from public.retirement_decisions rd
    where rd.subject_type = 'staff'
      and rd.subject_id = cs.id
      and rd.season_number = p_season_number
      and rd.status in ('planned', 'announced')
      and rd.payload ->> 'source_table' = 'club_staff'
  );

  get diagnostics v_club_staff_inactivated = row_count;

  update public.staff_candidates sc
  set is_available = false
  where exists (
    select 1
    from public.retirement_decisions rd
    where rd.subject_type = 'staff'
      and rd.subject_id = sc.id
      and rd.season_number = p_season_number
      and rd.status in ('planned', 'announced')
      and rd.payload ->> 'source_table' = 'staff_candidates'
  );

  get diagnostics v_staff_candidates_removed = row_count;

  update public.retirement_decisions rd
  set
    status = 'finalized',
    finalized_at = now()
  where rd.season_number = p_season_number
    and rd.status in ('planned', 'announced');

  get diagnostics v_decisions_finalized = row_count;

  return jsonb_build_object(
    'status', 'completed',
    'season_number', p_season_number,
    'effective_game_date', v_effective_game_date,
    'decisions_finalized', v_decisions_finalized,
    'roster_removed', v_roster_removed,
    'riders_marked_retired', v_riders_marked_retired,
    'free_agents_removed', v_free_agents_removed,
    'club_staff_inactivated', v_club_staff_inactivated,
    'staff_candidates_removed', v_staff_candidates_removed,
    'summary_notifications', v_summary_notifications
  );
end;$function$
;

CREATE OR REPLACE FUNCTION public.run_retirement_daily_jobs()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_current_season integer;
  v_today date;
  v_generated jsonb;
  v_announced jsonb;
  v_finalize_current jsonb := jsonb_build_object('status', 'not_due');
  v_finalize_previous jsonb := jsonb_build_object('status', 'not_due');
begin
  select gs.season_number, public.get_current_game_date_date()
  into v_current_season, v_today
  from public.game_state gs
  where gs.id = true
  limit 1;

  if v_current_season is null or v_today is null then
    raise exception 'Game state is missing.';
  end if;

  v_generated := public.generate_retirement_decisions_for_season(v_current_season);
  v_announced := public.announce_due_retirement_decisions();

  -- Safety: if a previous season somehow was not finalized, finalize it after season change.
  if v_current_season > 1 then
    begin
      v_finalize_previous := public.finalize_retirements_for_season(v_current_season - 1, false);
    exception when others then
      v_finalize_previous := jsonb_build_object('status', 'skipped', 'reason', sqlerrm);
    end;
  end if;

  -- End of current season.
  if v_today >= make_date(1999 + v_current_season, 12, 31) then
    begin
      v_finalize_current := public.finalize_retirements_for_season(v_current_season, false);
    exception when others then
      v_finalize_current := jsonb_build_object('status', 'skipped', 'reason', sqlerrm);
    end;
  end if;

  return jsonb_build_object(
    'status', 'completed',
    'game_date', v_today,
    'season_number', v_current_season,
    'generated', v_generated,
    'announced', v_announced,
    'finalize_previous', v_finalize_previous,
    'finalize_current', v_finalize_current
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_run_retirement_daily_jobs()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Disabled intentionally.
  -- Retirement jobs now run once per game day through:
  -- process_daily_tick() -> run_retirement_daily_jobs()
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finalize_due_retirement_decisions()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare
  v_game_date date;
  v_season_count integer := 0;
  v_due_row record;
begin
  v_game_date := public.get_current_game_date_date();

  if v_game_date is null then
    raise exception 'Current game date not found.';
  end if;

  /*
    Finalize every retirement season where the effective date is due.
    This also protects you if the game ever skips past 31/12.

    Important:
    - finalize_retirements_for_season(...) must run first.
    - create_retirement_finalization_notifications(...) runs after riders are removed
      and staff are set inactive.
  */
  for v_due_row in
    select
      rd.season_number,
      min(rd.effective_game_date)::date as effective_game_date
    from public.retirement_decisions rd
    where rd.status in ('planned', 'announced')
      and rd.effective_game_date <= v_game_date
    group by rd.season_number
    order by rd.season_number
  loop
    perform public.finalize_retirements_for_season(
      v_due_row.season_number,
      true
    );

    perform public.create_retirement_finalization_notifications(
      v_due_row.season_number,
      v_due_row.effective_game_date
    );

    v_season_count := v_season_count + 1;
  end loop;

  return jsonb_build_object(
    'status', 'completed',
    'game_date', v_game_date,
    'finalized_season_count', v_season_count
  );
end;$function$
;

CREATE OR REPLACE FUNCTION public.apply_retirement_finalization_effects()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status='finalized' and old.status is distinct from new.status then
    if new.subject_type='rider' then
      delete from public.club_riders cr where cr.rider_id=new.subject_id;

      update public.riders r
      set availability_status='retired',
          unavailable_until=null,
          unavailable_reason=null
      where r.id=new.subject_id;

      update public.rider_contracts rc
      set status='terminated',
          notes_json=coalesce(rc.notes_json,'{}'::jsonb)||jsonb_build_object(
            'terminated_reason','retirement',
            'retirement_season',new.season_number,
            'retirement_effective_game_date',new.effective_game_date
          ),
          updated_at=now()
      where rc.rider_id=new.subject_id
        and rc.status='active';

      update public.rider_transfer_listings l
      set status='expired'
      where l.rider_id=new.subject_id and l.status in ('listed','club_accepted');

      update public.rider_transfer_offers o
      set status='expired'
      where o.rider_id=new.subject_id and o.status in ('open','club_accepted');

      update public.rider_transfer_negotiations n
      set status='expired'
      where n.rider_id=new.subject_id and n.status in ('open','accepted');

      update public.rider_free_agents fa
      set status='expired'
      where fa.rider_id=new.subject_id and fa.status='available';

    elsif new.subject_type='staff' then
      update public.club_staff cs
      set is_active=false
      where cs.id=new.subject_id
        and (new.club_id is null or cs.club_id=new.club_id);

      update public.staff_candidates sc
      set is_available=false
      where sc.id=new.subject_id
        and coalesce(new.payload->>'source_table','')='staff_candidates';
    end if;
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_retirement_finalization_notifications(p_season_number integer, p_effective_game_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_created_count integer := 0;
  v_group record;
  v_existing_notification_id bigint;
begin
  for v_group in
    select
      rd.club_id,
      rd.owner_user_id,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'display_name', rd.display_name,
            'role_label', rd.role_label,
            'age_years', rd.age_years,
            'retirement_band', rd.retirement_band
          )
          order by rd.display_name
        ) filter (where rd.subject_type = 'rider'),
        '[]'::jsonb
      ) as riders,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'display_name', rd.display_name,
            'role_label', rd.role_label,
            'age_years', rd.age_years,
            'retirement_band', rd.retirement_band
          )
          order by rd.display_name
        ) filter (where rd.subject_type = 'staff'),
        '[]'::jsonb
      ) as staff
    from public.retirement_decisions rd
    where rd.status = 'finalized'
      and rd.season_number = p_season_number
      and rd.effective_game_date = p_effective_game_date
      and rd.club_id is not null
      and rd.owner_user_id is not null
    group by rd.club_id, rd.owner_user_id
  loop
    select n.id
    into v_existing_notification_id
    from public.notifications n
    join public.notification_types nt on nt.id = n.type_id
    join public.user_notifications un on un.notification_id = n.id
    where nt.code = 'SEASON_RETIREMENTS_CONFIRMED'
      and un.user_id = v_group.owner_user_id
      and n.payload_json ->> 'club_id' = v_group.club_id::text
      and (n.payload_json ->> 'season_number')::integer = p_season_number
      and (n.payload_json ->> 'effective_game_date')::date = p_effective_game_date
    limit 1;

    if v_existing_notification_id is null then
      perform public.create_game_notification_for_user_checked(
        v_group.owner_user_id,
        'SEASON_RETIREMENTS_CONFIRMED',
        'Season retirements confirmed',
        'Season ' || p_season_number || ' retirements have been finalized. Open to review retired riders and staff.',
        '/dashboard/squad',
        jsonb_build_object(
          'club_id', v_group.club_id,
          'season_number', p_season_number,
          'effective_game_date', p_effective_game_date,
          'riders', v_group.riders,
          'staff', v_group.staff,
          'rider_count', jsonb_array_length(v_group.riders),
          'staff_count', jsonb_array_length(v_group.staff)
        )
      );

      v_created_count := v_created_count + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'status', 'completed',
    'season_number', p_season_number,
    'effective_game_date', p_effective_game_date,
    'created_count', v_created_count
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_get_contract_extension_quote_debug(p_user_id uuid, p_staff_id uuid, p_seasons integer)
 RETURNS TABLE(staff_id uuid, staff_name text, role_type text, current_salary_weekly integer, requested_salary_weekly integer, minimum_acceptable_salary_weekly integer, requested_raise_percent integer, target_contract_expires_at date, target_season_number integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_current_game_date date;
  v_staff public.club_staff%rowtype;
  v_club_tier text;
  v_quality_score numeric;
  v_requested_raise_percent integer;
  v_requested_salary integer;
  v_minimum_salary integer;
  v_target_contract_expires_at date;
  v_base_year integer;
  v_target_season_number integer;
begin
  if p_user_id is null then
    raise exception 'Debug user id is required';
  end if;

  if p_seasons not in (1, 2) then
    raise exception 'p_seasons must be 1 or 2';
  end if;

  v_current_game_date := public.get_current_game_date_date();

  select cs.*
  into v_staff
  from public.club_staff cs
  join public.clubs c on c.id = cs.club_id
  where cs.id = p_staff_id
    and cs.is_active = true
    and c.owner_user_id = p_user_id
    and c.deleted_at is null
  limit 1;

  if not found then
    raise exception 'Active staff member not found for this user';
  end if;

  select c.club_tier
  into v_club_tier
  from public.clubs c
  where c.id = v_staff.club_id;

  v_quality_score :=
    coalesce(v_staff.expertise, 0) * 0.30 +
    coalesce(v_staff.experience, 0) * 0.15 +
    coalesce(v_staff.potential, 0) * 0.10 +
    coalesce(v_staff.leadership, 0) * 0.15 +
    coalesce(v_staff.efficiency, 0) * 0.25 +
    coalesce(v_staff.loyalty, 0) * 0.05;

  v_requested_raise_percent :=
    case
      when v_quality_score >= 85 then 10
      when v_quality_score >= 75 then 7
      when v_quality_score >= 65 then 4
      when v_quality_score >= 55 then 2
      else 0
    end;

  v_requested_raise_percent :=
    v_requested_raise_percent +
    case coalesce(v_club_tier, '')
      when 'worldteam' then 3
      when 'proteam' then 2
      when 'continental' then 1
      else 0
    end;

  if p_seasons = 2 then
    v_requested_raise_percent := greatest(0, v_requested_raise_percent - 1);
  end if;

  v_requested_salary :=
    greatest(
      v_staff.salary_weekly,
      round(v_staff.salary_weekly * (1 + v_requested_raise_percent / 100.0))::int
    );

  v_minimum_salary :=
    greatest(
      v_staff.salary_weekly,
      round(v_staff.salary_weekly * (1 + greatest(v_requested_raise_percent - 3, 0) / 100.0))::int
    );

  if v_staff.contract_expires_at is not null
     and v_staff.contract_expires_at >= v_current_game_date then
    v_base_year := extract(year from v_staff.contract_expires_at)::int;
  else
    v_base_year := extract(year from v_current_game_date)::int;
  end if;

  v_target_contract_expires_at := make_date(v_base_year + p_seasons, 12, 31);
  v_target_season_number := extract(year from v_target_contract_expires_at)::int - 1999;

  return query
  select
    v_staff.id,
    v_staff.staff_name,
    v_staff.role_type,
    v_staff.salary_weekly,
    v_requested_salary,
    v_minimum_salary,
    v_requested_raise_percent,
    v_target_contract_expires_at,
    v_target_season_number;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.can_complete_ai_ai_transfer_deal_today()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_limit integer;
  v_completed_today integer;
begin
  select coalesce(transfer_ai_ai_completed_deal_daily_limit, 10)
  into v_limit
  from public.market_ai_config
  limit 1;

  v_completed_today := public.count_ai_ai_completed_transfer_deals_on_date(
    public.get_current_game_date_date()
  );

  return v_completed_today < coalesce(v_limit, 10);
end;
$function$
;

