CREATE OR REPLACE FUNCTION public.trg_guard_ai_transfer_offer_daily_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_today date;
  v_limit integer;
  v_existing_ai_offers integer;
  v_buyer_is_ai boolean;
begin
  /*
    Final safety guard for AI transfer offers.

    Purpose:
    - Prevent duplicate AI offer batches on the same game date.
    - Works no matter which job/function tries to insert the offer.
    - User-created offers are NOT affected.
  */

  v_today := coalesce(
    new.offered_on_game_date::date,
    public.get_market_game_date()
  );

  select coalesce(cfg.transfer_buyer_daily_limit, 60)
  into v_limit
  from public.get_market_ai_config() cfg
  limit 1;

  select coalesce(c.is_ai, false)
  into v_buyer_is_ai
  from public.clubs c
  where c.id = new.buyer_club_id
  limit 1;

  -- Human/user buyer offers are not capped by this guard.
  if coalesce(v_buyer_is_ai, false) = false then
    return new;
  end if;

  -- Serialize all AI-offer inserts for this game date.
  perform pg_advisory_xact_lock(
    hashtext('ai_transfer_offer_daily_insert_cap:' || v_today::text)
  );

  select count(*)
  into v_existing_ai_offers
  from public.rider_transfer_offers o
  join public.clubs buyer on buyer.id = o.buyer_club_id
  where buyer.is_ai = true
    and o.offered_on_game_date::date = v_today;

  if v_existing_ai_offers >= v_limit then
    -- Silently skip the insert instead of creating another duplicate batch.
    return null;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_get_contract_extension_quote(p_staff_id uuid, p_seasons integer)
 RETURNS TABLE(staff_id uuid, staff_name text, role_type text, current_salary_weekly integer, requested_salary_weekly integer, minimum_acceptable_salary_weekly integer, requested_raise_percent integer, target_contract_expires_at date, target_season_number integer, interest_score integer, interest_level text, willingness_status text, decision_reason text, salary_reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$declare
  v_user_id uuid;
  v_current_game_date date;
  v_staff public.club_staff%rowtype;
  v_club_tier text;
  v_quality_score numeric;
  v_tier_modifier integer := 0;
  v_loyalty_modifier integer := 0;
  v_age_modifier integer := 0;
  v_contract_modifier integer := 0;
  v_skill_raise integer := 0;
  v_requested_raise_percent integer;
  v_requested_salary integer;
  v_minimum_salary integer;
  v_interest_score integer;
  v_interest_level text;
  v_willingness_status text;
  v_decision_reason text;
  v_salary_reason text;
  v_target_contract_expires_at date;
  v_base_year integer;
  v_target_season_number integer;
  v_age integer;
  v_days_left integer;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'staff_get_contract_extension_quote: user not authenticated';
  end if;

  if p_seasons not in (1, 2) then
    raise exception 'staff_get_contract_extension_quote: p_seasons must be 1 or 2';
  end if;

  v_current_game_date := public.get_current_game_date_date();

  if v_current_game_date is null then
    raise exception 'staff_get_contract_extension_quote: could not resolve current game date';
  end if;

  select cs.*
  into v_staff
  from public.club_staff cs
  join public.clubs c
    on c.id = cs.club_id
  where cs.id = p_staff_id
    and cs.is_active = true
    and c.owner_user_id = v_user_id
    and c.deleted_at is null
  limit 1;

  if not found then
    raise exception 'staff_get_contract_extension_quote: active staff member not found for current user';
  end if;

  select lower(coalesce(c.club_tier::text, ''))
  into v_club_tier
  from public.clubs c
  where c.id = v_staff.club_id
  limit 1;

  v_quality_score :=
    coalesce(v_staff.expertise, 0) * 0.30
    + coalesce(v_staff.experience, 0) * 0.15
    + coalesce(v_staff.potential, 0) * 0.10
    + coalesce(v_staff.leadership, 0) * 0.15
    + coalesce(v_staff.efficiency, 0) * 0.25
    + coalesce(v_staff.loyalty, 0) * 0.05;

  v_age :=
    case
      when v_staff.birth_date is null then null
      else extract(year from age(v_current_game_date, v_staff.birth_date))::int
    end;

  v_days_left :=
    case
      when v_staff.contract_expires_at is null then 0
      else (v_staff.contract_expires_at - v_current_game_date)
    end;

  v_tier_modifier :=
    case
      when v_club_tier in ('worldteam', 'world_team', 'world tour', 'worldtour') then 15
      when v_club_tier in ('proteam', 'pro_team', 'pro') then 8
      when v_club_tier in ('continental', 'conti') then 2
      else 0
    end;

  v_loyalty_modifier :=
    case
      when coalesce(v_staff.loyalty, 0) >= 80 then 15
      when coalesce(v_staff.loyalty, 0) >= 65 then 8
      when coalesce(v_staff.loyalty, 0) >= 50 then 2
      when coalesce(v_staff.loyalty, 0) >= 35 then -8
      else -15
    end;

  v_age_modifier :=
    case
      when v_age is null then 0
      when v_age >= 64 then -8
      when v_age >= 58 then -3
      when v_age <= 35 then 5
      else 0
    end;

  v_contract_modifier :=
    case
      when v_days_left <= 30 then 8
      when v_days_left <= 90 then 4
      when v_days_left >= 365 then -4
      else 0
    end;

  v_interest_score :=
    greatest(
      0,
      least(
        100,
        round(
          45
          + v_tier_modifier
          + v_loyalty_modifier
          + v_age_modifier
          + v_contract_modifier
          + ((v_quality_score - 55) * 0.25)
        )::int
      )
    );

  v_interest_level :=
    case
      when v_interest_score >= 80 then 'very_interested'
      when v_interest_score >= 65 then 'interested'
      when v_interest_score >= 45 then 'open_to_talk'
      when v_interest_score >= 30 then 'uncertain'
      else 'unwilling'
    end;

  v_willingness_status :=
    case
      when v_interest_score < 30 then 'unwilling'
      when v_interest_score < 45 then 'hard_to_convince'
      else 'willing_to_negotiate'
    end;

  v_skill_raise :=
    case
      when v_quality_score >= 85 then 12
      when v_quality_score >= 75 then 9
      when v_quality_score >= 65 then 6
      when v_quality_score >= 55 then 3
      else 1
    end;

  v_requested_raise_percent :=
    v_skill_raise
    + case
        when v_interest_score < 45 then 5
        when v_interest_score < 60 then 2
        when v_interest_score >= 80 then -1
        else 0
      end;

  v_requested_raise_percent :=
    v_requested_raise_percent
    + case v_club_tier::text
        when 'worldteam' then 3
        when 'proteam' then 2
        when 'continental' then 1
        else 0
      end;

  if p_seasons = 2 then
    v_requested_raise_percent := greatest(0, v_requested_raise_percent - 1);
  end if;

  v_requested_salary :=
    greatest(
      v_staff.salary_weekly,
      round(v_staff.salary_weekly * (1 + (v_requested_raise_percent / 100.0)))::int
    );

  v_minimum_salary :=
    greatest(
      v_staff.salary_weekly,
      round(
        v_staff.salary_weekly
        * (1 + (greatest(v_requested_raise_percent - 4, 0) / 100.0))
      )::int
    );

  v_decision_reason :=
    case
      when v_interest_score < 30 then
        v_staff.staff_name || ' is currently not interested in extending the contract.'
      when v_interest_score < 45 then
        v_staff.staff_name || ' is uncertain and would need a strong offer to stay.'
      when v_interest_score < 65 then
        v_staff.staff_name || ' is open to talks but will compare the offer with his role and club situation.'
      when v_interest_score < 80 then
        v_staff.staff_name || ' is interested in staying if the salary offer is fair.'
      else
        v_staff.staff_name || ' is very interested in continuing with the club.'
    end;

  v_salary_reason :=
    case
      when v_quality_score >= 75 then 'High staff quality increases salary expectations.'
      when v_interest_score < 45 then 'Lower interest means the staff member wants extra compensation.'
      when coalesce(v_staff.loyalty, 0) >= 70 then 'Good loyalty keeps salary expectations more reasonable.'
      else 'Salary request is based on current wage, role quality, club tier and loyalty.'
    end;

  if v_staff.contract_expires_at is not null
     and v_staff.contract_expires_at >= v_current_game_date then
    v_base_year := extract(year from v_staff.contract_expires_at)::int;
  else
    v_base_year := extract(year from v_current_game_date)::int;
  end if;

  v_target_contract_expires_at := make_date(v_base_year + p_seasons, 12, 31);
  v_target_season_number := extract(year from v_target_contract_expires_at)::int - 1999;

  return query
  select
    v_staff.id,
    v_staff.staff_name,
    v_staff.role_type,
    v_staff.salary_weekly,
    v_requested_salary,
    v_minimum_salary,
    v_requested_raise_percent,
    v_target_contract_expires_at,
    v_target_season_number,
    v_interest_score,
    v_interest_level,
    v_willingness_status,
    v_decision_reason,
    v_salary_reason;
end;$function$
;

CREATE OR REPLACE FUNCTION public.extend_club_staff_contract(p_staff_id uuid, p_seasons integer, p_salary_weekly integer)
 RETURNS TABLE(staff_id uuid, staff_name text, new_salary_weekly integer, new_contract_expires_at date, new_season_number integer, decision_status text, decision_message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
  v_quote record;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'You must be signed in to extend staff contracts.';
  end if;

  if p_seasons not in (1, 2) then
    raise exception 'Please choose a valid contract length.';
  end if;

  if p_salary_weekly is null or p_salary_weekly <= 0 then
    raise exception 'Please enter a valid weekly salary.';
  end if;

  select *
  into v_quote
  from public.staff_get_contract_extension_quote(p_staff_id, p_seasons);

  if v_quote.staff_id is null then
    raise exception 'No contract quote is available for this staff member.';
  end if;

  if v_quote.willingness_status = 'unwilling' then
    return query
    select
      v_quote.staff_id,
      v_quote.staff_name,
      v_quote.current_salary_weekly,
      null::date,
      null::integer,
      'unwilling'::text,
      (v_quote.staff_name || ' is not interested in extending the contract right now.')::text;
    return;
  end if;

  if p_salary_weekly < v_quote.minimum_acceptable_salary_weekly then
    return query
    select
      v_quote.staff_id,
      v_quote.staff_name,
      v_quote.current_salary_weekly,
      null::date,
      null::integer,
      'rejected'::text,
      (
        v_quote.staff_name ||
        ' rejected the offer. He wants at least $' ||
        v_quote.minimum_acceptable_salary_weekly::text ||
        ' per week.'
      )::text;
    return;
  end if;

  if p_salary_weekly < v_quote.requested_salary_weekly then
    return query
    select
      v_quote.staff_id,
      v_quote.staff_name,
      v_quote.current_salary_weekly,
      null::date,
      null::integer,
      'countered'::text,
      (
        v_quote.staff_name ||
        ' is interested, but wants closer to $' ||
        v_quote.requested_salary_weekly::text ||
        ' per week.'
      )::text;
    return;
  end if;

  update public.club_staff
  set
    salary_weekly = p_salary_weekly,
    contract_expires_at = v_quote.target_contract_expires_at,
    updated_at = now()
  where id = p_staff_id
    and is_active = true;

  return query
  select
    cs.id,
    cs.staff_name,
    cs.salary_weekly,
    cs.contract_expires_at,
    extract(year from cs.contract_expires_at)::int - 1999,
    'accepted'::text,
    (
      cs.staff_name ||
      ' accepted the new contract until Season ' ||
      (extract(year from cs.contract_expires_at)::int - 1999)::text ||
      '.'
    )::text
  from public.club_staff cs
  where cs.id = p_staff_id
  limit 1;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_training_camp_bookings_fill_snapshots()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_camp record;
begin
  select
    c.name,
    c.country_code,
    c.region_name
  into v_camp
  from public.training_camp_catalog c
  where c.id = new.camp_id
  limit 1;

  new.camp_name := coalesce(new.camp_name, v_camp.name);
  new.country_code := coalesce(new.country_code, new.country_code_snapshot, v_camp.country_code);
  new.region_name := coalesce(new.region_name, v_camp.region_name);
  new.staff_count := coalesce(new.staff_count, 0);
  new.participants_count := coalesce(new.participants_count, 0);
  new.charged_participants_count := greatest(
    coalesce(new.charged_participants_count, 0),
    coalesce(new.participants_count, 0) + coalesce(new.staff_count, 0)
  );
  new.notes := coalesce(new.notes, '{}'::jsonb);

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.training_camp_staff_boost(p_role_type text, p_expertise integer, p_experience integer, p_potential integer, p_leadership integer, p_efficiency integer, p_loyalty integer)
 RETURNS TABLE(boost_label text, boost_metadata jsonb)
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_score integer;
  v_bonus integer;
begin
  if p_role_type = 'head_coach' then
    v_score := round((coalesce(p_expertise, 0) + coalesce(p_potential, 0) + coalesce(p_efficiency, 0)) / 3.0);
    v_bonus := greatest(2, floor(v_score / 16.0)::integer);

    return query
    select
      format('+%s%% rider development support', v_bonus),
      jsonb_build_object(
        'role_type', p_role_type,
        'development_bonus_pct', v_bonus,
        'source_score', v_score
      );
    return;
  end if;

  if p_role_type = 'team_doctor' then
    v_score := round((coalesce(p_expertise, 0) + coalesce(p_experience, 0) + coalesce(p_efficiency, 0)) / 3.0);
    v_bonus := greatest(1, floor(v_score / 24.0)::integer);

    return query
    select
      format('+%s recovery support', v_bonus),
      jsonb_build_object(
        'role_type', p_role_type,
        'recovery_bonus', v_bonus,
        'health_risk_reduction_pct', greatest(2, floor(v_score / 18.0)::integer),
        'source_score', v_score
      );
    return;
  end if;

  if p_role_type = 'mechanic' then
    v_score := round((coalesce(p_expertise, 0) + coalesce(p_experience, 0) + coalesce(p_efficiency, 0)) / 3.0);
    v_bonus := greatest(2, floor(v_score / 18.0)::integer);

    return query
    select
      format('-%s%% mechanical issue risk', v_bonus),
      jsonb_build_object(
        'role_type', p_role_type,
        'mechanical_risk_reduction_pct', v_bonus,
        'source_score', v_score
      );
    return;
  end if;

  if p_role_type = 'sport_director' then
    v_score := round((coalesce(p_leadership, 0) + coalesce(p_experience, 0) + coalesce(p_efficiency, 0)) / 3.0);
    v_bonus := greatest(1, floor(v_score / 20.0)::integer);

    return query
    select
      format('+%s%% camp organization support', v_bonus),
      jsonb_build_object(
        'role_type', p_role_type,
        'organization_bonus_pct', v_bonus,
        'morale_support_pct', greatest(1, floor(v_score / 25.0)::integer),
        'source_score', v_score
      );
    return;
  end if;

  return query
  select
    'No camp boost',
    jsonb_build_object(
      'role_type', p_role_type,
      'development_bonus_pct', 0,
      'recovery_bonus', 0
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_training_camp_staff_boost_summary(p_booking_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_result jsonb;
begin
  select jsonb_build_object(
    'staff_count', count(*),
    'development_bonus_pct',
      coalesce(sum((b.boost_metadata ->> 'development_bonus_pct')::numeric), 0),
    'recovery_bonus',
      coalesce(sum((b.boost_metadata ->> 'recovery_bonus')::integer), 0),
    'health_risk_reduction_pct',
      coalesce(sum((b.boost_metadata ->> 'health_risk_reduction_pct')::numeric), 0),
    'mechanical_risk_reduction_pct',
      coalesce(sum((b.boost_metadata ->> 'mechanical_risk_reduction_pct')::numeric), 0),
    'organization_bonus_pct',
      coalesce(sum((b.boost_metadata ->> 'organization_bonus_pct')::numeric), 0),
    'boosts',
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'staff_id', a.staff_id,
            'staff_name', a.staff_name_snapshot,
            'role_type', a.role_type,
            'boost_label', a.boost_label,
            'boost_metadata', a.boost_metadata
          )
          order by a.role_type, a.staff_name_snapshot
        ),
        '[]'::jsonb
      )
  )
  into v_result
  from public.training_camp_staff_assignments a
  cross join lateral (
    select a.boost_metadata
  ) b
  where a.booking_id = p_booking_id;

  return coalesce(
    v_result,
    jsonb_build_object(
      'staff_count', 0,
      'development_bonus_pct', 0,
      'recovery_bonus', 0,
      'health_risk_reduction_pct', 0,
      'mechanical_risk_reduction_pct', 0,
      'organization_bonus_pct', 0,
      'boosts', '[]'::jsonb
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_apply_training_camp_staff_boosts()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_booking_id uuid;
  v_summary jsonb;
  v_base_development numeric;
  v_development_bonus_pct numeric;
  v_recovery_bonus integer;
begin
  if coalesce(new.source, '') <> 'training_camp'
     and coalesce(new.activity_type, '') <> 'training_camp' then
    return new;
  end if;

  if new.metadata is null or not (new.metadata ? 'booking_id') then
    return new;
  end if;

  begin
    v_booking_id := (new.metadata ->> 'booking_id')::uuid;
  exception when others then
    return new;
  end;

  v_summary := public.get_training_camp_staff_boost_summary(v_booking_id);
  v_development_bonus_pct := coalesce((v_summary ->> 'development_bonus_pct')::numeric, 0);
  v_recovery_bonus := coalesce((v_summary ->> 'recovery_bonus')::integer, 0);

  v_base_development := coalesce(
    nullif(new.metadata ->> 'base_development_before_staff', '')::numeric,
    nullif(new.metadata ->> 'development_value_base', '')::numeric,
    0
  );

  new.metadata :=
    coalesce(new.metadata, '{}'::jsonb)
    || jsonb_build_object(
      'camp_staff_summary', v_summary,
      'camp_staff_count', coalesce((v_summary ->> 'staff_count')::integer, 0),
      'base_development_before_staff', v_base_development
    );

  if coalesce((new.metadata ->> 'development_eligible')::boolean, true) = true
     and v_base_development > 0 then
    new.metadata :=
      new.metadata
      || jsonb_build_object(
        'development_value_base',
        round((v_base_development * (1 + (v_development_bonus_pct / 100.0)))::numeric, 4),
        'staff_development_bonus_pct',
        v_development_bonus_pct
      );
  end if;

  if coalesce(new.participated, false) = true and v_recovery_bonus > 0 then
    new.recovery_bonus := coalesce(new.recovery_bonus, 0) + least(v_recovery_bonus, 2);
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_available_training_camp_staff(p_club_id uuid, p_start_date date DEFAULT NULL::date, p_days integer DEFAULT 7)
 RETURNS TABLE(staff_id uuid, club_id uuid, club_name text, staff_name text, role_type text, role_label text, specialization text, team_scope text, overall integer, salary_weekly integer, on_active_course boolean, overlapping_booking_id uuid, availability_status text, block_reason text, boost_label text, boost_metadata jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid;
  v_owner_user_id uuid;
  v_family_club_ids uuid[];
  v_start date;
  v_end date;
begin
  v_uid := auth.uid();

  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  select c.owner_user_id
  into v_owner_user_id
  from public.clubs c
  where c.id = p_club_id
  limit 1;

  if v_owner_user_id is null then
    raise exception 'Club not found';
  end if;

  if v_owner_user_id <> v_uid
     and not exists (
       select 1
       from public.club_memberships cm
       where cm.club_id = p_club_id
         and cm.user_id = v_uid
     ) then
    raise exception 'Not allowed';
  end if;

  select coalesce(array_agg(c.id), array[p_club_id]::uuid[])
  into v_family_club_ids
  from public.clubs c
  where c.owner_user_id = v_owner_user_id
    and c.deleted_at is null
    and coalesce(c.club_type, 'main') in ('main', 'developing');

  v_start := coalesce(p_start_date, public.get_current_game_date_date()) - 1;
  v_end := coalesce(p_start_date, public.get_current_game_date_date()) + greatest(coalesce(p_days, 7), 1);

  return query
  with staff_base as (
    select
      cs.id as staff_id,
      cs.club_id,
      c.name as club_name,
      cs.staff_name,
      cs.role_type,
      case cs.role_type
        when 'head_coach' then 'Head Coach'
        when 'team_doctor' then 'Team Doctor'
        when 'mechanic' then 'Mechanic'
        when 'sport_director' then 'Sport Director'
        else initcap(replace(cs.role_type, '_', ' '))
      end as role_label,
      cs.specialization,
      cs.team_scope,
      round(
        (
          cs.expertise
          + cs.experience
          + cs.potential
          + cs.leadership
          + cs.efficiency
          + cs.loyalty
        ) / 6.0
      )::integer as overall,
      cs.salary_weekly,
      cs.expertise,
      cs.experience,
      cs.potential,
      cs.leadership,
      cs.efficiency,
      cs.loyalty,
      exists (
        select 1
        from public.staff_courses sc
        where sc.staff_id = cs.id
          and sc.status = 'active'
      ) as on_active_course,
      (
        select b.id
        from public.training_camp_staff_assignments a
        join public.training_camp_bookings b
          on b.id = a.booking_id
        where a.staff_id = cs.id
          and b.status in ('planned', 'active')
          and v_start <= (b.end_date + 1)
          and (b.start_date - 1) <= v_end
        order by b.start_date
        limit 1
      ) as overlapping_booking_id
    from public.club_staff cs
    join public.clubs c on c.id = cs.club_id
    where cs.club_id = any(v_family_club_ids)
      and cs.is_active = true
      and cs.role_type in ('head_coach', 'team_doctor', 'mechanic', 'sport_director')
  )
  select
    sb.staff_id,
    sb.club_id,
    sb.club_name,
    sb.staff_name,
    sb.role_type,
    sb.role_label,
    sb.specialization,
    sb.team_scope,
    sb.overall,
    sb.salary_weekly,
    sb.on_active_course,
    sb.overlapping_booking_id,
    case
      when sb.on_active_course then 'unavailable'
      when sb.overlapping_booking_id is not null then 'unavailable'
      else 'available'
    end as availability_status,
    case
      when sb.on_active_course then 'Currently on a staff course'
      when sb.overlapping_booking_id is not null then 'Already assigned to an overlapping camp'
      else null
    end as block_reason,
    boost.boost_label,
    boost.boost_metadata
  from staff_base sb
  cross join lateral public.training_camp_staff_boost(
    sb.role_type,
    sb.expertise,
    sb.experience,
    sb.potential,
    sb.leadership,
    sb.efficiency,
    sb.loyalty
  ) boost
  order by
    case sb.role_type
      when 'head_coach' then 1
      when 'team_doctor' then 2
      when 'mechanic' then 3
      when 'sport_director' then 4
      else 99
    end,
    sb.staff_name;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_training_camp_quote_v2(p_club_id uuid, p_camp_id uuid, p_start_date date, p_days integer, p_rider_ids uuid[], p_staff_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS TABLE(camp_id uuid, camp_name text, city_name text, camp_country_code text, camp_region_name text, camp_type text, stars smallint, club_id uuid, club_country_code text, club_region_name text, participants_count integer, days_count integer, weather_state text, weather_score integer, training_modifier numeric, missed_day_chance integer, travel_per_rider integer, travel_total integer, accommodation_total integer, camp_fee_total integer, logistics_total integer, total_cost integer, per_rider_total integer, warnings jsonb, riders_count integer, staff_count integer, charged_participants_count integer)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_camp public.training_camp_catalog%rowtype;
  v_club_country_code text;
  v_club_region text;
  v_owner_user_id uuid;
  v_family_club_ids uuid[];
  v_riders_count integer := 0;
  v_staff_count integer := 0;
  v_charged_count integer := 0;

  v_weather_state text;
  v_weather_score integer;
  v_training_modifier numeric;
  v_missed_day_chance integer;

  v_travel_per_rider integer := 0;
  v_travel_total integer := 0;
  v_accommodation_total integer := 0;
  v_camp_fee_total integer := 0;
  v_logistics_total integer := 500;
  v_total_cost integer := 0;
  v_per_rider_total integer := 0;

  v_warnings jsonb := '[]'::jsonb;
  v_policy record;
  v_base_logistics_total integer := 500;
  v_start date;
  v_end date;
begin
  if p_days not in (7, 10, 14) then
    raise exception 'Training camp days must be 7, 10, or 14';
  end if;

  select *
  into v_camp
  from public.training_camp_catalog
  where id = p_camp_id
    and is_active = true
  limit 1;

  if not found then
    raise exception 'Training camp not found or inactive';
  end if;

  select c.country_code, c.owner_user_id
  into v_club_country_code, v_owner_user_id
  from public.clubs c
  where c.id = p_club_id
  limit 1;

  if v_club_country_code is null then
    raise exception 'Club not found or club country is missing';
  end if;

  select coalesce(array_agg(c.id), array[p_club_id]::uuid[])
  into v_family_club_ids
  from public.clubs c
  where c.owner_user_id = v_owner_user_id
    and c.deleted_at is null
    and coalesce(c.club_type, 'main') in ('main', 'developing');

  v_start := p_start_date - 1;
  v_end := p_start_date + p_days;

  select count(*)
  into v_riders_count
  from (
    select distinct unnest(coalesce(p_rider_ids, '{}'::uuid[])) as rider_id
  ) x;

  select count(*)
  into v_staff_count
  from (
    select distinct unnest(coalesce(p_staff_ids, '{}'::uuid[])) as staff_id
  ) x
  join public.club_staff cs
    on cs.id = x.staff_id
   and cs.club_id = any(v_family_club_ids)
   and cs.is_active = true
   and cs.role_type in ('head_coach', 'team_doctor', 'mechanic', 'sport_director')
  where not exists (
    select 1
    from public.staff_courses sc
    where sc.staff_id = cs.id
      and sc.status = 'active'
  )
  and not exists (
    select 1
    from public.training_camp_staff_assignments a
    join public.training_camp_bookings b
      on b.id = a.booking_id
    where a.staff_id = cs.id
      and b.status in ('planned', 'active')
      and v_start <= (b.end_date + 1)
      and (b.start_date - 1) <= v_end
  );

  v_charged_count := v_riders_count + v_staff_count;
  v_club_region := public.get_country_region(v_club_country_code);

  select
    ws.weather_state,
    ws.weather_score,
    ws.training_modifier,
    ws.missed_day_chance
  into
    v_weather_state,
    v_weather_score,
    v_training_modifier,
    v_missed_day_chance
  from public.get_training_camp_weather_state(
    v_camp.country_code,
    p_start_date,
    v_camp.preferred_weeks,
    v_camp.risky_weeks,
    v_camp.closed_weeks,
    v_camp.altitude_category
  ) ws;

  if upper(v_club_country_code) = upper(v_camp.country_code) then
    v_travel_per_rider := 80;
  elsif v_club_region = v_camp.region_name then
    v_travel_per_rider := 200;
  elsif (
    (v_club_region = 'Europe' and v_camp.region_name in ('Africa', 'Middle East')) or
    (v_camp.region_name = 'Europe' and v_club_region in ('Africa', 'Middle East')) or
    (v_club_region = 'North America' and v_camp.region_name = 'South America') or
    (v_club_region = 'South America' and v_camp.region_name = 'North America') or
    (v_club_region = 'Asia' and v_camp.region_name = 'Middle East') or
    (v_club_region = 'Middle East' and v_camp.region_name = 'Asia')
  ) then
    v_travel_per_rider := 450;
  elsif v_club_region = 'Oceania' or v_camp.region_name = 'Oceania' then
    v_travel_per_rider := 1200;
  else
    v_travel_per_rider := 850;
  end if;

  select *
  into v_policy
  from public.get_club_team_policy_quote_effects(p_club_id)
  limit 1;

  v_travel_per_rider :=
    round(v_travel_per_rider::numeric * coalesce(v_policy.travel_cost_modifier, 1.00))::integer;

  v_travel_total :=
    (v_travel_per_rider * v_charged_count)
    + coalesce(v_policy.flight_trip_cost, 0)
    + coalesce(v_policy.ground_transport_cost, 0);

  v_accommodation_total :=
    round(
      (
        (v_camp.base_accommodation_per_day * v_camp.location_cost_index)
        * p_days
        * v_charged_count
      )::numeric
      * coalesce(v_policy.accommodation_cost_modifier, 1.00)
    )::integer;

  v_camp_fee_total :=
    round(
      (v_camp.base_camp_fee_per_day * v_camp.location_cost_index)
      * p_days
      * v_charged_count
    )::integer;

  v_logistics_total :=
    round(
      (
        v_base_logistics_total
        + coalesce(v_policy.logistics_weekly_cost, 0)
        + coalesce(v_policy.vehicle_cost, 0)
      )::numeric
      * coalesce(v_policy.logistics_cost_modifier, 1.00)
    )::integer;

  v_total_cost :=
    v_travel_total
    + v_accommodation_total
    + v_camp_fee_total
    + v_logistics_total;

  if v_charged_count > 0 then
    v_per_rider_total := ceil(v_total_cost::numeric / v_charged_count)::integer;
  else
    v_per_rider_total := 0;
  end if;

  if v_riders_count < 5 then
    v_warnings := v_warnings || jsonb_build_array('Minimum 5 riders are required to book a training camp.');
  end if;

  if v_staff_count = 0 then
    v_warnings := v_warnings || jsonb_build_array('No staff selected. The camp will run without staff boosts.');
  end if;

  if v_weather_state = 'mixed' then
    v_warnings := v_warnings || jsonb_build_array('Weather conditions may disrupt some training days.');
  elsif v_weather_state = 'poor' then
    v_warnings := v_warnings || jsonb_build_array('Weather conditions are poor and training quality will be heavily reduced.');
  elsif v_weather_state = 'unavailable' then
    v_warnings := v_warnings || jsonb_build_array('This camp is unavailable for the selected start week.');
  end if;

  return query
  select
    v_camp.id,
    v_camp.name,
    v_camp.city_name,
    v_camp.country_code,
    v_camp.region_name,
    v_camp.camp_type,
    v_camp.stars,
    p_club_id,
    v_club_country_code,
    v_club_region,
    v_charged_count,
    p_days,
    v_weather_state,
    v_weather_score,
    v_training_modifier,
    v_missed_day_chance,
    v_travel_per_rider,
    v_travel_total,
    v_accommodation_total,
    v_camp_fee_total,
    v_logistics_total,
    v_total_cost,
    v_per_rider_total,
    v_warnings,
    v_riders_count,
    v_staff_count,
    v_charged_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_training_camp_booking_v2(p_club_id uuid, p_camp_id uuid, p_start_date date, p_days integer, p_rider_ids uuid[], p_staff_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS TABLE(is_valid boolean, riders_count integer, staff_count integer, charged_participants_count integer, weather_state text, validation_errors jsonb, validation_warnings jsonb, blocked_riders jsonb, blocked_staff jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_errors jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_blocked_riders jsonb := '[]'::jsonb;
  v_blocked_staff jsonb := '[]'::jsonb;

  v_current_game_date date;

  v_owner_user_id uuid;
  v_family_club_ids uuid[] := array[p_club_id];

  v_selected_rider_ids uuid[] := '{}'::uuid[];
  v_selected_staff_ids uuid[] := '{}'::uuid[];
  v_overlap_rider_ids uuid[] := '{}'::uuid[];

  v_riders_count integer := 0;
  v_staff_count integer := 0;

  v_start date;
  v_end date;

  v_camp record;
  v_weather_score integer;
  v_training_modifier numeric;
  v_missed_day_chance integer;
begin
  select public.get_current_game_date_date()
  into v_current_game_date;

  if v_current_game_date is null then
    v_errors := v_errors || jsonb_build_array('Current game date could not be resolved.');
  end if;

  if p_start_date is null then
    v_errors := v_errors || jsonb_build_array('Start date is required.');
  elsif v_current_game_date is not null and p_start_date <= v_current_game_date then
    v_errors := v_errors || jsonb_build_array(
      'Training camp cannot start today or in the past. Earliest start is tomorrow.'
    );
  end if;

  if p_days not in (7, 10, 14) then
    v_errors := v_errors || jsonb_build_array('Camp duration must be 7, 10, or 14 days.');
  end if;

  select coalesce(array_agg(x.rider_id), '{}'::uuid[])
  into v_selected_rider_ids
  from (
    select distinct unnest(coalesce(p_rider_ids, '{}'::uuid[])) as rider_id
  ) x
  where x.rider_id is not null;

  select coalesce(array_agg(x.staff_id), '{}'::uuid[])
  into v_selected_staff_ids
  from (
    select distinct unnest(coalesce(p_staff_ids, '{}'::uuid[])) as staff_id
  ) x
  where x.staff_id is not null;

  select c.owner_user_id
  into v_owner_user_id
  from public.clubs c
  where c.id = p_club_id
  limit 1;

  if v_owner_user_id is null then
    v_errors := v_errors || jsonb_build_array('Club not found.');
  else
    select coalesce(array_agg(c.id), array[p_club_id]::uuid[])
    into v_family_club_ids
    from public.clubs c
    where c.owner_user_id = v_owner_user_id
      and c.deleted_at is null
      and coalesce(c.club_type, 'main') in ('main', 'developing');
  end if;

  select *
  into v_camp
  from public.training_camp_catalog c
  where c.id = p_camp_id
    and c.is_active = true
  limit 1;

  if v_camp.id is null then
    v_errors := v_errors || jsonb_build_array('Selected camp does not exist or is inactive.');
  elsif p_start_date is not null then
    select
      ws.weather_state,
      ws.weather_score,
      ws.training_modifier,
      ws.missed_day_chance
    into
      weather_state,
      v_weather_score,
      v_training_modifier,
      v_missed_day_chance
    from public.get_training_camp_weather_state(
      v_camp.country_code,
      p_start_date,
      v_camp.preferred_weeks,
      v_camp.risky_weeks,
      v_camp.closed_weeks,
      v_camp.altitude_category
    ) ws;
  end if;

  if p_start_date is not null and p_days is not null then
    v_start := p_start_date - 1;
    v_end := p_start_date + p_days;
  end if;

  if exists (
    select 1
    from unnest(v_selected_rider_ids) as selected_rider_id
    left join public.club_roster cr
      on cr.rider_id = selected_rider_id
     and cr.club_id = any(v_family_club_ids)
    where cr.rider_id is null
  ) then
    v_errors := v_errors || jsonb_build_array(
      'One or more selected riders do not belong to your club family.'
    );
  end if;

  if p_start_date is not null and p_days is not null then
    select coalesce(array_agg(distinct o.rider_id), '{}'::uuid[])
    into v_overlap_rider_ids
    from public.get_overlapping_training_camp_riders(
      v_selected_rider_ids,
      p_start_date,
      p_days
    ) o;
  end if;

  if coalesce(array_length(v_overlap_rider_ids, 1), 0) > 0 then
    v_errors := v_errors || jsonb_build_array(
      'One or more selected riders are already assigned to an overlapping training camp.'
    );
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'rider_id', cr.rider_id,
    'display_name', cr.display_name,
    'availability_status', cr.availability_status,
    'fatigue', cr.fatigue,
    'status_code', 'already_in_overlapping_camp'
  )), '[]'::jsonb)
  into v_blocked_riders
  from public.club_roster cr
  where cr.rider_id = any(v_overlap_rider_ids);

  select count(*)
  into v_riders_count
  from public.club_roster cr
  join unnest(v_selected_rider_ids) as sr(rider_id)
    on sr.rider_id = cr.rider_id
  where cr.club_id = any(v_family_club_ids)
    and cr.availability_status in ('fit', 'not_fully_fit', 'injured', 'sick')
    and not (cr.rider_id = any(v_overlap_rider_ids));

  if v_riders_count < 5 then
    v_errors := v_errors || jsonb_build_array(
      'Minimum 5 camp riders are required. Injured or sick riders count toward the minimum, but they will not train until recovered.'
    );
  end if;

  if exists (
    select 1
    from public.club_roster cr
    join unnest(v_selected_rider_ids) as sr(rider_id)
      on sr.rider_id = cr.rider_id
    where cr.club_id = any(v_family_club_ids)
      and cr.availability_status in ('injured', 'sick')
      and not (cr.rider_id = any(v_overlap_rider_ids))
  ) then
    v_warnings := v_warnings || jsonb_build_array(
      'Some selected riders are injured or sick. They count toward the minimum and can attend camp, but they will not train until recovered.'
    );
  end if;

  if exists (
    select 1
    from unnest(v_selected_staff_ids) as selected_staff_id
    left join public.club_staff cs
      on cs.id = selected_staff_id
     and cs.club_id = any(v_family_club_ids)
     and cs.is_active = true
     and cs.role_type in ('head_coach', 'team_doctor', 'mechanic', 'sport_director')
    where cs.id is null
  ) then
    v_errors := v_errors || jsonb_build_array(
      'One or more selected staff members are unavailable, inactive, scouts, or do not belong to your club family.'
    );
  end if;

  with selected_staff as (
    select cs.*
    from public.club_staff cs
    where cs.id = any(v_selected_staff_ids)
      and cs.club_id = any(v_family_club_ids)
      and cs.is_active = true
      and cs.role_type in ('head_coach', 'team_doctor', 'mechanic', 'sport_director')
  ),
  blocked as (
    select
      ss.id,
      ss.staff_name,
      ss.role_type,
      case
        when exists (
          select 1
          from public.staff_courses sc
          where sc.staff_id = ss.id
            and sc.status = 'active'
        ) then 'active_staff_course'
        when v_start is not null
         and v_end is not null
         and exists (
          select 1
          from public.training_camp_staff_assignments a
          join public.training_camp_bookings b
            on b.id = a.booking_id
          where a.staff_id = ss.id
            and b.status in ('planned', 'active')
            and v_start <= (b.end_date + 1)
            and (b.start_date - 1) <= v_end
        ) then 'already_in_overlapping_camp'
        else null
      end as status_code
    from selected_staff ss
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'staff_id', b.id,
    'staff_name', b.staff_name,
    'role_type', b.role_type,
    'status_code', b.status_code
  )), '[]'::jsonb)
  into v_blocked_staff
  from blocked b
  where b.status_code is not null;

  if jsonb_array_length(v_blocked_staff) > 0 then
    v_errors := v_errors || jsonb_build_array(
      'One or more selected staff members are unavailable because they are on a course or already assigned to an overlapping camp.'
    );
  end if;

  select count(*)
  into v_staff_count
  from public.club_staff cs
  where cs.id = any(v_selected_staff_ids)
    and cs.club_id = any(v_family_club_ids)
    and cs.is_active = true
    and cs.role_type in ('head_coach', 'team_doctor', 'mechanic', 'sport_director')
    and not exists (
      select 1
      from public.staff_courses sc
      where sc.staff_id = cs.id
        and sc.status = 'active'
    )
    and not exists (
      select 1
      from public.training_camp_staff_assignments a
      join public.training_camp_bookings b
        on b.id = a.booking_id
      where a.staff_id = cs.id
        and b.status in ('planned', 'active')
        and v_start is not null
        and v_end is not null
        and v_start <= (b.end_date + 1)
        and (b.start_date - 1) <= v_end
    );

  if coalesce(array_length(v_selected_staff_ids, 1), 0) = 0 then
    v_warnings := v_warnings || jsonb_build_array(
      'No staff selected. This is allowed, but the camp will not receive staff boosts.'
    );
  end if;

  if weather_state = 'mixed' then
    v_warnings := v_warnings || jsonb_build_array('Weather may reduce training quality.');
  elsif weather_state = 'poor' then
    v_warnings := v_warnings || jsonb_build_array('Weather is poor and will heavily reduce training quality.');
  elsif weather_state = 'unavailable' then
    v_errors := v_errors || jsonb_build_array('Selected camp is unavailable for the chosen start week.');
  end if;

  return query
  select
    jsonb_array_length(v_errors) = 0,
    v_riders_count,
    v_staff_count,
    v_riders_count + v_staff_count,
    weather_state,
    v_errors,
    v_warnings,
    v_blocked_riders,
    v_blocked_staff;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_book_training_camp_v2(p_club_id uuid, p_camp_id uuid, p_start_date date, p_days integer, p_rider_ids uuid[], p_staff_ids uuid[], p_idempotency_key text)
 RETURNS TABLE(booking_id uuid, finance_transaction_id uuid, booking_status text, total_cost integer, participants_count integer, staff_count integer, charged_participants_count integer, weather_state text, validation_warnings jsonb, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare
  v_stage text := 'start';
  v_uid uuid;
  v_current_game_date date;
  v_normalized_rider_ids uuid[];
  v_normalized_staff_ids uuid[];
  v_eligible_rider_ids uuid[];
  v_eligible_staff_ids uuid[];
  v_eligible_rider_count integer := 0;
  v_eligible_staff_count integer := 0;

  v_owner_user_id uuid;
  v_family_club_ids uuid[];

  v_validation record;
  v_quote record;
  v_camp record;

  v_finance_tx uuid;
  v_existing_booking record;
  v_new_booking_id uuid;
  v_inserted_participants integer := 0;
  v_inserted_staff integer := 0;
  v_created_at timestamptz;
begin
  v_stage := 'auth';
  v_uid := auth.uid();

  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  v_stage := 'idempotency_key_check';

  if p_idempotency_key is null or btrim(p_idempotency_key) = '' then
    raise exception 'Idempotency key is required';
  end if;

  v_stage := 'current_game_date_check';

  select public.get_current_game_date_date()
  into v_current_game_date;

  if v_current_game_date is null then
    raise exception 'Current game date could not be resolved.';
  end if;

  if p_start_date <= v_current_game_date then
    raise exception 'Training camp cannot start today or in the past. Earliest start is tomorrow.';
  end if;

  v_stage := 'normalize_ids';

  select coalesce(array_agg(x.rider_id), '{}'::uuid[])
  into v_normalized_rider_ids
  from (
    select distinct unnest(coalesce(p_rider_ids, '{}'::uuid[])) as rider_id
  ) x;

  select coalesce(array_agg(x.staff_id), '{}'::uuid[])
  into v_normalized_staff_ids
  from (
    select distinct unnest(coalesce(p_staff_ids, '{}'::uuid[])) as staff_id
  ) x;

  v_stage := 'resolve_club_family';

  select c.owner_user_id
  into v_owner_user_id
  from public.clubs c
  where c.id = p_club_id
  limit 1;

  if v_owner_user_id is null then
    raise exception 'Club not found';
  end if;

  select coalesce(array_agg(c.id), '{}'::uuid[])
  into v_family_club_ids
  from public.clubs c
  where c.owner_user_id = v_owner_user_id
    and c.deleted_at is null
    and coalesce(c.club_type, 'main') in ('main', 'developing');

  v_stage := 'resolve_eligible_riders';

  select
    coalesce(array_agg(cr.rider_id order by cr.rider_id), '{}'::uuid[]),
    count(*)
  into v_eligible_rider_ids, v_eligible_rider_count
  from public.club_roster cr
  where cr.club_id = any(v_family_club_ids)
    and cr.rider_id = any(v_normalized_rider_ids)
    and cr.availability_status in ('fit', 'not_fully_fit', 'injured', 'sick');

  if v_eligible_rider_count < 5 then
    raise exception 'Need at least 5 eligible riders, found %.', v_eligible_rider_count;
  end if;

  v_stage := 'resolve_eligible_staff';

  select
    coalesce(array_agg(cs.id order by cs.id), '{}'::uuid[]),
    count(*)
  into v_eligible_staff_ids, v_eligible_staff_count
  from public.club_staff cs
  where cs.club_id = any(v_family_club_ids)
    and cs.id = any(v_normalized_staff_ids)
    and cs.is_active = true
    and cs.role_type in ('head_coach', 'team_doctor', 'mechanic', 'sport_director')
    and not exists (
      select 1
      from public.staff_courses sc
      where sc.staff_id = cs.id
        and sc.status = 'active'
    )
    and not exists (
      select 1
      from public.training_camp_staff_assignments a
      join public.training_camp_bookings b
        on b.id = a.booking_id
      where a.staff_id = cs.id
        and b.status in ('planned', 'active')
        and (p_start_date - 1) <= (b.end_date + 1)
        and (b.start_date - 1) <= (p_start_date + p_days)
    );

  v_stage := 'validate_booking';

  select *
  into v_validation
  from public.validate_training_camp_booking_v2(
    p_club_id,
    p_camp_id,
    p_start_date,
    p_days,
    v_normalized_rider_ids,
    v_normalized_staff_ids
  );

  if not coalesce(v_validation.is_valid, false) then
    raise exception 'Training camp booking validation failed: %',
      coalesce(v_validation.validation_errors::text, '[]');
  end if;

  v_stage := 'get_quote';

  select *
  into v_quote
  from public.get_training_camp_quote_v2(
    p_club_id,
    p_camp_id,
    p_start_date,
    p_days,
    v_eligible_rider_ids,
    v_eligible_staff_ids
  );

  if v_quote.camp_id is null then
    raise exception 'Quote generation returned no row';
  end if;

  v_stage := 'load_camp_snapshot';

  select
    id,
    name,
    city_name,
    country_code,
    region_name,
    camp_type,
    stars
  into v_camp
  from public.training_camp_catalog
  where id = p_camp_id
  limit 1;

  if v_camp.id is null then
    raise exception 'Training camp not found';
  end if;

  v_stage := 'finance_spend_from_club';

  v_finance_tx := public.finance_spend_from_club(
    p_club_id,
    v_quote.total_cost,
    'training_camp_booking',
    'SINK',
    p_idempotency_key,
    jsonb_build_object(
      'camp_id', v_camp.id,
      'camp_name', v_camp.name,
      'city_name', v_camp.city_name,
      'country_code', v_camp.country_code,
      'region_name', v_camp.region_name,
      'camp_type', v_camp.camp_type,
      'start_date', p_start_date,
      'days', p_days,
      'riders_count', v_quote.riders_count,
      'staff_count', v_quote.staff_count,
      'charged_participants_count', v_quote.charged_participants_count,
      'participants_count', v_quote.participants_count,
      'weather_state', v_quote.weather_state,
      'travel_total', v_quote.travel_total,
      'accommodation_total', v_quote.accommodation_total,
      'camp_fee_total', v_quote.camp_fee_total,
      'logistics_total', v_quote.logistics_total,
      'total_cost', v_quote.total_cost,
      'rider_ids', to_jsonb(v_eligible_rider_ids),
      'staff_ids', to_jsonb(v_eligible_staff_ids)
    )
  );

  if v_finance_tx is null then
    raise exception 'finance_spend_from_club returned null transaction id';
  end if;

  v_stage := 'check_existing_booking_by_finance_tx';

  select
    b.id,
    b.finance_transaction_id,
    b.status,
    b.total_cost,
    b.participants_count,
    b.staff_count,
    b.charged_participants_count,
    b.created_at
  into v_existing_booking
  from public.training_camp_bookings b
  where b.finance_transaction_id = v_finance_tx
  limit 1;

  if v_existing_booking.id is not null then
    return query
    select
      v_existing_booking.id,
      v_existing_booking.finance_transaction_id,
      v_existing_booking.status,
      v_existing_booking.total_cost,
      v_existing_booking.participants_count,
      v_existing_booking.staff_count,
      v_existing_booking.charged_participants_count,
      v_quote.weather_state,
      coalesce(v_validation.validation_warnings, '[]'::jsonb),
      v_existing_booking.created_at;
    return;
  end if;

  v_stage := 'insert_booking';

  insert into public.training_camp_bookings as tcb (
    club_id,
    camp_id,
    start_date,
    end_date,
    days_count,
    status,
    participants_count,
    staff_count,
    charged_participants_count,
    camp_name,
    country_code,
    region_name,
    camp_type_snapshot,
    stars_snapshot,
    city_snapshot,
    country_code_snapshot,
    weather_summary,
    travel_cost_total,
    accommodation_cost_total,
    camp_fee_cost_total,
    logistics_cost_total,
    total_cost,
    finance_transaction_id,
    created_by_user_id,
    notes
  )
  values (
    p_club_id,
    p_camp_id,
    p_start_date,
    (p_start_date + (p_days - 1)),
    p_days,
    'planned',
    v_quote.riders_count,
    v_quote.staff_count,
    v_quote.charged_participants_count,
    v_camp.name,
    v_camp.country_code,
    v_camp.region_name,
    v_camp.camp_type,
    v_camp.stars,
    v_camp.city_name,
    v_camp.country_code,
    jsonb_build_object(
      'weather_state', v_quote.weather_state,
      'weather_score', v_quote.weather_score,
      'training_modifier', v_quote.training_modifier,
      'missed_day_chance', v_quote.missed_day_chance
    ),
    v_quote.travel_total,
    v_quote.accommodation_total,
    v_quote.camp_fee_total,
    v_quote.logistics_total,
    v_quote.total_cost,
    v_finance_tx,
    v_uid,
    jsonb_build_object(
      'riders_count', v_quote.riders_count,
      'staff_count', v_quote.staff_count,
      'charged_participants_count', v_quote.charged_participants_count
    )
  )
  returning tcb.id, tcb.created_at
  into v_new_booking_id, v_created_at;

  v_stage := 'insert_participants';

  insert into public.training_camp_participants (
    booking_id,
    rider_id
  )
  select
    v_new_booking_id,
    x.rider_id
  from unnest(v_eligible_rider_ids) as x(rider_id);

  get diagnostics v_inserted_participants = row_count;

  if v_inserted_participants < 5 then
    raise exception 'Booking creation failed: fewer than 5 eligible riders were inserted (%).', v_inserted_participants;
  end if;

  v_stage := 'insert_staff_assignments';

  insert into public.training_camp_staff_assignments (
    booking_id,
    staff_id,
    club_id,
    role_type,
    staff_name_snapshot,
    boost_label,
    boost_metadata
  )
  select
    v_new_booking_id,
    cs.id,
    cs.club_id,
    cs.role_type,
    cs.staff_name,
    boost.boost_label,
    boost.boost_metadata
  from public.club_staff cs
  cross join lateral public.training_camp_staff_boost(
    cs.role_type,
    cs.expertise,
    cs.experience,
    cs.potential,
    cs.leadership,
    cs.efficiency,
    cs.loyalty
  ) boost
  where cs.id = any(v_eligible_staff_ids)
  on conflict do nothing;

  get diagnostics v_inserted_staff = row_count;

  v_stage := 'update_booking_counts';

  update public.training_camp_bookings
  set
    participants_count = v_inserted_participants,
    staff_count = v_inserted_staff,
    charged_participants_count = v_inserted_participants + v_inserted_staff,
    notes = coalesce(notes, '{}'::jsonb) || jsonb_build_object(
      'riders_count', v_inserted_participants,
      'staff_count', v_inserted_staff,
      'charged_participants_count', v_inserted_participants + v_inserted_staff,
      'staff_boost_summary', public.get_training_camp_staff_boost_summary(v_new_booking_id)
    )
  where id = v_new_booking_id;

  v_stage := 'return_success';

  return query
  select
    v_new_booking_id,
    v_finance_tx,
    'planned'::text,
    v_quote.total_cost,
    v_inserted_participants,
    v_inserted_staff,
    v_inserted_participants + v_inserted_staff,
    v_quote.weather_state,
    coalesce(v_validation.validation_warnings, '[]'::jsonb),
    v_created_at;

exception
  when others then
    raise exception 'finance_book_training_camp_v2 failed at stage [%]: %', v_stage, sqlerrm;
end;$function$
;

CREATE OR REPLACE FUNCTION public.finance_book_training_camp_debug_v2(p_club_id uuid, p_camp_id uuid, p_start_date date, p_days integer, p_rider_ids uuid[], p_staff_ids uuid[], p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result record;
begin
  select *
  into v_result
  from public.finance_book_training_camp_v2(
    p_club_id,
    p_camp_id,
    p_start_date,
    p_days,
    p_rider_ids,
    p_staff_ids,
    p_idempotency_key
  );

  return jsonb_build_object(
    'ok', true,
    'booking_id', v_result.booking_id,
    'finance_transaction_id', v_result.finance_transaction_id,
    'booking_status', v_result.booking_status,
    'total_cost', v_result.total_cost,
    'participants_count', v_result.participants_count,
    'staff_count', v_result.staff_count,
    'charged_participants_count', v_result.charged_participants_count,
    'weather_state', v_result.weather_state,
    'validation_warnings', v_result.validation_warnings,
    'created_at', v_result.created_at
  );

exception
  when others then
    return jsonb_build_object(
      'ok', false,
      'sqlstate', sqlstate,
      'message', sqlerrm
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.training_get_current_camp(p_camp_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid;
  v_booking record;
  v_current_game_date date;
  v_result jsonb;
begin
  v_uid := auth.uid();

  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  v_current_game_date := public.get_current_game_date_date();

  select b.*
  into v_booking
  from public.training_camp_bookings b
  join public.clubs c
    on c.id = b.club_id
  left join public.club_memberships cm
    on cm.club_id = c.id
   and cm.user_id = v_uid
  where (
      c.owner_user_id = v_uid
      or cm.user_id is not null
    )
    and b.status in ('planned', 'active')
    and (
      p_camp_id is null
      or b.id = p_camp_id
      or b.camp_id = p_camp_id
    )
  order by
    case b.status
      when 'active' then 1
      when 'planned' then 2
      else 9
    end,
    b.start_date
  limit 1;

  if v_booking.id is null then
    return jsonb_build_object(
      'camp', null,
      'participants', '[]'::jsonb,
      'staff', '[]'::jsonb
    );
  end if;

  v_result := jsonb_build_object(
    'camp',
      jsonb_build_object(
        'id', v_booking.id,
        'location_name', coalesce(v_booking.city_snapshot, v_booking.camp_name, 'Training camp'),
        'country_code', coalesce(v_booking.country_code_snapshot, v_booking.country_code),
        'focus_label', initcap(replace(public.resolve_training_camp_focus_code(v_booking.camp_type_snapshot), '_', ' ')),
        'current_day',
          case
            when v_current_game_date is null then null
            when v_current_game_date < v_booking.start_date then 0
            when v_current_game_date > v_booking.end_date then v_booking.days_count
            else greatest(1, (v_current_game_date - v_booking.start_date) + 1)
          end,
        'duration_days', v_booking.days_count,
        'status', v_booking.status,
        'started_on_game_date', v_booking.start_date,
        'ends_on_game_date', v_booking.end_date
      ),
    'participants',
      coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', tcp.rider_id,
            'rider_id', tcp.rider_id,
            'rider_name', coalesce(cr.display_name, r.display_name, concat_ws(' ', r.first_name, r.last_name)),
            'role', cr.assigned_role,
            'status', coalesce(cr.availability_status, r.availability_status),
            'daily_gain', coalesce(today_gain.daily_gain, 0),
            'total_gain', coalesce(total_gain.total_gain, 0)
          )
          order by coalesce(cr.display_name, r.display_name, concat_ws(' ', r.first_name, r.last_name))
        )
        from public.training_camp_participants tcp
        join public.riders r
          on r.id = tcp.rider_id
        left join public.club_roster cr
          on cr.rider_id = tcp.rider_id
        left join lateral (
          select round(coalesce((a.metadata ->> 'development_value_base')::numeric, 0), 4) as daily_gain
          from public.rider_daily_activity a
          where a.rider_id = tcp.rider_id
            and a.activity_type = 'training_camp'
            and (a.metadata ->> 'booking_id')::uuid = v_booking.id
            and a.activity_date = coalesce(v_current_game_date, v_booking.start_date)
          limit 1
        ) today_gain on true
        left join lateral (
          select round(sum(coalesce((a.metadata ->> 'development_value_base')::numeric, 0)), 4) as total_gain
          from public.rider_daily_activity a
          where a.rider_id = tcp.rider_id
            and a.activity_type = 'training_camp'
            and (a.metadata ->> 'booking_id')::uuid = v_booking.id
        ) total_gain on true
        where tcp.booking_id = v_booking.id
      ), '[]'::jsonb),
    'staff',
      coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', a.staff_id,
            'staff_id', a.staff_id,
            'staff_name', a.staff_name_snapshot,
            'role_type', a.role_type,
            'boost_label', a.boost_label
          )
          order by
            case a.role_type
              when 'head_coach' then 1
              when 'team_doctor' then 2
              when 'mechanic' then 3
              when 'sport_director' then 4
              else 99
            end,
            a.staff_name_snapshot
        )
        from public.training_camp_staff_assignments a
        where a.booking_id = v_booking.id
      ), '[]'::jsonb)
  );

  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_daily_market_jobs_detailed()
 RETURNS TABLE(expired_transfer_listings integer, expired_transfer_offers integer, expired_transfer_negotiations integer, expired_free_agents integer, expired_free_agent_negotiations integer, refill_created_count integer, refill_amateur_created integer, refill_continental_created integer, refill_proteam_created integer, ai_seller_clubs_reviewed integer, ai_seller_listings_created integer, ai_seller_skipped_count integer, ai_transfer_buyer_clubs_reviewed integer, ai_transfer_buyer_offers_created integer, ai_transfer_buyer_skipped_no_candidate integer, ai_transfer_buyer_skipped_cash_reserve integer, ai_transfer_offer_review_clubs_reviewed integer, ai_transfer_offer_review_offers_accepted integer, ai_transfer_offer_review_offers_rejected integer, ai_transfer_offer_review_skipped_count integer, ai_transfer_contract_review_clubs_reviewed integer, ai_transfer_contract_review_terms_submitted integer, ai_transfer_contract_review_skipped_count integer, ai_free_agent_buyer_clubs_reviewed integer, ai_free_agent_buyer_offers_created integer, ai_free_agent_buyer_skipped_no_candidate integer, ai_free_agent_buyer_skipped_cash_reserve integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_today date;
  v_claimed boolean := false;
  v_result record;
begin
  v_today := public.get_market_game_date();

  if v_today is null then
    raise exception 'run_daily_market_jobs_detailed: market game date could not be resolved';
  end if;

  insert into public.rider_market_daily_runs (
    run_game_date,
    status,
    started_at
  )
  values (
    v_today,
    'running',
    now()
  )
  on conflict do nothing
  returning true into v_claimed;

  /*
    If today's AI market jobs already ran, return the stored result.
    This makes the function safe against direct/manual duplicate calls.
  */
  if not coalesce(v_claimed, false) then
    return query
    select
      r.expired_transfer_listings,
      r.expired_transfer_offers,
      r.expired_transfer_negotiations,
      r.expired_free_agents,
      r.expired_free_agent_negotiations,
      r.refill_created_count,
      r.refill_amateur_created,
      r.refill_continental_created,
      r.refill_proteam_created,
      r.ai_seller_clubs_reviewed,
      r.ai_seller_listings_created,
      r.ai_seller_skipped_count,
      r.ai_transfer_buyer_clubs_reviewed,
      r.ai_transfer_buyer_offers_created,
      r.ai_transfer_buyer_skipped_no_candidate,
      r.ai_transfer_buyer_skipped_cash_reserve,
      r.ai_transfer_offer_review_clubs_reviewed,
      r.ai_transfer_offer_review_offers_accepted,
      r.ai_transfer_offer_review_offers_rejected,
      r.ai_transfer_offer_review_skipped_count,
      r.ai_transfer_contract_review_clubs_reviewed,
      r.ai_transfer_contract_review_terms_submitted,
      r.ai_transfer_contract_review_skipped_count,
      r.ai_free_agent_buyer_clubs_reviewed,
      r.ai_free_agent_buyer_offers_created,
      r.ai_free_agent_buyer_skipped_no_candidate,
      r.ai_free_agent_buyer_skipped_cash_reserve
    from public.rider_market_daily_runs r
    where r.run_game_date = v_today;

    return;
  end if;

  begin
    select *
    into v_result
    from public.run_daily_market_jobs_detailed_core();

    update public.rider_market_daily_runs r
    set
      status = 'completed',
      completed_at = now(),
      error_message = null,

      expired_transfer_listings = coalesce(v_result.expired_transfer_listings, 0),
      expired_transfer_offers = coalesce(v_result.expired_transfer_offers, 0),
      expired_transfer_negotiations = coalesce(v_result.expired_transfer_negotiations, 0),
      expired_free_agents = coalesce(v_result.expired_free_agents, 0),
      expired_free_agent_negotiations = coalesce(v_result.expired_free_agent_negotiations, 0),

      refill_created_count = coalesce(v_result.refill_created_count, 0),
      refill_amateur_created = coalesce(v_result.refill_amateur_created, 0),
      refill_continental_created = coalesce(v_result.refill_continental_created, 0),
      refill_proteam_created = coalesce(v_result.refill_proteam_created, 0),

      ai_seller_clubs_reviewed = coalesce(v_result.ai_seller_clubs_reviewed, 0),
      ai_seller_listings_created = coalesce(v_result.ai_seller_listings_created, 0),
      ai_seller_skipped_count = coalesce(v_result.ai_seller_skipped_count, 0),

      ai_transfer_buyer_clubs_reviewed = coalesce(v_result.ai_transfer_buyer_clubs_reviewed, 0),
      ai_transfer_buyer_offers_created = coalesce(v_result.ai_transfer_buyer_offers_created, 0),
      ai_transfer_buyer_skipped_no_candidate = coalesce(v_result.ai_transfer_buyer_skipped_no_candidate, 0),
      ai_transfer_buyer_skipped_cash_reserve = coalesce(v_result.ai_transfer_buyer_skipped_cash_reserve, 0),

      ai_transfer_offer_review_clubs_reviewed = coalesce(v_result.ai_transfer_offer_review_clubs_reviewed, 0),
      ai_transfer_offer_review_offers_accepted = coalesce(v_result.ai_transfer_offer_review_offers_accepted, 0),
      ai_transfer_offer_review_offers_rejected = coalesce(v_result.ai_transfer_offer_review_offers_rejected, 0),
      ai_transfer_offer_review_skipped_count = coalesce(v_result.ai_transfer_offer_review_skipped_count, 0),

      ai_transfer_contract_review_clubs_reviewed = coalesce(v_result.ai_transfer_contract_review_clubs_reviewed, 0),
      ai_transfer_contract_review_terms_submitted = coalesce(v_result.ai_transfer_contract_review_terms_submitted, 0),
      ai_transfer_contract_review_skipped_count = coalesce(v_result.ai_transfer_contract_review_skipped_count, 0),

      ai_free_agent_buyer_clubs_reviewed = coalesce(v_result.ai_free_agent_buyer_clubs_reviewed, 0),
      ai_free_agent_buyer_offers_created = coalesce(v_result.ai_free_agent_buyer_offers_created, 0),
      ai_free_agent_buyer_skipped_no_candidate = coalesce(v_result.ai_free_agent_buyer_skipped_no_candidate, 0),
      ai_free_agent_buyer_skipped_cash_reserve = coalesce(v_result.ai_free_agent_buyer_skipped_cash_reserve, 0)
    where r.run_game_date = v_today;

  exception when others then
    update public.rider_market_daily_runs r
    set
      status = 'failed',
      completed_at = now(),
      error_message = sqlerrm
    where r.run_game_date = v_today;

    raise;
  end;

  return query
  select
    r.expired_transfer_listings,
    r.expired_transfer_offers,
    r.expired_transfer_negotiations,
    r.expired_free_agents,
    r.expired_free_agent_negotiations,
    r.refill_created_count,
    r.refill_amateur_created,
    r.refill_continental_created,
    r.refill_proteam_created,
    r.ai_seller_clubs_reviewed,
    r.ai_seller_listings_created,
    r.ai_seller_skipped_count,
    r.ai_transfer_buyer_clubs_reviewed,
    r.ai_transfer_buyer_offers_created,
    r.ai_transfer_buyer_skipped_no_candidate,
    r.ai_transfer_buyer_skipped_cash_reserve,
    r.ai_transfer_offer_review_clubs_reviewed,
    r.ai_transfer_offer_review_offers_accepted,
    r.ai_transfer_offer_review_offers_rejected,
    r.ai_transfer_offer_review_skipped_count,
    r.ai_transfer_contract_review_clubs_reviewed,
    r.ai_transfer_contract_review_terms_submitted,
    r.ai_transfer_contract_review_skipped_count,
    r.ai_free_agent_buyer_clubs_reviewed,
    r.ai_free_agent_buyer_offers_created,
    r.ai_free_agent_buyer_skipped_no_candidate,
    r.ai_free_agent_buyer_skipped_cash_reserve
  from public.rider_market_daily_runs r
  where r.run_game_date = v_today;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_training_camp_started_notification(p_booking_id uuid, p_game_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$declare
  v_game_date date;
  v_booking record;
  v_riders_json jsonb := '[]'::jsonb;
  v_staff_json jsonb := '[]'::jsonb;
  v_rider_names text := '';
  v_staff_names text := '';
  v_action_url text;
  v_message text;
  v_claimed_started_log_count integer := 0;
begin
  v_game_date := coalesce(p_game_date, public.get_current_game_date_date());

  if v_game_date is null then
    return jsonb_build_object(
      'ok', false,
      'reason', 'current_game_date_not_found'
    );
  end if;

  select
    b.id,
    b.club_id,
    b.camp_id,
    b.camp_name,
    b.city_snapshot,
    b.camp_type_snapshot,
    b.start_date,
    b.end_date,
    b.days_count,
    b.participants_count,
    b.staff_count,
    b.charged_participants_count,
    b.status,
    b.notes,
    c.owner_user_id
  into v_booking
  from public.training_camp_bookings b
  join public.clubs c
    on c.id = b.club_id
  where b.id = p_booking_id
  limit 1;

  if v_booking.id is null then
    return jsonb_build_object(
      'ok', false,
      'reason', 'booking_not_found'
    );
  end if;

  if v_booking.owner_user_id is null then
    return jsonb_build_object(
      'ok', false,
      'reason', 'owner_user_not_found',
      'booking_id', p_booking_id
    );
  end if;

  insert into public.training_camp_notification_log (
    booking_id,
    game_date,
    notification_type
  )
  values (
    p_booking_id,
    v_game_date,
    'started'
  )
  on conflict do nothing;

  get diagnostics v_claimed_started_log_count = row_count;

  if v_claimed_started_log_count = 0 then
    return jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'already_sent',
      'booking_id', p_booking_id,
      'notification_type', 'TRAINING_CAMP_START'
    );
  end if;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'rider_id', x.rider_id,
          'rider_name', x.rider_name,
          'availability_status', x.availability_status
        )
        order by x.rider_name
      ),
      '[]'::jsonb
    ),
    coalesce(string_agg(x.rider_name, ', ' order by x.rider_name), '')
  into v_riders_json, v_rider_names
  from (
    select
      tcp.rider_id,
      coalesce(
        nullif(r.display_name, ''),
        nullif(btrim(concat_ws(' ', r.first_name, r.last_name)), ''),
        'Unknown rider'
      ) as rider_name,
      coalesce(r.availability_status, 'fit') as availability_status
    from public.training_camp_participants tcp
    left join public.riders r
      on r.id = tcp.rider_id
    where tcp.booking_id = p_booking_id
  ) x;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'staff_id', a.staff_id,
          'staff_name', a.staff_name_snapshot,
          'role_type', a.role_type,
          'role_label', initcap(replace(a.role_type, '_', ' ')),
          'boost_label', a.boost_label,
          'boost_metadata', a.boost_metadata
        )
        order by a.role_type, a.staff_name_snapshot
      ),
      '[]'::jsonb
    ),
    coalesce(
      string_agg(
        format(
          '%s (%s)',
          a.staff_name_snapshot,
          initcap(replace(a.role_type, '_', ' '))
        ),
        ', '
        order by a.role_type, a.staff_name_snapshot
      ),
      ''
    )
  into v_staff_json, v_staff_names
  from public.training_camp_staff_assignments a
  where a.booking_id = p_booking_id;

  v_action_url := '/dashboard/training?tab=training-camps&camp_id=' || p_booking_id::text;

  v_message := format(
    'Your training camp in %s has started. It runs until %s. Riders: %s. Staff: %s.',
    coalesce(v_booking.city_snapshot, 'unknown location'),
    to_char(v_booking.end_date, 'FMMonth FMDD'),
    case
      when coalesce(v_rider_names, '') = '' then 'none listed'
      else v_rider_names
    end,
    case
      when coalesce(v_staff_names, '') = '' then 'no staff assigned'
      else v_staff_names
    end
  );

  perform public.create_infrastructure_notification(
    v_booking.owner_user_id,
    'TRAINING_CAMP_START',
    'Training camp started',
    v_message,
    v_action_url,
    jsonb_build_object(
      'booking_id', v_booking.id,
      'camp_id', v_booking.camp_id,
      'camp_name', v_booking.camp_name,
      'city', v_booking.city_snapshot,
      'camp_type', v_booking.camp_type_snapshot,
      'status', 'active',
      'start_date', v_booking.start_date,
      'end_date', v_booking.end_date,
      'days_count', v_booking.days_count,
      'riders_count', coalesce(v_booking.participants_count, 0),
      'staff_count', coalesce(v_booking.staff_count, 0),
      'charged_participants_count', coalesce(v_booking.charged_participants_count, 0),
      'riders', v_riders_json,
      'staff', v_staff_json,
      'staff_boost_summary', coalesce(v_booking.notes->'staff_boost_summary', 'null'::jsonb),
      'action_url', v_action_url
    )
  );

  return jsonb_build_object(
    'ok', true,
    'booking_id', p_booking_id,
    'notification_type', 'TRAINING_CAMP_START',
    'action_url', v_action_url,
    'riders_count', jsonb_array_length(v_riders_json),
    'staff_count', jsonb_array_length(v_staff_json)
  );
end;$function$
;

CREATE OR REPLACE FUNCTION public.create_training_camp_daily_report_notification(p_booking_id uuid, p_report_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$declare
  v_current_game_date date;
  v_hour_number integer := 0;
  v_minute_number integer := 0;
  v_report_date date;

  v_booking record;
  v_report record;

  v_action_url text;
  v_message text;

  v_riders jsonb := '[]'::jsonb;
  v_staff jsonb := '[]'::jsonb;

  v_unavailable_count integer := 0;
  v_unavailable_names text := null;

  v_injured_count integer := 0;
  v_injured_names text := null;

  v_sick_count integer := 0;
  v_sick_names text := null;

  v_not_fully_fit_count integer := 0;
  v_not_fully_fit_names text := null;

  v_notification_exists boolean := false;
begin
  if p_booking_id is null then
    return jsonb_build_object(
      'ok', false,
      'reason', 'missing_booking_id'
    );
  end if;

  v_current_game_date := public.get_current_game_date_date();

  select
    coalesce(gs.hour_number, 0),
    coalesce(gs.minute_number, 0)
  into
    v_hour_number,
    v_minute_number
  from public.game_state gs
  where gs.id = true
  limit 1;

  v_report_date := coalesce(
    p_report_date,
    case
      when ((v_hour_number * 60) + v_minute_number) >= ((23 * 60) + 30)
        then v_current_game_date
      else (v_current_game_date - interval '1 day')::date
    end
  );

  select
    b.id,
    b.club_id,
    b.camp_id,
    b.camp_name,
    b.city_snapshot,
    b.country_code,
    b.region_name,
    b.camp_type_snapshot,
    b.start_date,
    b.end_date,
    b.days_count,
    b.participants_count,
    b.staff_count,
    b.status,
    c.owner_user_id
  into v_booking
  from public.training_camp_bookings b
  join public.clubs c
    on c.id = b.club_id
  where b.id = p_booking_id
  limit 1;

  if v_booking.id is null then
    return jsonb_build_object(
      'ok', false,
      'reason', 'booking_not_found',
      'booking_id', p_booking_id
    );
  end if;

  if v_booking.owner_user_id is null then
    return jsonb_build_object(
      'ok', false,
      'reason', 'booking_owner_user_not_found',
      'booking_id', p_booking_id
    );
  end if;

  select
    r.id,
    r.booking_id,
    r.report_date,
    r.day_index,
    r.weather_state,
    r.session_completed,
    r.participants_count,
    r.completed_count,
    r.missed_count,
    r.avg_fatigue_before,
    r.avg_fatigue_after,
    r.summary_text,
    r.payload
  into v_report
  from public.training_camp_daily_reports r
  where r.booking_id = p_booking_id
    and r.report_date = v_report_date
  limit 1;

  if v_report.id is null then
    return jsonb_build_object(
      'ok', false,
      'reason', 'daily_report_not_found',
      'booking_id', p_booking_id,
      'report_date', v_report_date
    );
  end if;

  if exists (
    select 1
    from public.training_camp_notification_log l
    where l.booking_id = p_booking_id
      and l.game_date = v_report_date
      and l.notification_type = 'daily_report'
  ) then
    return jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'already_logged',
      'booking_id', p_booking_id,
      'report_date', v_report_date,
      'notification_type', 'TRAINING_CAMP_DAILY_REPORT'
    );
  end if;

  if exists (
    select 1
    from public.notifications n
    join public.notification_types nt
      on nt.id = n.type_id
    where nt.code = 'TRAINING_CAMP_DAILY_REPORT'
      and n.payload_json->>'booking_id' = p_booking_id::text
      and n.payload_json->>'report_date' = v_report_date::text
  ) then
    insert into public.training_camp_notification_log (
      booking_id,
      game_date,
      notification_type
    )
    values (
      p_booking_id,
      v_report_date,
      'daily_report'
    )
    on conflict do nothing;

    return jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', 'notification_already_exists_log_repaired',
      'booking_id', p_booking_id,
      'report_date', v_report_date,
      'notification_type', 'TRAINING_CAMP_DAILY_REPORT'
    );
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'rider_id', tcp.rider_id,
        'rider_name',
          coalesce(
            nullif(trim(concat_ws(' ', to_jsonb(r)->>'first_name', to_jsonb(r)->>'last_name')), ''),
            nullif(trim(to_jsonb(r)->>'full_name'), ''),
            nullif(trim(to_jsonb(r)->>'rider_full_name'), ''),
            nullif(trim(to_jsonb(r)->>'display_name'), ''),
            nullif(trim(cr.display_name), ''),
            tcp.rider_id::text
          ),
        'availability_status', coalesce(cr.availability_status, 'unknown'),
        'fatigue', cr.fatigue
      )
      order by coalesce(
        nullif(trim(concat_ws(' ', to_jsonb(r)->>'first_name', to_jsonb(r)->>'last_name')), ''),
        nullif(trim(to_jsonb(r)->>'full_name'), ''),
        nullif(trim(to_jsonb(r)->>'rider_full_name'), ''),
        nullif(trim(to_jsonb(r)->>'display_name'), ''),
        nullif(trim(cr.display_name), ''),
        tcp.rider_id::text
      )
    ),
    '[]'::jsonb
  )
  into v_riders
  from public.training_camp_participants tcp
  left join public.club_roster cr
    on cr.rider_id = tcp.rider_id
   and cr.club_id = v_booking.club_id
  left join public.riders r
    on r.id = tcp.rider_id
  where tcp.booking_id = p_booking_id;

  select
    count(*) filter (
      where coalesce(cr.availability_status, 'fit') in ('injured', 'sick')
    ),
    string_agg(
      coalesce(
        nullif(trim(concat_ws(' ', to_jsonb(r)->>'first_name', to_jsonb(r)->>'last_name')), ''),
        nullif(trim(to_jsonb(r)->>'full_name'), ''),
        nullif(trim(to_jsonb(r)->>'rider_full_name'), ''),
        nullif(trim(to_jsonb(r)->>'display_name'), ''),
        nullif(trim(cr.display_name), ''),
        tcp.rider_id::text
      ),
      ', ' order by coalesce(
        nullif(trim(concat_ws(' ', to_jsonb(r)->>'first_name', to_jsonb(r)->>'last_name')), ''),
        nullif(trim(to_jsonb(r)->>'full_name'), ''),
        nullif(trim(to_jsonb(r)->>'rider_full_name'), ''),
        nullif(trim(to_jsonb(r)->>'display_name'), ''),
        nullif(trim(cr.display_name), ''),
        tcp.rider_id::text
      )
    ) filter (
      where coalesce(cr.availability_status, 'fit') in ('injured', 'sick')
    ),

    count(*) filter (
      where coalesce(cr.availability_status, 'fit') = 'injured'
    ),
    string_agg(
      coalesce(
        nullif(trim(concat_ws(' ', to_jsonb(r)->>'first_name', to_jsonb(r)->>'last_name')), ''),
        nullif(trim(to_jsonb(r)->>'full_name'), ''),
        nullif(trim(to_jsonb(r)->>'rider_full_name'), ''),
        nullif(trim(to_jsonb(r)->>'display_name'), ''),
        nullif(trim(cr.display_name), ''),
        tcp.rider_id::text
      ),
      ', ' order by coalesce(
        nullif(trim(concat_ws(' ', to_jsonb(r)->>'first_name', to_jsonb(r)->>'last_name')), ''),
        nullif(trim(to_jsonb(r)->>'full_name'), ''),
        nullif(trim(to_jsonb(r)->>'rider_full_name'), ''),
        nullif(trim(to_jsonb(r)->>'display_name'), ''),
        nullif(trim(cr.display_name), ''),
        tcp.rider_id::text
      )
    ) filter (
      where coalesce(cr.availability_status, 'fit') = 'injured'
    ),

    count(*) filter (
      where coalesce(cr.availability_status, 'fit') = 'sick'
    ),
    string_agg(
      coalesce(
        nullif(trim(concat_ws(' ', to_jsonb(r)->>'first_name', to_jsonb(r)->>'last_name')), ''),
        nullif(trim(to_jsonb(r)->>'full_name'), ''),
        nullif(trim(to_jsonb(r)->>'rider_full_name'), ''),
        nullif(trim(to_jsonb(r)->>'display_name'), ''),
        nullif(trim(cr.display_name), ''),
        tcp.rider_id::text
      ),
      ', ' order by coalesce(
        nullif(trim(concat_ws(' ', to_jsonb(r)->>'first_name', to_jsonb(r)->>'last_name')), ''),
        nullif(trim(to_jsonb(r)->>'full_name'), ''),
        nullif(trim(to_jsonb(r)->>'rider_full_name'), ''),
        nullif(trim(to_jsonb(r)->>'display_name'), ''),
        nullif(trim(cr.display_name), ''),
        tcp.rider_id::text
      )
    ) filter (
      where coalesce(cr.availability_status, 'fit') = 'sick'
    ),

    count(*) filter (
      where coalesce(cr.availability_status, 'fit') = 'not_fully_fit'
    ),
    string_agg(
      coalesce(
        nullif(trim(concat_ws(' ', to_jsonb(r)->>'first_name', to_jsonb(r)->>'last_name')), ''),
        nullif(trim(to_jsonb(r)->>'full_name'), ''),
        nullif(trim(to_jsonb(r)->>'rider_full_name'), ''),
        nullif(trim(to_jsonb(r)->>'display_name'), ''),
        nullif(trim(cr.display_name), ''),
        tcp.rider_id::text
      ),
      ', ' order by coalesce(
        nullif(trim(concat_ws(' ', to_jsonb(r)->>'first_name', to_jsonb(r)->>'last_name')), ''),
        nullif(trim(to_jsonb(r)->>'full_name'), ''),
        nullif(trim(to_jsonb(r)->>'rider_full_name'), ''),
        nullif(trim(to_jsonb(r)->>'display_name'), ''),
        nullif(trim(cr.display_name), ''),
        tcp.rider_id::text
      )
    ) filter (
      where coalesce(cr.availability_status, 'fit') = 'not_fully_fit'
    )
  into
    v_unavailable_count,
    v_unavailable_names,
    v_injured_count,
    v_injured_names,
    v_sick_count,
    v_sick_names,
    v_not_fully_fit_count,
    v_not_fully_fit_names
  from public.training_camp_participants tcp
  left join public.club_roster cr
    on cr.rider_id = tcp.rider_id
   and cr.club_id = v_booking.club_id
  left join public.riders r
    on r.id = tcp.rider_id
  where tcp.booking_id = p_booking_id;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'staff_id', a.staff_id,
        'staff_name', a.staff_name_snapshot,
        'role_type', a.role_type,
        'role_label',
          case a.role_type
            when 'head_coach' then 'Head Coach'
            when 'team_doctor' then 'Team Doctor'
            when 'mechanic' then 'Mechanic'
            when 'sport_director' then 'Sport Director'
            else initcap(replace(coalesce(a.role_type, 'staff'), '_', ' '))
          end,
        'boost_label', a.boost_label,
        'boost_metadata', a.boost_metadata
      )
      order by a.staff_name_snapshot
    ),
    '[]'::jsonb
  )
  into v_staff
  from public.training_camp_staff_assignments a
  where a.booking_id = p_booking_id;

  v_action_url :=
    '/dashboard/training?tab=training-camps&camp_id=' || p_booking_id::text;

  v_message := format(
    'Day %s/%s report for your training camp in %s is ready.',
    coalesce(v_report.day_index, 1),
    coalesce(v_booking.days_count, 1),
    coalesce(v_booking.city_snapshot, 'unknown location')
  );

  perform public.create_infrastructure_notification(
    v_booking.owner_user_id,
    'TRAINING_CAMP_DAILY_REPORT',
    'Training camp daily report',
    v_message,
    v_action_url,
    jsonb_build_object(
      'booking_id', p_booking_id,
      'status', v_booking.status,
      'report_date', v_report_date,
      'camp_day', v_report.day_index,
      'camp_days_total', v_booking.days_count,
      'start_date', v_booking.start_date,
      'end_date', v_booking.end_date,
      'city_name', v_booking.city_snapshot,
      'camp_name', v_booking.camp_name,
      'camp_type', v_booking.camp_type_snapshot,
      'weather_state', v_report.weather_state,
      'participants_count', v_report.participants_count,
      'completed_count', v_report.completed_count,
      'missed_count', v_report.missed_count,

      'unavailable_count', coalesce(v_unavailable_count, 0),
      'unavailable_names', coalesce(v_unavailable_names, ''),
      'unavailable_rider_names', coalesce(v_unavailable_names, ''),

      'injured_count', coalesce(v_injured_count, 0),
      'injured_names', coalesce(v_injured_names, ''),
      'injured_rider_names', coalesce(v_injured_names, ''),

      'sick_count', coalesce(v_sick_count, 0),
      'sick_names', coalesce(v_sick_names, ''),
      'sick_rider_names', coalesce(v_sick_names, ''),

      'not_fully_fit_count', coalesce(v_not_fully_fit_count, 0),
      'not_fully_fit_names', coalesce(v_not_fully_fit_names, ''),
      'not_fully_fit_rider_names', coalesce(v_not_fully_fit_names, ''),

      'summary_text', v_report.summary_text,
      'action_url', v_action_url,
      'riders', v_riders,
      'staff', v_staff
    )
  );

  select exists (
    select 1
    from public.notifications n
    join public.notification_types nt
      on nt.id = n.type_id
    where nt.code = 'TRAINING_CAMP_DAILY_REPORT'
      and n.payload_json->>'booking_id' = p_booking_id::text
      and n.payload_json->>'report_date' = v_report_date::text
  )
  into v_notification_exists;

  if not v_notification_exists then
    return jsonb_build_object(
      'ok', false,
      'reason', 'notification_create_call_finished_but_notification_not_found',
      'booking_id', p_booking_id,
      'report_date', v_report_date,
      'notification_type', 'TRAINING_CAMP_DAILY_REPORT'
    );
  end if;

  insert into public.training_camp_notification_log (
    booking_id,
    game_date,
    notification_type
  )
  values (
    p_booking_id,
    v_report_date,
    'daily_report'
  )
  on conflict do nothing;

  return jsonb_build_object(
    'ok', true,
    'booking_id', p_booking_id,
    'report_date', v_report_date,
    'notification_type', 'TRAINING_CAMP_DAILY_REPORT',
    'action_url', v_action_url,
    'riders_count', jsonb_array_length(v_riders),
    'staff_count', jsonb_array_length(v_staff)
  );
end;$function$
;

CREATE OR REPLACE FUNCTION public.apply_training_camp_star_modifiers_to_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_booking_id uuid := null;
  v_stars integer := 3;
  v_star_development_modifier numeric := 1.00;
  v_star_fatigue_delta integer := 0;

  v_roster_status text := null;
  v_status text := 'fit';
  v_focus_code text := 'general';

  v_availability_modifier numeric := 1.00;
  v_base_development_before_staff numeric := 0.0000;
  v_missed_day boolean := false;
  v_missed_day_reason text := null;
begin
  if coalesce(new.source, '') <> 'training_camp'
     or coalesce(new.activity_type, '') <> 'training_camp' then
    return new;
  end if;

  if coalesce(new.metadata, '{}'::jsonb) ? 'booking_id'
     and (new.metadata->>'booking_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    v_booking_id := (new.metadata->>'booking_id')::uuid;
  end if;

  if v_booking_id is not null then
    select coalesce(b.stars_snapshot, 3)::integer
    into v_stars
    from public.training_camp_bookings b
    where b.id = v_booking_id
    limit 1;
  end if;

  v_stars := greatest(1, least(5, coalesce(v_stars, 3)));
  v_star_development_modifier := public.training_camp_star_development_modifier(v_stars);
  v_star_fatigue_delta := public.training_camp_star_fatigue_delta(v_stars);

  select cr.availability_status
  into v_roster_status
  from public.club_roster cr
  where cr.rider_id = new.rider_id
  order by cr.club_id
  limit 1;

  v_status := coalesce(
    v_roster_status,
    new.metadata->>'availability_status',
    'fit'
  );

  v_focus_code := coalesce(
    new.metadata->>'focus_code',
    new.metadata->>'camp_type',
    'general'
  );

  if v_status in ('injured', 'sick') then
    v_availability_modifier := 0.00;
    v_base_development_before_staff := 0.0000;
    v_missed_day := true;
    v_missed_day_reason := v_status;

    new.participated := false;
    new.fatigue_load := 0;

  elsif v_status = 'not_fully_fit' then
    v_availability_modifier := 0.80;
    v_base_development_before_staff := round((0.0800 * 0.80 * v_star_development_modifier)::numeric, 4);
    v_missed_day := false;
    v_missed_day_reason := null;

    new.participated := true;
    new.fatigue_load := greatest(0, 8 + v_star_fatigue_delta);

  else
    v_availability_modifier := 1.00;
    v_base_development_before_staff := round((0.0800 * v_star_development_modifier)::numeric, 4);
    v_missed_day := false;
    v_missed_day_reason := null;

    new.participated := true;
    new.fatigue_load := greatest(0, 16 + v_star_fatigue_delta);
  end if;

  new.metadata :=
    coalesce(new.metadata, '{}'::jsonb)
    || jsonb_build_object(
      'stars_snapshot', v_stars,
      'star_development_modifier', v_star_development_modifier,
      'star_fatigue_delta', v_star_fatigue_delta,
      'availability_status', v_status,
      'availability_modifier', v_availability_modifier,
      'base_development_before_staff', v_base_development_before_staff,
      'development_value_base', v_base_development_before_staff,
      'missed_day', v_missed_day,
      'missed_day_reason', v_missed_day_reason,
      'focus_code', v_focus_code
    );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.training_development_multiplier(p_birth_date date, p_potential integer, p_as_of_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_as_of_date date;
  v_age_years integer;
  v_age_multiplier numeric := 1.00;
  v_potential_multiplier numeric := 1.00;
  v_combined_multiplier numeric := 1.00;
begin
  v_as_of_date := coalesce(p_as_of_date, public.get_current_game_date_date(), current_date);

  if p_birth_date is not null then
    v_age_years := extract(year from age(v_as_of_date, p_birth_date))::integer;
  else
    v_age_years := null;
  end if;

  v_age_multiplier :=
    case
      when v_age_years is null then 1.00
      when v_age_years <= 18 then 1.15
      when v_age_years between 19 and 21 then 1.12
      when v_age_years between 22 and 24 then 1.08
      when v_age_years between 25 and 28 then 1.00
      when v_age_years between 29 and 31 then 0.96
      when v_age_years between 32 and 34 then 0.90
      else 0.82
    end;

  v_potential_multiplier :=
    case
      when p_potential is null then 1.00
      when p_potential >= 90 then 1.15
      when p_potential >= 80 then 1.10
      when p_potential >= 70 then 1.05
      when p_potential >= 60 then 1.00
      when p_potential >= 50 then 0.96
      else 0.92
    end;

  v_combined_multiplier := greatest(
    0.75,
    least(1.30, v_age_multiplier * v_potential_multiplier)
  );

  return jsonb_build_object(
    'age_years', v_age_years,
    'age_multiplier', round(v_age_multiplier, 4),
    'potential', p_potential,
    'potential_multiplier', round(v_potential_multiplier, 4),
    'combined_multiplier', round(v_combined_multiplier, 4)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_zzz_training_activity_development_normalizer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_birth_date date;
  v_potential integer;
  v_multiplier_payload jsonb;
  v_age_potential_multiplier numeric := 1.00;

  v_intensity text;
  v_base_value numeric := 0;
  v_final_value numeric := 0;

  v_coach_training_multiplier numeric := 1.00;
  v_coach_development_multiplier numeric := 1.00;
  v_coach_youth_multiplier numeric := 1.00;

  v_booking_id uuid;
  v_stars integer := 3;
  v_star_fatigue_delta integer := 0;
  v_star_development_value numeric := 0.095;

  v_roster_availability text;
  v_activity_availability text;
  v_availability_modifier numeric := 1.00;

  v_staff_development_bonus_pct numeric := 0;
  v_base_before_staff numeric := 0;
begin
  if new.activity_type not in ('training', 'training_camp') then
    return new;
  end if;

  select r.birth_date, r.potential
  into v_birth_date, v_potential
  from public.riders r
  where r.id = new.rider_id
  limit 1;

  v_multiplier_payload := public.training_development_multiplier(
    v_birth_date,
    v_potential,
    new.activity_date
  );

  v_age_potential_multiplier :=
    coalesce((v_multiplier_payload->>'combined_multiplier')::numeric, 1.00);

  /*
   * REGULAR TRAINING
   *
   * The weekly processor still applies weather_modifier and availability_modifier.
   * So here we store the base development value after age/potential/coach multipliers,
   * but before weather and availability.
   */
  if new.source = 'regular_training'
     and new.activity_type = 'training' then

    v_intensity := lower(coalesce(
      nullif(new.metadata->>'resolved_intensity', ''),
      nullif(new.intensity, ''),
      'normal'
    ));

    v_base_value :=
      case v_intensity
        when 'light' then 0.020
        when 'hard' then 0.050
        else 0.035
      end;

    v_coach_training_multiplier :=
      coalesce(nullif(new.metadata->>'coach_training_multiplier', '')::numeric, 1.00);

    v_coach_development_multiplier :=
      coalesce(nullif(new.metadata->>'coach_development_multiplier', '')::numeric, 1.00);

    v_coach_youth_multiplier :=
      coalesce(nullif(new.metadata->>'coach_youth_multiplier', '')::numeric, 1.00);

    v_final_value := round(
      v_base_value
      * v_age_potential_multiplier
      * v_coach_training_multiplier
      * v_coach_development_multiplier
      * v_coach_youth_multiplier,
      4
    );

    new.metadata := coalesce(new.metadata, '{}'::jsonb) || jsonb_build_object(
      'raw_regular_development_value', v_base_value,
      'age_potential_multiplier', v_age_potential_multiplier,
      'age_potential_payload', v_multiplier_payload,
      'base_development_before_staff', v_final_value,
      'development_value_base', v_final_value,
      'development_value_version', 'regular_0_035_0_050_age_potential_v1'
    );

    return new;
  end if;

  /*
   * TRAINING CAMP
   *
   * Camp value is exact by destination stars:
   * 1-star = 0.09025
   * 2-star = 0.09310
   * 3-star = 0.09500
   * 4-star = 0.10500
   * 5-star = 0.12000
   */
  if new.activity_type = 'training_camp' then
    v_booking_id := nullif(new.metadata->>'booking_id', '')::uuid;

    if v_booking_id is not null then
      select b.stars_snapshot
      into v_stars
      from public.training_camp_bookings b
      where b.id = v_booking_id
      limit 1;
    end if;

    v_stars := coalesce(v_stars, nullif(new.metadata->>'stars_snapshot', '')::integer, 3);

    v_star_development_value :=
      case v_stars
        when 1 then 0.09025
        when 2 then 0.09310
        when 3 then 0.09500
        when 4 then 0.10500
        when 5 then 0.12000
        else 0.09500
      end;

    v_star_fatigue_delta :=
      case v_stars
        when 1 then 2
        when 2 then 1
        when 3 then 0
        when 4 then -1
        when 5 then -2
        else 0
      end;

    select cr.availability_status
    into v_roster_availability
    from public.club_roster cr
    where cr.rider_id = new.rider_id
    limit 1;

    v_activity_availability := lower(coalesce(
      nullif(new.metadata->>'availability_status', ''),
      v_roster_availability,
      'fit'
    ));

    v_availability_modifier :=
      case
        when v_activity_availability in ('injured', 'sick') then 0.00
        when v_activity_availability = 'not_fully_fit' then 0.80
        else 1.00
      end;

    v_staff_development_bonus_pct :=
      coalesce(nullif(new.metadata->>'staff_development_bonus_pct', '')::numeric, 0);

    if v_activity_availability in ('injured', 'sick') then
      new.participated := false;
      new.fatigue_load := 0;
      v_base_before_staff := 0;
      v_final_value := 0;
    else
      new.participated := coalesce(new.participated, true);
      new.fatigue_load := greatest(0, 16 + v_star_fatigue_delta);

      v_base_before_staff := round(
        v_star_development_value
        * v_availability_modifier
        * v_age_potential_multiplier,
        4
      );

      v_final_value := round(
        v_base_before_staff * (1 + (v_staff_development_bonus_pct / 100.0)),
        4
      );
    end if;

    new.metadata := coalesce(new.metadata, '{}'::jsonb) || jsonb_build_object(
      'stars_snapshot', v_stars,
      'star_development_value', v_star_development_value,
      'star_development_modifier', round(v_star_development_value / 0.09500, 4),
      'star_fatigue_delta', v_star_fatigue_delta,
      'availability_status', v_activity_availability,
      'availability_modifier', v_availability_modifier,
      'age_potential_multiplier', v_age_potential_multiplier,
      'age_potential_payload', v_multiplier_payload,
      'base_development_before_staff', v_base_before_staff,
      'staff_development_bonus_pct', v_staff_development_bonus_pct,
      'development_value_base', v_final_value,
      'development_value_version', 'camp_star_exact_age_potential_v1',
      'missed_day', (v_activity_availability in ('injured', 'sick')),
      'missed_day_reason',
        case
          when v_activity_availability in ('injured', 'sick') then v_activity_availability
          else null
        end
    );

    return new;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_normalize_training_camp_development_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_stars integer;
  v_star_development_value numeric;
  v_star_fatigue_delta integer;

  v_availability_status text;
  v_availability_modifier numeric;
  v_missed_day boolean;

  v_age_potential_payload jsonb;
  v_age_potential_multiplier numeric := 1.00;

  v_staff_development_bonus_pct numeric := 0;
  v_base_development_before_staff numeric := 0;
  v_development_value_base numeric := 0;
begin
  if new.activity_type is distinct from 'training_camp' then
    return new;
  end if;

  select b.stars_snapshot
  into v_stars
  from public.training_camp_bookings b
  where b.id::text = nullif(new.metadata->>'booking_id', '')
  limit 1;

  v_stars := coalesce(v_stars, nullif(new.metadata->>'stars_snapshot', '')::integer, 3);

  v_star_development_value :=
    case v_stars
      when 1 then 0.080
      when 2 then 0.0875
      when 3 then 0.095
      when 4 then 0.105
      when 5 then 0.120
      else 0.095
    end;

  v_star_fatigue_delta :=
    case v_stars
      when 1 then 2
      when 2 then 1
      when 3 then 0
      when 4 then -1
      when 5 then -2
      else 0
    end;

  v_availability_status := lower(
    coalesce(
      nullif(new.metadata->>'availability_status', ''),
      nullif(new.metadata->>'activity_status', ''),
      'fit'
    )
  );

  v_missed_day :=
    coalesce(new.participated = false, false)
    or coalesce((new.metadata->>'missed_day')::boolean, false)
    or v_availability_status in ('sick', 'injured');

  v_availability_modifier :=
    case
      when v_missed_day then 0.00
      when v_availability_status = 'not_fully_fit' then 0.80
      else 1.00
    end;

  select public.training_development_multiplier(r.birth_date, r.potential, new.activity_date)
  into v_age_potential_payload
  from public.riders r
  where r.id = new.rider_id
  limit 1;

  v_age_potential_multiplier :=
    coalesce((v_age_potential_payload->>'combined_multiplier')::numeric, 1.00);

  v_staff_development_bonus_pct :=
    coalesce(nullif(new.metadata->>'staff_development_bonus_pct', '')::numeric, 0);

  if v_missed_day then
    new.fatigue_load := 0;
    v_base_development_before_staff := 0;
    v_development_value_base := 0;
  else
    new.fatigue_load := greatest(0, 16 + v_star_fatigue_delta);

    v_base_development_before_staff := round(
      v_star_development_value
      * v_availability_modifier
      * v_age_potential_multiplier,
      4
    );

    v_development_value_base := round(
      v_base_development_before_staff
      * (1 + (v_staff_development_bonus_pct / 100.0)),
      4
    );
  end if;

  new.metadata :=
    coalesce(new.metadata, '{}'::jsonb)
    || jsonb_build_object(
      'stars_snapshot', v_stars,
      'star_development_value', v_star_development_value,
      'star_fatigue_delta', v_star_fatigue_delta,
      'availability_status', v_availability_status,
      'availability_modifier', v_availability_modifier,
      'age_potential_multiplier', v_age_potential_multiplier,
      'age_potential_payload', coalesce(v_age_potential_payload, '{}'::jsonb),
      'base_development_before_staff', v_base_development_before_staff,
      'development_value_base', v_development_value_base,
      'development_value_version', 'camp_0_095_0_105_0_120_age_potential_v1'
    );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.training_get_camp_weather(p_booking_id uuid, p_days integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_club_id uuid;
  v_booking record;
  v_current_game_date date;
  v_country_code text;
  v_city text;

  v_offset integer;
  v_weather_date date;
  v_week integer;
  v_normal record;

  v_roll numeric;
  v_temp_roll numeric;
  v_wind_roll numeric;
  v_risk_roll numeric;

  v_condition_code text;
  v_condition_label text;
  v_temp_c integer;
  v_wind_kmh integer;
  v_wet_chance integer;

  v_p_clear numeric;
  v_p_partly numeric;
  v_p_overcast numeric;
  v_p_foggy numeric;
  v_p_drizzle numeric;
  v_p_rain numeric;
  v_p_heavy_rain numeric;
  v_p_sleet numeric;
  v_p_snow numeric;
  v_p_thunderstorm numeric;
  v_total numeric;

  v_item jsonb;
  v_today jsonb := null;
  v_forecast jsonb := '[]'::jsonb;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  v_club_id := public.get_my_club_id();
  v_current_game_date := public.get_current_game_date_date();

  select
    b.id,
    b.club_id,
    b.city_snapshot,
    coalesce(b.country_code_snapshot, b.country_code) as country_code,
    b.start_date,
    b.end_date,
    b.status
  into v_booking
  from public.training_camp_bookings b
  where b.id = p_booking_id
    and b.club_id = v_club_id
  limit 1;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'reason', 'training_camp_not_found'
    );
  end if;

  v_country_code := v_booking.country_code;
  v_city := coalesce(v_booking.city_snapshot, 'Training camp');

  if v_current_game_date is null then
    v_current_game_date := coalesce(v_booking.start_date, current_date);
  end if;

  for v_offset in 0..greatest(1, least(coalesce(p_days, 5), 10)) loop
    v_weather_date := v_current_game_date + v_offset;
    v_week := extract(week from v_weather_date)::integer;

    select *
    into v_normal
    from public.country_weather_weekly_normals n
    where n.country_code = v_country_code
      and n.week_of_year = v_week
    limit 1;

    if not found then
      v_condition_code := 'overcast';
      v_condition_label := 'Overcast';
      v_temp_c := 0;
      v_wind_kmh := 0;
      v_wet_chance := 0;
    else
      /*
       * Stable daily randomness:
       * Same booking + same game date always gives same weather.
       * Different game date gives different variation.
       */
      v_roll :=
        mod(abs(hashtextextended(p_booking_id::text || ':' || v_weather_date::text || ':condition:v2', 0)), 10000::bigint)::numeric / 10000.0;

      v_temp_roll :=
        mod(abs(hashtextextended(p_booking_id::text || ':' || v_weather_date::text || ':temp:v2', 0)), 10000::bigint)::numeric / 10000.0;

      v_wind_roll :=
        mod(abs(hashtextextended(p_booking_id::text || ':' || v_weather_date::text || ':wind:v2', 0)), 10000::bigint)::numeric / 10000.0;

      v_risk_roll :=
        mod(abs(hashtextextended(p_booking_id::text || ':' || v_weather_date::text || ':risk:v2', 0)), 10000::bigint)::numeric / 10000.0;

      /*
       * Small daily adjustment.
       * This keeps the weekly climate identity, but avoids every day feeling copied.
       */
      v_p_clear := greatest(0, coalesce(v_normal.p_clear, 0) + ((v_roll - 0.50) * 0.06));
      v_p_partly := greatest(0, coalesce(v_normal.p_partly_cloudy, 0) + ((v_temp_roll - 0.50) * 0.08));
      v_p_overcast := greatest(0, coalesce(v_normal.p_overcast, 0) + ((v_wind_roll - 0.50) * 0.08));
      v_p_foggy := greatest(0, coalesce(v_normal.p_foggy, 0));
      v_p_drizzle := greatest(0, coalesce(v_normal.p_drizzle, 0) + ((v_risk_roll - 0.50) * 0.06));
      v_p_rain := greatest(0, coalesce(v_normal.p_rain, 0) + ((v_roll - 0.50) * 0.05));
      v_p_heavy_rain := greatest(0, coalesce(v_normal.p_heavy_rain, 0));
      v_p_sleet := greatest(0, coalesce(v_normal.p_sleet, 0));
      v_p_snow := greatest(0, coalesce(v_normal.p_snow, 0));
      v_p_thunderstorm := greatest(0, coalesce(v_normal.p_thunderstorm, 0));

      v_total :=
        v_p_clear
        + v_p_partly
        + v_p_overcast
        + v_p_foggy
        + v_p_drizzle
        + v_p_rain
        + v_p_heavy_rain
        + v_p_sleet
        + v_p_snow
        + v_p_thunderstorm;

      if v_total <= 0 then
        v_condition_code := 'overcast';
      else
        v_roll := v_roll * v_total;

        if v_roll < v_p_clear then
          v_condition_code := 'clear';
        elsif v_roll < v_p_clear + v_p_partly then
          v_condition_code := 'partly_cloudy';
        elsif v_roll < v_p_clear + v_p_partly + v_p_overcast then
          v_condition_code := 'overcast';
        elsif v_roll < v_p_clear + v_p_partly + v_p_overcast + v_p_foggy then
          v_condition_code := 'foggy';
        elsif v_roll < v_p_clear + v_p_partly + v_p_overcast + v_p_foggy + v_p_drizzle then
          v_condition_code := 'drizzle';
        elsif v_roll < v_p_clear + v_p_partly + v_p_overcast + v_p_foggy + v_p_drizzle + v_p_rain then
          v_condition_code := 'rain';
        elsif v_roll < v_p_clear + v_p_partly + v_p_overcast + v_p_foggy + v_p_drizzle + v_p_rain + v_p_heavy_rain then
          v_condition_code := 'heavy_rain';
        elsif v_roll < v_p_clear + v_p_partly + v_p_overcast + v_p_foggy + v_p_drizzle + v_p_rain + v_p_heavy_rain + v_p_sleet then
          v_condition_code := 'sleet';
        elsif v_roll < v_p_clear + v_p_partly + v_p_overcast + v_p_foggy + v_p_drizzle + v_p_rain + v_p_heavy_rain + v_p_sleet + v_p_snow then
          v_condition_code := 'snow';
        else
          v_condition_code := 'thunderstorm';
        end if;
      end if;

      v_condition_label :=
        case v_condition_code
          when 'clear' then 'Clear'
          when 'partly_cloudy' then 'Partly cloudy'
          when 'overcast' then 'Overcast'
          when 'foggy' then 'Foggy'
          when 'drizzle' then 'Drizzle'
          when 'rain' then 'Rain'
          when 'heavy_rain' then 'Heavy rain'
          when 'sleet' then 'Sleet'
          when 'snow' then 'Snow'
          when 'thunderstorm' then 'Thunderstorm'
          else 'Overcast'
        end;

      v_temp_c := round(coalesce(v_normal.avg_temp_c, 0) + ((v_temp_roll * 8) - 4))::integer;
      v_wind_kmh := greatest(0, round(coalesce(v_normal.avg_wind_kmh, 0) + ((v_wind_roll * 10) - 5))::integer);

      v_wet_chance := round(
        least(
          100,
          greatest(
            0,
            (
              coalesce(v_normal.p_drizzle, 0)
              + coalesce(v_normal.p_rain, 0)
              + coalesce(v_normal.p_heavy_rain, 0)
              + coalesce(v_normal.p_sleet, 0)
              + coalesce(v_normal.p_snow, 0)
              + coalesce(v_normal.p_thunderstorm, 0)
            ) * 100
            + ((v_risk_roll * 16) - 8)
          )
        )
      )::integer;
    end if;

    v_item := jsonb_build_object(
      'date', v_weather_date,
      'city_name', v_city,
      'country_code', v_country_code,
      'week_of_year', v_week,
      'condition_code', v_condition_code,
      'condition', v_condition_label,
      'temp_c', v_temp_c,
      'wind_kmh', v_wind_kmh,
      'wet_weather_chance_pct', v_wet_chance
    );

    if v_offset = 0 then
      v_today := v_item;
    else
      v_forecast := v_forecast || jsonb_build_array(v_item);
    end if;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'source', 'country_weather_weekly_normals_seeded_daily_v2',
    'base_game_date', v_current_game_date,
    'city_name', v_city,
    'country_code', v_country_code,
    'today', v_today,
    'forecast', v_forecast
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.save_training_camp_day_training_plans(p_booking_id uuid, p_plans jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_club_id uuid;
  v_current_game_date date;
  v_booking record;
  v_plan record;
  v_saved_count integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_booking_id is null then
    raise exception 'Missing booking id';
  end if;

  if p_plans is null or jsonb_typeof(p_plans) <> 'array' then
    raise exception 'Plans must be a JSON array';
  end if;

  v_club_id := public.get_my_club_id();
  v_current_game_date := public.get_current_game_date_date();

  if v_current_game_date is null then
    raise exception 'Current game date not found';
  end if;

  select
    b.id,
    b.club_id,
    b.start_date,
    b.end_date,
    b.status
  into v_booking
  from public.training_camp_bookings b
  where b.id = p_booking_id
    and b.club_id = v_club_id
  limit 1;

  if not found then
    raise exception 'Training camp booking not found';
  end if;

  for v_plan in
    select *
    from jsonb_to_recordset(p_plans) as x(
      rider_id uuid,
      plan_date date,
      intensity text
    )
  loop
    if v_plan.rider_id is null or v_plan.plan_date is null then
      raise exception 'Invalid training plan row';
    end if;

    if v_plan.intensity not in ('day_off', 'light', 'normal', 'hard') then
      raise exception 'Invalid intensity: %', v_plan.intensity;
    end if;

    if v_plan.plan_date <= v_current_game_date then
      raise exception 'Training plan for % is already locked', v_plan.plan_date;
    end if;

    if v_plan.plan_date > (v_current_game_date + interval '3 days')::date then
      raise exception 'Only the next 3 days can be planned';
    end if;

    if v_plan.plan_date < v_booking.start_date or v_plan.plan_date > v_booking.end_date then
      raise exception 'Plan date % is outside this training camp', v_plan.plan_date;
    end if;

    insert into public.training_camp_day_training_plans (
      booking_id,
      rider_id,
      plan_date,
      intensity,
      created_by,
      updated_by,
      updated_at
    )
    values (
      p_booking_id,
      v_plan.rider_id,
      v_plan.plan_date,
      v_plan.intensity,
      auth.uid(),
      auth.uid(),
      now()
    )
    on conflict (booking_id, rider_id, plan_date)
    do update set
      intensity = excluded.intensity,
      updated_by = auth.uid(),
      updated_at = now();

    v_saved_count := v_saved_count + 1;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'saved_count', v_saved_count
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_apply_training_camp_weather_effects_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_weather_state text;
  v_planned_intensity text;
  v_missed_day boolean := false;

  v_old_weather_skill_modifier numeric := 1.00;
  v_new_weather_skill_modifier numeric := 1.00;
  v_weather_ratio numeric := 1.00;

  v_old_weather_fatigue_delta integer := 0;
  v_base_weather_fatigue_delta integer := 0;
  v_new_weather_fatigue_delta integer := 0;

  v_base_development_before_staff numeric;
  v_development_value_base numeric;

  v_effect record;
begin
  if coalesce(new.source, '') <> 'training_camp'
     and coalesce(new.activity_type, '') <> 'training_camp'
  then
    return new;
  end if;

  new.metadata := coalesce(new.metadata, '{}'::jsonb);

  v_weather_state := coalesce(
    nullif(new.metadata->>'weather_state', ''),
    nullif(new.metadata->>'weather_condition', ''),
    'ideal'
  );

  v_planned_intensity := lower(coalesce(nullif(new.metadata->>'planned_intensity', ''), new.intensity, 'normal'));

  v_missed_day :=
    lower(coalesce(new.metadata->>'missed_day', 'false')) in ('true', 't', '1', 'yes')
    or lower(coalesce(new.metadata->>'participated', 'true')) in ('false', 'f', '0', 'no')
    or v_planned_intensity = 'day_off';

  select *
  into v_effect
  from public.training_camp_weather_effect_v1(v_weather_state);

  v_new_weather_skill_modifier := coalesce(v_effect.skill_modifier, 1.00);
  v_base_weather_fatigue_delta := coalesce(v_effect.base_fatigue_delta, 0);

  v_old_weather_skill_modifier := coalesce(
    nullif(new.metadata->>'weather_skill_modifier', '')::numeric,
    1.00
  );

  if v_old_weather_skill_modifier = 0 then
    v_old_weather_skill_modifier := 1.00;
  end if;

  v_old_weather_fatigue_delta := coalesce(
    nullif(new.metadata->>'weather_fatigue_delta', '')::integer,
    0
  );

  /*
   * Weather fatigue is scaled by intensity:
   * - day_off / missed day: no extra weather fatigue
   * - light: half weather fatigue
   * - normal: full weather fatigue
   * - hard: 125% weather fatigue
   */
  if v_missed_day then
    v_new_weather_fatigue_delta := 0;
    v_new_weather_skill_modifier := 1.00;
  elsif v_planned_intensity = 'light' then
    v_new_weather_fatigue_delta := ceil(v_base_weather_fatigue_delta * 0.50)::integer;
  elsif v_planned_intensity = 'hard' then
    v_new_weather_fatigue_delta := ceil(v_base_weather_fatigue_delta * 1.25)::integer;
  else
    v_new_weather_fatigue_delta := v_base_weather_fatigue_delta;
  end if;

  v_weather_ratio := v_new_weather_skill_modifier / v_old_weather_skill_modifier;

  v_base_development_before_staff := nullif(new.metadata->>'base_development_before_staff', '')::numeric;
  v_development_value_base := nullif(new.metadata->>'development_value_base', '')::numeric;

  if not v_missed_day then
    if v_base_development_before_staff is not null then
      v_base_development_before_staff := round(v_base_development_before_staff * v_weather_ratio, 4);
      new.metadata := jsonb_set(
        new.metadata,
        '{base_development_before_staff}',
        to_jsonb(to_char(v_base_development_before_staff, 'FM999999990.0000')),
        true
      );
    end if;

    if v_development_value_base is not null then
      v_development_value_base := round(v_development_value_base * v_weather_ratio, 4);
      new.metadata := jsonb_set(
        new.metadata,
        '{development_value_base}',
        to_jsonb(to_char(v_development_value_base, 'FM999999990.0000')),
        true
      );
    end if;
  end if;

  new.fatigue_load := greatest(
    0,
    coalesce(new.fatigue_load, 0) - v_old_weather_fatigue_delta + v_new_weather_fatigue_delta
  );

  new.metadata := jsonb_set(
    new.metadata,
    '{weather_state}',
    to_jsonb(v_effect.normalized_weather_state),
    true
  );

  new.metadata := jsonb_set(
    new.metadata,
    '{weather_skill_modifier}',
    to_jsonb(to_char(v_new_weather_skill_modifier, 'FM999999990.0000')),
    true
  );

  new.metadata := jsonb_set(
    new.metadata,
    '{weather_fatigue_delta}',
    to_jsonb(v_new_weather_fatigue_delta::text),
    true
  );

  new.metadata := jsonb_set(
    new.metadata,
    '{weather_risk_level}',
    to_jsonb(v_effect.risk_level),
    true
  );

  new.metadata := jsonb_set(
    new.metadata,
    '{weather_sickness_risk_pct}',
    to_jsonb(to_char(v_effect.sickness_risk_pct, 'FM999999990.00')),
    true
  );

  new.metadata := jsonb_set(
    new.metadata,
    '{weather_injury_risk_pct}',
    to_jsonb(to_char(v_effect.injury_risk_pct, 'FM999999990.00')),
    true
  );

  new.metadata := jsonb_set(
    new.metadata,
    '{weather_mechanical_risk_pct}',
    to_jsonb(to_char(v_effect.mechanical_risk_pct, 'FM999999990.00')),
    true
  );

  new.metadata := jsonb_set(
    new.metadata,
    '{weather_warning}',
    to_jsonb(v_effect.should_warn),
    true
  );

  new.metadata := jsonb_set(
    new.metadata,
    '{weather_effect_version}',
    to_jsonb('training_camp_weather_effects_v1'::text),
    true
  );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_apply_regular_training_staff_boosts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_club_id uuid;
  v_birth_date date;
  v_rider_age integer := 0;

  v_training_multiplier numeric := 1.0;
  v_development_multiplier numeric := 1.0;
  v_youth_multiplier numeric := 1.0;
  v_applied_youth_multiplier numeric := 1.0;
  v_combined_multiplier numeric := 1.0;

  v_base_before_staff numeric := 0;
  v_final_development_value numeric := 0;
  v_staff_bonus_added numeric := 0;
  v_staff_bonus_pct numeric := 0;
begin
  if new.source is distinct from 'regular_training' then
    return new;
  end if;

  if coalesce(new.activity_type, '') <> 'training' then
    return new;
  end if;

  if coalesce(new.participated, false) = false then
    return new;
  end if;

  if lower(coalesce(new.metadata->>'development_eligible', 'true')) in ('false', '0', 'no') then
    return new;
  end if;

  if lower(coalesce(new.metadata->>'regular_staff_boost_applied', 'false')) in ('true', '1', 'yes') then
    return new;
  end if;

  v_base_before_staff := coalesce(
    nullif(new.metadata->>'base_development_before_staff', '')::numeric,
    nullif(new.metadata->>'development_value_base', '')::numeric,
    0
  );

  if v_base_before_staff <= 0 then
    return new;
  end if;

  select
    cr.club_id,
    r.birth_date
  into
    v_club_id,
    v_birth_date
  from public.club_riders cr
  join public.riders r
    on r.id = cr.rider_id
  join public.clubs c
    on c.id = cr.club_id
  where cr.rider_id = new.rider_id
    and c.deleted_at is null
  limit 1;

  if v_club_id is null then
    return new;
  end if;

  select
    coalesce(e.training_efficiency_multiplier, 1.0),
    coalesce(e.development_multiplier, 1.0),
    coalesce(e.youth_dev_multiplier, 1.0)
  into
    v_training_multiplier,
    v_development_multiplier,
    v_youth_multiplier
  from public.get_head_coach_effects(v_club_id) e
  limit 1;

  v_training_multiplier := coalesce(v_training_multiplier, 1.0);
  v_development_multiplier := coalesce(v_development_multiplier, 1.0);
  v_youth_multiplier := coalesce(v_youth_multiplier, 1.0);

  if v_birth_date is not null and new.activity_date is not null then
    v_rider_age := extract(year from age(new.activity_date, v_birth_date))::int;
  end if;

  if v_rider_age > 0 and v_rider_age <= 23 then
    v_applied_youth_multiplier := v_youth_multiplier;
  else
    v_applied_youth_multiplier := 1.0;
  end if;

  v_combined_multiplier :=
    v_training_multiplier
    * v_development_multiplier
    * v_applied_youth_multiplier;

  v_final_development_value := round(v_base_before_staff * v_combined_multiplier, 4);
  v_staff_bonus_added := round(v_final_development_value - v_base_before_staff, 4);
  v_staff_bonus_pct := round((v_combined_multiplier - 1.0) * 100.0, 2);

  new.metadata :=
    coalesce(new.metadata, '{}'::jsonb)
    || jsonb_build_object(
      'base_development_before_staff', round(v_base_before_staff, 4),
      'development_value_base', v_final_development_value,
      'staff_development_bonus_pct', v_staff_bonus_pct,
      'staff_bonus_added', v_staff_bonus_added,
      'staff_training_multiplier', round(v_training_multiplier, 4),
      'staff_development_multiplier', round(v_development_multiplier, 4),
      'staff_youth_multiplier', round(v_applied_youth_multiplier, 4),
      'regular_staff_boost_applied', true,
      'regular_staff_boost_version', 'regular_head_coach_staff_boost_v1'
    );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_head_coach_effects(p_club_id uuid, p_effective_date date)
 RETURNS TABLE(staff_id uuid, staff_name text, specialization text, training_efficiency_multiplier numeric, development_multiplier numeric, overload_risk_multiplier numeric, youth_dev_multiplier numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_effective_date date := p_effective_date;
  v_club_type text := 'main';
  v_parent_club_id uuid := null;
  v_staff_club_id uuid := p_club_id;
  v_expected_head_role text := 'head_coach';
  v_expected_scope text := 'first_team';
  v_staff record;
  v_primary_staff_id uuid := null;
  v_primary_staff_name text := null;
  v_primary_specialization text := null;
  v_available_trainer_count integer := 0;
  v_training_output_pct numeric := 0;
  v_development_support_pct numeric := 0;
  v_overload_risk_reduction_pct numeric := 0;
  v_raw_training_pct numeric := 0;
  v_raw_development_pct numeric := 0;
  v_raw_overload_pct numeric := 0;
  v_assignment_factor numeric := 1.0;
  v_availability_factor numeric := 1.0;
  v_has_active_course boolean := false;
begin
  if p_club_id is null then return; end if;

  if v_effective_date is null then
    v_effective_date := public.get_current_game_date_date();
  end if;
  if v_effective_date is null then return; end if;

  select coalesce(c.club_type, 'main'), c.parent_club_id
  into v_club_type, v_parent_club_id
  from public.clubs c
  where c.id = p_club_id
  limit 1;

  if v_club_type = 'developing' then
    v_staff_club_id := coalesce(v_parent_club_id, p_club_id);
    v_expected_head_role := 'u23_head_coach';
    v_expected_scope := 'u23';
  else
    v_staff_club_id := p_club_id;
    v_expected_head_role := 'head_coach';
    v_expected_scope := 'first_team';
  end if;

  for v_staff in
    select
      cs.id,
      cs.staff_name,
      cs.specialization,
      cs.role_type,
      cs.team_scope,
      cs.expertise,
      cs.experience,
      cs.potential,
      cs.leadership,
      cs.efficiency,
      cs.loyalty
    from public.club_staff cs
    where cs.club_id in (p_club_id, v_staff_club_id)
      and cs.role_type in (v_expected_head_role, 'trainer')
      and coalesce(cs.is_active, false) = true
      and cs.team_scope::text in (v_expected_scope, 'all')
    order by
      case when cs.role_type = v_expected_head_role then 0 else 1 end,
      case when cs.team_scope::text = 'all' then 0 else 1 end,
      cs.staff_name
  loop
    if v_primary_staff_id is null then
      v_primary_staff_id := v_staff.id;
      v_primary_staff_name := v_staff.staff_name;
      v_primary_specialization := v_staff.specialization;
    end if;

    v_assignment_factor := coalesce(
      public.get_staff_assignment_availability_factor(v_staff.id, v_effective_date),
      1.0
    );

    select exists (
      select 1
      from public.staff_courses sc
      where sc.staff_id = v_staff.id
        and sc.status = 'active'
        and sc.started_game_date <= v_effective_date
        and sc.completes_on_game_date >= v_effective_date
    ) into v_has_active_course;

    if v_has_active_course then v_assignment_factor := 0; end if;
    v_availability_factor := least(1.0, greatest(0.0, coalesce(v_assignment_factor, 1.0)));

    if v_staff.role_type = v_expected_head_role then
      v_raw_training_pct := least(10, greatest(0, round(coalesce(v_staff.expertise, 0)::numeric / 10.0)));
      v_raw_development_pct := least(10, greatest(0, round(coalesce(v_staff.potential, 0)::numeric / 20.0)));
      if v_club_type = 'developing' then
        v_raw_development_pct := round(
          v_raw_development_pct * public.youth_academy_u23_head_coach_development_multiplier_v1(p_club_id),
          2
        );
      end if;
      v_raw_overload_pct := least(10, greatest(0, round((coalesce(v_staff.efficiency, 0)::numeric + public.team_policy_staff_quality_bonus_v1(v_staff_club_id)) / 20.0)));
    elsif v_staff.role_type = 'trainer' then
      v_raw_training_pct := least(5, greatest(0, round(coalesce(v_staff.expertise, 0)::numeric / 25.0)));
      v_raw_development_pct := least(5, greatest(0, round(coalesce(v_staff.potential, 0)::numeric / 25.0)));
      v_raw_overload_pct := least(5, greatest(0, round(coalesce(v_staff.efficiency, 0)::numeric / 40.0)));
      if v_availability_factor > 0 then
        v_available_trainer_count := v_available_trainer_count + 1;
      end if;
    end if;

    v_training_output_pct := v_training_output_pct + (v_raw_training_pct * v_availability_factor);
    v_development_support_pct := v_development_support_pct + (v_raw_development_pct * v_availability_factor);
    v_overload_risk_reduction_pct := v_overload_risk_reduction_pct + (v_raw_overload_pct * v_availability_factor);
  end loop;

  if v_primary_staff_id is null then return; end if;

  staff_id := v_primary_staff_id;
  staff_name := case
    when v_available_trainer_count > 0 then v_primary_staff_name || ' + ' || v_available_trainer_count::text || ' Trainer'
    else v_primary_staff_name
  end;
  specialization := case
    when v_available_trainer_count > 0 then 'Coaching Staff'
    else coalesce(v_primary_specialization, 'Coaching Staff')
  end;
  training_efficiency_multiplier := round(1 + (v_training_output_pct / 100.0), 4);
  development_multiplier := round(1 + (v_development_support_pct / 100.0), 4);
  overload_risk_multiplier := round(1 - (v_overload_risk_reduction_pct / 100.0), 4);
  youth_dev_multiplier := 1.0000;
  return next;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_process_weekly_staff_wages()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_current_game_date date;
  v_iso_dow integer;
  v_payroll_date date;
  v_week_key text;
  r record;
  v_existing_transaction_id uuid;
  v_charge_result jsonb;
  v_clubs_processed integer := 0;
  v_clubs_charged integer := 0;
  v_clubs_skipped_already_charged integer := 0;
  v_clubs_skipped_no_staff integer := 0;
begin
  -- Same lock as rider payroll, acquired before club finance work.
  perform pg_advisory_xact_lock(
    hashtextextended('finance_weekly_payroll_global_v1', 0)
  );

  v_current_game_date := public.get_current_game_date_date();

  if v_current_game_date is null then
    return jsonb_build_object(
      'ok', false,
      'reason', 'game_date_missing'
    );
  end if;

  v_iso_dow := extract(isodow from v_current_game_date)::int;
  v_payroll_date := v_current_game_date - ((v_iso_dow - 1) * interval '1 day')::interval;
  v_week_key := to_char(v_payroll_date, 'IYYY-IW');

  if v_current_game_date < v_payroll_date then
    return jsonb_build_object(
      'ok', true,
      'did_run', false,
      'reason', 'before_payroll_date',
      'current_game_date', v_current_game_date,
      'payroll_date', v_payroll_date,
      'week_key', v_week_key
    );
  end if;

  for r in
    select c.id as club_id
    from public.clubs c
    where c.deleted_at is null
      and c.owner_user_id is not null
      and coalesce(c.is_ai, false) = false
    order by c.id
  loop
    v_clubs_processed := v_clubs_processed + 1;

    select t.id
    into v_existing_transaction_id
    from finance.transactions t
    where t.type = 'staff_salary_payday'
      and coalesce(
        t.metadata ->> 'charged_club_id',
        t.metadata ->> 'club_id'
      ) = r.club_id::text
      and t.idempotency_key in (
        'staff_salary_payday:' || r.club_id::text || ':' || v_week_key,
        'staff_salary_payday:' || r.club_id::text || ':' || v_week_key || ':backfill'
      )
    order by t.created_at desc
    limit 1;

    if v_existing_transaction_id is not null then
      v_clubs_skipped_already_charged := v_clubs_skipped_already_charged + 1;
      continue;
    end if;

    select public.finance_charge_club_staff_wages(
      r.club_id,
      'staff_salary_payday:' || r.club_id::text || ':' || v_week_key
    )
    into v_charge_result;

    if coalesce((v_charge_result ->> 'charged')::boolean, false) = true then
      v_clubs_charged := v_clubs_charged + 1;
    elsif coalesce((v_charge_result ->> 'already_charged')::boolean, false) = true then
      v_clubs_skipped_already_charged := v_clubs_skipped_already_charged + 1;
    else
      v_clubs_skipped_no_staff := v_clubs_skipped_no_staff + 1;
    end if;
  end loop;

  insert into public.staff_payroll_runs (
    week_key,
    processed_at
  )
  values (
    v_week_key,
    now()
  )
  on conflict (week_key)
  do update set
    processed_at = excluded.processed_at;

  return jsonb_build_object(
    'ok', true,
    'did_run', true,
    'week_key', v_week_key,
    'payroll_date', v_payroll_date,
    'current_game_date', v_current_game_date,
    'clubs_processed', v_clubs_processed,
    'clubs_charged', v_clubs_charged,
    'clubs_skipped_already_charged', v_clubs_skipped_already_charged,
    'clubs_skipped_no_staff', v_clubs_skipped_no_staff
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public._finance_charge_club_rider_wages_core_v1(p_club_id uuid, p_idempotency_key text, p_payroll_date date DEFAULT NULL::date)
 RETURNS TABLE(transaction_id uuid, total_wages bigint, rider_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'finance', 'pg_temp'
AS $function$
declare
  v_game_date date;
  v_total_wages bigint := 0;
  v_rider_count integer := 0;

  v_main_squad_rider_count integer := 0;
  v_developing_squad_rider_count integer := 0;
  v_contract_only_rider_count integer := 0;

  v_main_squad_wages bigint := 0;
  v_developing_squad_wages bigint := 0;
  v_contract_only_wages bigint := 0;

  v_transaction_id uuid;
  v_existing_transaction_id uuid;
  v_metadata jsonb;
  v_display_timestamp jsonb;

  v_finance_club_id uuid;
  v_requested_club_type text;

  v_club_account_id uuid;
  v_sink_account_id uuid;
begin
  v_game_date := coalesce(p_payroll_date, public.get_current_game_date_date());

  if v_game_date is null then
    raise exception 'finance_charge_club_rider_wages: could not resolve payroll game date';
  end if;

  /*
    Finance club rule:
    - If requested club is main, charge that club.
    - If requested club is developing, charge its parent main club.
  */
  select
    case
      when c.club_type = 'developing' then c.parent_club_id
      else c.id
    end,
    c.club_type::text
  into
    v_finance_club_id,
    v_requested_club_type
  from public.clubs c
  where c.id = p_club_id
  limit 1;

  if v_finance_club_id is null then
    raise exception 'Could not resolve finance club for club %', p_club_id;
  end if;

  /*
    Payroll scope:
    - Main club riders
    - Developing-team riders where developing.parent_club_id = main club
    - Contract-only fallback for older data where rider_contracts exists but club_riders is missing

    Salary source priority:
    1. active contract for the rider's squad club
    2. active contract for the finance/main club
    3. riders.salary
  */
  with squad_clubs as (
    select
      c.id as club_id,
      c.club_type::text as squad_type
    from public.clubs c
    where c.deleted_at is null
      and coalesce(c.is_active, true) = true
      and (
        c.id = v_finance_club_id
        or (
          c.club_type = 'developing'
          and c.parent_club_id = v_finance_club_id
        )
      )
  ),
  candidate_riders as (
    select
      cr.rider_id,
      cr.club_id as squad_club_id,
      sc.squad_type,
      1 as source_priority,
      cr.created_at
    from public.club_riders cr
    join squad_clubs sc
      on sc.club_id = cr.club_id

    union all

    select
      rc.rider_id,
      rc.club_id as squad_club_id,
      'contract_only'::text as squad_type,
      2 as source_priority,
      rc.created_at
    from public.rider_contracts rc
    where rc.club_id = v_finance_club_id
      and rc.status = 'active'
      and coalesce(rc.salary_weekly, 0) > 0
  ),
  assigned_riders as (
    select distinct on (cr.rider_id)
      cr.rider_id,
      cr.squad_club_id,
      cr.squad_type
    from candidate_riders cr
    order by
      cr.rider_id,
      cr.source_priority asc,
      cr.created_at desc nulls last
  ),
  payroll_rows as (
    select
      ar.rider_id,
      case
        when ar.squad_type = 'main' then 'main'
        when ar.squad_type = 'developing' then 'developing'
        else 'contract_only'
      end as payroll_squad_type,
      coalesce(rc.salary_weekly, r.salary, 0)::bigint as salary_weekly
    from assigned_riders ar
    join public.riders r
      on r.id = ar.rider_id
    left join lateral (
      select rc.salary_weekly
      from public.rider_contracts rc
      where rc.rider_id = ar.rider_id
        and rc.status = 'active'
        and rc.club_id in (ar.squad_club_id, v_finance_club_id)
      order by
        case when rc.club_id = ar.squad_club_id then 0 else 1 end,
        rc.created_at desc nulls last
      limit 1
    ) rc on true
  )
  select
    coalesce(sum(pr.salary_weekly) filter (where pr.salary_weekly > 0), 0)::bigint,
    count(*) filter (where pr.salary_weekly > 0)::integer,

    count(*) filter (
      where pr.salary_weekly > 0
        and pr.payroll_squad_type = 'main'
    )::integer,

    count(*) filter (
      where pr.salary_weekly > 0
        and pr.payroll_squad_type = 'developing'
    )::integer,

    count(*) filter (
      where pr.salary_weekly > 0
        and pr.payroll_squad_type = 'contract_only'
    )::integer,

    coalesce(sum(pr.salary_weekly) filter (
      where pr.salary_weekly > 0
        and pr.payroll_squad_type = 'main'
    ), 0)::bigint,

    coalesce(sum(pr.salary_weekly) filter (
      where pr.salary_weekly > 0
        and pr.payroll_squad_type = 'developing'
    ), 0)::bigint,

    coalesce(sum(pr.salary_weekly) filter (
      where pr.salary_weekly > 0
        and pr.payroll_squad_type = 'contract_only'
    ), 0)::bigint
  into
    v_total_wages,
    v_rider_count,
    v_main_squad_rider_count,
    v_developing_squad_rider_count,
    v_contract_only_rider_count,
    v_main_squad_wages,
    v_developing_squad_wages,
    v_contract_only_wages
  from payroll_rows pr;

  if v_rider_count = 0 or v_total_wages <= 0 then
    return query
    select null::uuid, 0::bigint, 0::integer;
    return;
  end if;

  -- Duplicate protection per main/finance club + payroll date.
  select t.id
  into v_existing_transaction_id
  from finance.transactions t
  where t.type = 'rider_salary_payday'
    and coalesce(t.metadata ->> 'charged_club_id', t.metadata ->> 'club_id', '') = v_finance_club_id::text
    and coalesce(t.metadata ->> 'game_date', t.metadata ->> 'in_game_date', '') = v_game_date::text
    and coalesce(t.metadata ->> 'is_reversal', 'false') <> 'true'
  order by t.created_at desc
  limit 1;

  if v_existing_transaction_id is not null then
    return query
    select v_existing_transaction_id, v_total_wages, v_rider_count;
    return;
  end if;

  if p_idempotency_key is not null then
    select t.id
    into v_existing_transaction_id
    from finance.transactions t
    where t.idempotency_key = p_idempotency_key
    limit 1;

    if v_existing_transaction_id is not null then
      return query
      select v_existing_transaction_id, v_total_wages, v_rider_count;
      return;
    end if;
  end if;

  -- Mandatory payroll funding check.
  declare
    v_funds_result jsonb;
  begin
    v_funds_result := public.finance_ensure_mandatory_funds(
      v_finance_club_id,
      v_total_wages,
      'rider_salary_payday',
      v_game_date::text,
      'mandatory_funds:rider_salary_payday:' ||
        v_finance_club_id::text || ':' ||
        v_game_date::text
    );

    if coalesce((v_funds_result ->> 'ok')::boolean, false) is not true then
      return query
      select
        null::uuid,
        v_total_wages::bigint,
        v_rider_count::integer;
      return;
    end if;
  end;

  v_club_account_id := public.finance_get_or_create_club_account(
    v_finance_club_id,
    'CASH',
    'main'
  );

  select a.id
  into v_sink_account_id
  from finance.accounts a
  where a.system_code = 'SINK'
    and a.currency = 'CASH'
    and a.kind = 'main'
  limit 1;

  if v_sink_account_id is null then
    raise exception 'SINK cash account not found';
  end if;

  -- Payroll is displayed as Monday 00:00 in-game time.
  v_display_timestamp :=
    jsonb_build_object(
      'season', extract(year from v_game_date)::integer - 1999,
      'month', extract(month from v_game_date)::integer,
      'day', extract(day from v_game_date)::integer,
      'hour', 0,
      'minute', 0
    );

  v_metadata :=
    jsonb_build_object(
      'game_date', v_game_date,
      'in_game_date', v_game_date,
      'display_timestamp', v_display_timestamp,
      'game_date_parts', v_display_timestamp,

      'requested_club_id', p_club_id,
      'charged_club_id', v_finance_club_id,
      'requested_club_type', v_requested_club_type,

      'rider_count', v_rider_count,
      'total_wages', v_total_wages,

      'main_squad_rider_count', v_main_squad_rider_count,
      'developing_squad_rider_count', v_developing_squad_rider_count,
      'contract_only_rider_count', v_contract_only_rider_count,

      'main_squad_wages', v_main_squad_wages,
      'developing_squad_wages', v_developing_squad_wages,
      'contract_only_wages', v_contract_only_wages,

      'payroll_scope', 'main_plus_developing_squads',
      'salary_source_policy', 'active_contract_else_riders_salary',
      'source', 'weekly_rider_payroll_v2'
    );

  insert into finance.transactions (
    id,
    type,
    created_by,
    idempotency_key,
    metadata
  )
  values (
    gen_random_uuid(),
    'rider_salary_payday',
    auth.uid(),
    p_idempotency_key,
    v_metadata
  )
  returning id into v_transaction_id;

  insert into finance.entries (
    transaction_id,
    account_id,
    amount,
    memo
  )
  values
    (v_transaction_id, v_club_account_id, -v_total_wages, 'rider salary payday debit'),
    (v_transaction_id, v_sink_account_id,  v_total_wages, 'rider salary payday credit');

  return query
  select v_transaction_id, v_total_wages, v_rider_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.can_hire_staff_role(p_club_id uuid, p_role_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_limit record;
begin
  select *
  into v_limit
  from public.get_staff_role_limits(p_club_id)
  where role_type = p_role_type
  limit 1;

  if v_limit.role_type is null then
    return jsonb_build_object(
      'ok', false,
      'reason', 'invalid_role',
      'message', 'This staff role is not recognized.',
      'role_type', p_role_type
    );
  end if;

  if coalesce(v_limit.current_capacity, 0) <= 0 then
    return jsonb_build_object(
      'ok', false,
      'reason', 'role_locked',
      'message', coalesce(v_limit.locked_reason, 'This staff role is not unlocked yet.'),
      'role_type', v_limit.role_type,
      'assigned_count', v_limit.assigned_count,
      'current_capacity', v_limit.current_capacity
    );
  end if;

  if coalesce(v_limit.assigned_count, 0) >= coalesce(v_limit.current_capacity, 0) then
    return jsonb_build_object(
      'ok', false,
      'reason', 'role_capacity_full',
      'message', 'No open staff slot is available for this role.',
      'role_type', v_limit.role_type,
      'assigned_count', v_limit.assigned_count,
      'current_capacity', v_limit.current_capacity
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'reason', 'role_capacity_available',
    'message', 'Staff role slot is available.',
    'role_type', v_limit.role_type,
    'assigned_count', v_limit.assigned_count,
    'current_capacity', v_limit.current_capacity,
    'open_slots', v_limit.open_slots
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_enforce_staff_role_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_check jsonb;
begin
  -- Inactive rows do not consume a staff slot.
  if coalesce(new.is_active, true) = false then
    return new;
  end if;

  -- Updating normal fields on an already-active staff member should not be blocked.
  -- Example: salary update, contract update, notes update.
  if tg_op = 'UPDATE'
     and coalesce(old.is_active, true) = true
     and old.club_id is not distinct from new.club_id
     and old.role_type is not distinct from new.role_type
  then
    return new;
  end if;

  v_check := public.can_hire_staff_role(new.club_id, new.role_type);

  if coalesce((v_check ->> 'ok')::boolean, false) = false then
    raise exception 'Cannot hire staff role %. %',
      new.role_type,
      coalesce(v_check ->> 'message', 'No staff slot is available for this role.')
    using
      errcode = '23514',
      detail = v_check::text;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_staff_market_role_options(p_club_id uuid)
 RETURNS TABLE(role_type text, display_name text, role_group text, max_absolute integer, current_capacity integer, assigned_count integer, open_slots integer, is_unlocked boolean, is_hireable boolean, locked_reason text, facility_key text, gameplay_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return query
  select
    l.role_type,
    l.display_name,
    l.role_group,
    l.max_absolute,
    l.current_capacity,
    l.assigned_count,
    l.open_slots,
    l.is_unlocked,
    (l.is_unlocked = true and l.open_slots > 0) as is_hireable,
    l.locked_reason,
    l.facility_key,
    l.gameplay_status
  from public.get_staff_role_limits(p_club_id) l
  join public.staff_role_definitions d
    on d.role_type = l.role_type
  where d.is_market_role = true
  order by
    case l.role_type
      when 'head_coach' then 10
      when 'trainer' then 20
      when 'team_doctor' then 30
      when 'physio' then 40
      when 'mechanic' then 50
      when 'scout_analyst' then 60
      when 'nutritionist' then 70
      when 'sport_director' then 80
      when 'u23_head_coach' then 90
      else 999
    end;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_market_refill_available_candidates(p_role_type text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role text;
  v_target integer;
  v_current integer;
  v_missing integer;
  v_to_generate integer;
  v_i integer;
  v_country_code text;
  v_generated integer := 0;
  v_roles text[];
begin
  v_roles := array[
    'head_coach',
    'trainer',
    'team_doctor',
    'physio',
    'mechanic',
    'scout_analyst',
    'nutritionist',
    'sport_director',
    'u23_head_coach'
  ];

  if p_role_type is not null then
    if not (p_role_type = any(v_roles)) then
      raise exception 'Unknown staff role: %', p_role_type;
    end if;

    v_roles := array[p_role_type];
  end if;

  foreach v_role in array v_roles
  loop
    v_target := public.staff_market_target_available_count(v_role);

    select count(*)::integer
      into v_current
    from public.staff_candidates sc
    where sc.role_type = v_role
      and coalesce(sc.is_available, false) = true;

    v_missing := greatest(v_target - coalesce(v_current, 0), 0);

    -- Fill the entire deficit. The former per-refresh cap was the reason the
    -- market could contain only 5-10 candidates even with a 50-90 target.
    v_to_generate := v_missing;

    if v_to_generate > 0 then
      for v_i in 1..v_to_generate loop
        v_country_code := public.staff_market_pick_country_for_generation();

        perform public.insert_generated_staff_candidate(
          v_role,
          v_country_code,
          null
        );

        v_generated := v_generated + 1;
      end loop;
    end if;
  end loop;

  return v_generated;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.staff_market_run_daily_refresh(p_generate_count integer DEFAULT 20, p_lifetime_hours integer DEFAULT 48)
 RETURNS TABLE(game_date date, expired_count integer, generated_count integer, ok boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_game_date date;
  v_generated integer := 0;
begin
  v_game_date := public.get_current_game_date_date();

  -- Keep existing expiry behavior.
  -- We do not depend on its return type here.
  perform public.staff_market_expire_due_candidates();

  -- New controlled refill logic:
  -- Uses target stock + daily cap per role.
  v_generated := public.staff_market_refill_available_candidates(null);

  game_date := v_game_date;
  expired_count := 0;
  generated_count := v_generated;
  ok := true;

  return next;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_staff_candidate_profile(p_role_type text, p_country_code text, p_quality_tier text DEFAULT NULL::text)
 RETURNS TABLE(role_type text, specialization text, staff_name text, country_code text, expertise integer, experience integer, potential integer, leadership integer, efficiency integer, loyalty integer, salary_weekly integer, notes jsonb, first_name text, last_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role_type text := lower(trim(p_role_type));
  v_country_code text := coalesce(nullif(upper(trim(p_country_code)), ''), 'RS');

  v_first_names text[] := array[
    'Marco', 'Luca', 'Milan', 'Nikola', 'Ivan', 'Petar', 'Andrej', 'Stefan',
    'Carlos', 'Miguel', 'Luis', 'Javier', 'Thomas', 'Julien', 'Pierre',
    'Daniel', 'Martin', 'Jan', 'Erik', 'Sven', 'Mateo', 'Hugo'
  ];

  v_last_names text[] := array[
    'Bellini', 'Rossi', 'Kovacs', 'Petrovic', 'Moraru', 'Garcia', 'Sanchez',
    'Martin', 'Dubois', 'Moreau', 'Muller', 'Schmidt', 'Novak', 'Horvat',
    'Ilic', 'Nikolic', 'Font', 'Riba', 'Conti', 'Bianchi'
  ];

  v_specializations text[];
  v_role_salary_base numeric;
  v_base integer;
  v_score numeric;
begin
  if v_role_type = 'head_coach' then
    v_specializations := array['Youth Development', 'Training Systems', 'Race Preparation', 'Team Leadership', 'Recovery Planning'];
    v_role_salary_base := 700;

  elsif v_role_type = 'trainer' then
    v_specializations := array['Sprint Training', 'Climbing Training', 'Endurance Training', 'Time Trial Training', 'General Conditioning'];
    v_role_salary_base := 560;

  elsif v_role_type = 'team_doctor' then
    v_specializations := array['Sports Medicine', 'Injury Prevention', 'Illness Management', 'Recovery Medicine', 'Medical Planning'];
    v_role_salary_base := 650;

  elsif v_role_type = 'physio' then
    v_specializations := array['Rehabilitation', 'Massage Therapy', 'Mobility Work', 'Recovery Planning', 'Return-to-Fitness'];
    v_role_salary_base := 550;

  elsif v_role_type = 'mechanic' then
    v_specializations := array['Race Bikes', 'Repairs', 'Equipment Setup', 'Workshop Efficiency', 'Bike Reliability'];
    v_role_salary_base := 520;

  elsif v_role_type = 'scout_analyst' then
    v_specializations := array['Evaluation Accuracy', 'Scouting Network', 'Performance Data Analysis', 'Prospect Discovery'];
    v_role_salary_base := 500;

  elsif v_role_type = 'nutritionist' then
    v_specializations := array['Race Nutrition', 'Recovery Nutrition', 'Hydration Planning', 'Weight Management'];
    v_role_salary_base := 560;

  elsif v_role_type = 'sport_director' then
    v_specializations := array['Race Tactics', 'Teamwork', 'Domestique Coordination', 'Morale Management'];
    v_role_salary_base := 650;

  elsif v_role_type = 'u23_head_coach' then
    v_specializations := array['Youth Development', 'U23 Race Tactics', 'Talent Progression', 'Development Planning'];
    v_role_salary_base := 620;

  else
    raise exception 'Unsupported staff role: %', p_role_type;
  end if;

  v_base :=
    case lower(coalesce(p_quality_tier, 'mixed'))
      when 'elite' then 78
      when 'strong' then 68
      when 'solid' then 58
      when 'prospect' then 50
      else 54 + floor(random() * 18)::integer
    end;

  first_name := v_first_names[1 + floor(random() * array_length(v_first_names, 1))::integer];
  last_name := v_last_names[1 + floor(random() * array_length(v_last_names, 1))::integer];

  role_type := v_role_type;
  country_code := v_country_code;
  staff_name := first_name || ' ' || last_name;
  specialization := v_specializations[1 + floor(random() * array_length(v_specializations, 1))::integer];

  expertise := greatest(35, least(92, v_base + floor(random() * 17)::integer - 8));
  experience := greatest(35, least(92, v_base + floor(random() * 17)::integer - 8));
  potential := greatest(35, least(95, v_base + floor(random() * 20)::integer - 5));
  leadership := greatest(35, least(92, v_base + floor(random() * 17)::integer - 8));
  efficiency := greatest(35, least(92, v_base + floor(random() * 17)::integer - 8));
  loyalty := greatest(35, least(92, v_base + floor(random() * 17)::integer - 8));

  v_score :=
      expertise * 0.22
    + experience * 0.18
    + potential * 0.18
    + leadership * 0.14
    + efficiency * 0.18
    + loyalty * 0.10;

  salary_weekly := greatest(
    350,
    round(v_role_salary_base * (0.75 + (v_score / 100.0)))::integer
  );

  notes := jsonb_build_object(
    'generated_reason', 'staff_market_daily_refresh_v2',
    'generated_for_market', true,
    'quality_tier', coalesce(p_quality_tier, 'mixed'),
    'profile_version', 'new_staff_roles_v1'
  );

  return next;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.insert_generated_staff_candidate(p_role_type text, p_country_code text, p_quality_tier text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_profile record;
  v_identity record;
  v_candidate_id uuid;
  v_now_game_ts timestamp;
  v_birth_date date;
  v_lifetime_hours integer := 72;
begin
  select *
  into v_profile
  from public.generate_staff_candidate_profile(
    p_role_type,
    p_country_code,
    p_quality_tier
  );

  select *
  into v_identity
  from public.generate_staff_identity(p_country_code);

  v_now_game_ts := public.get_current_game_date_timestamp();
  v_birth_date := public.generate_staff_birth_date_v1(
    p_role_type,
    v_now_game_ts::date
  );

  insert into public.staff_candidates (
    role_type,
    specialization,
    staff_name,
    country_code,
    expertise,
    experience,
    potential,
    leadership,
    efficiency,
    loyalty,
    salary_weekly,
    is_available,
    notes,
    first_name,
    last_name,
    listed_at_game_ts,
    expires_at_game_ts,
    birth_date,
    market_region,
    created_at,
    updated_at
  )
  values (
    p_role_type,
    v_profile.specialization,
    concat_ws(' ', v_identity.first_name, v_identity.last_name),
    p_country_code,
    v_profile.expertise,
    v_profile.experience,
    v_profile.potential,
    v_profile.leadership,
    v_profile.efficiency,
    v_profile.loyalty,
    v_profile.salary_weekly,
    true,
    jsonb_build_object(
      'quality_tier', coalesce(p_quality_tier, 'mixed'),
      'profile_version', 'new_staff_roles_v1',
      'generated_reason', 'staff_market_daily_refresh_v2',
      'generated_for_market', true,
      'birth_date_source', 'generated_v1'
    ),
    v_identity.first_name,
    v_identity.last_name,
    v_now_game_ts,
    v_now_game_ts + make_interval(hours => v_lifetime_hours),
    v_birth_date,
    public.staff_market_region_from_country(p_country_code),
    now(),
    now()
  )
  returning id into v_candidate_id;

  return v_candidate_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_staff_market_candidates_for_club(p_club_id uuid, p_page integer DEFAULT 1, p_page_size integer DEFAULT 500)
 RETURNS TABLE(id uuid, role_type text, specialization text, first_name text, last_name text, staff_name text, country_code text, birth_date date, expertise smallint, experience smallint, potential smallint, leadership smallint, efficiency smallint, loyalty smallint, salary_weekly integer, is_available boolean, listed_at_game_ts timestamp without time zone, expires_at_game_ts timestamp without time zone, notes jsonb, market_region text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_region text;
  v_offset integer;
  v_is_premium boolean := false;
begin
  v_region := public.staff_market_region_for_club(p_club_id);
  v_offset := greatest(0,(greatest(p_page,1)-1)*greatest(p_page_size,1));

  select public.user_has_premium_access_v1(c.owner_user_id)
  into v_is_premium
  from public.clubs c
  where c.id=p_club_id;

  return query
  select
    sc.id, sc.role_type, sc.specialization, sc.first_name, sc.last_name,
    sc.staff_name, sc.country_code, sc.birth_date, sc.expertise, sc.experience,
    sc.potential, sc.leadership, sc.efficiency, sc.loyalty, sc.salary_weekly,
    sc.is_available, sc.listed_at_game_ts, sc.expires_at_game_ts, sc.notes,
    public.staff_market_region_from_country(sc.country_code)
  from public.staff_candidates sc
  where sc.is_available=true
    and (sc.role_type <> 'u23_head_coach' or coalesce(v_is_premium,false))
    and public.staff_market_candidate_visible_to_club(p_club_id,sc.country_code)
    and (
      v_region is null
      or public.staff_market_region_from_country(sc.country_code)=v_region
    )
  order by sc.expires_at_game_ts asc nulls last, sc.role_type asc,
           sc.salary_weekly desc, sc.staff_name asc
  limit greatest(p_page_size,1)
  offset v_offset;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_team_doctor_effects(p_club_id uuid, p_effective_date date)
 RETURNS TABLE(staff_id uuid, staff_name text, specialization text, risk_multiplier numeric, recovery_duration_multiplier numeric, daily_recovery_bonus integer, fatigue_floor_reduction integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_effective_date date := p_effective_date;
  v_staff record;

  v_primary_staff_id uuid := null;
  v_primary_staff_name text := null;
  v_available_physio_count integer := 0;
  v_available_nutritionist_count integer := 0;

  v_risk_reduction_pct numeric := 0;
  v_recovery_duration_reduction_pct numeric := 0;
  v_daily_recovery_bonus numeric := 0;
  v_fatigue_floor_reduction numeric := 0;

  v_assignment_factor numeric := 1.0;
  v_availability_factor numeric := 1.0;
  v_has_active_course boolean := false;

  v_staff_risk_pct numeric := 0;
  v_staff_recovery_pct numeric := 0;
  v_staff_daily_recovery numeric := 0;
  v_staff_floor_reduction numeric := 0;
begin
  if p_club_id is null then
    return;
  end if;

  if v_effective_date is null then
    v_effective_date := public.get_current_game_date_date();
  end if;

  if v_effective_date is null then
    return;
  end if;

  for v_staff in
    select
      cs.id,
      cs.staff_name,
      cs.specialization,
      cs.role_type,
      cs.expertise,
      cs.experience,
      cs.potential,
      cs.leadership,
      cs.efficiency,
      cs.loyalty
    from public.club_staff cs
    where cs.club_id = p_club_id
      and cs.role_type in ('team_doctor', 'physio', 'nutritionist')
      and coalesce(cs.is_active, false) = true
    order by
      case
        when cs.role_type = 'team_doctor' then 0
        when cs.role_type = 'physio' then 1
        when cs.role_type = 'nutritionist' then 2
        else 3
      end,
      cs.staff_name
  loop
    if v_primary_staff_id is null then
      v_primary_staff_id := v_staff.id;
      v_primary_staff_name := v_staff.staff_name;
    end if;

    v_assignment_factor := coalesce(
      public.get_staff_assignment_availability_factor(v_staff.id, v_effective_date),
      1.0
    );

    select exists (
      select 1
      from public.staff_courses sc
      where sc.staff_id = v_staff.id
        and sc.status = 'active'
        and sc.started_game_date <= v_effective_date
        and sc.completes_on_game_date >= v_effective_date
    )
    into v_has_active_course;

    if v_has_active_course then
      v_assignment_factor := 0;
    end if;

    v_availability_factor := least(1.0, greatest(0.0, coalesce(v_assignment_factor, 1.0)));

    v_staff_risk_pct := 0;
    v_staff_recovery_pct := 0;
    v_staff_daily_recovery := 0;
    v_staff_floor_reduction := 0;

    if v_staff.role_type = 'team_doctor' then
      v_staff_risk_pct :=
        least(12, greatest(0, round(coalesce(v_staff.expertise, 0)::numeric / 10.0)));

      v_staff_recovery_pct :=
        least(12, greatest(0, round((coalesce(v_staff.efficiency, 0)::numeric + public.team_policy_staff_quality_bonus_v1(p_club_id)) / 12.0)));

      v_staff_daily_recovery :=
        least(4, greatest(0, floor(coalesce(v_staff.experience, 0)::numeric / 30.0)));

      v_staff_floor_reduction :=
        least(4, greatest(0, floor(coalesce(v_staff.experience, 0)::numeric / 28.0)));

    elsif v_staff.role_type = 'physio' then
      v_staff_risk_pct :=
        least(4, greatest(0, round((coalesce(v_staff.efficiency, 0)::numeric + public.team_policy_staff_quality_bonus_v1(p_club_id)) / 35.0)));

      v_staff_recovery_pct :=
        least(8, greatest(0, round(coalesce(v_staff.expertise, 0)::numeric / 14.0)));

      v_staff_daily_recovery :=
        least(3, greatest(0, floor((coalesce(v_staff.efficiency, 0)::numeric + public.team_policy_staff_quality_bonus_v1(p_club_id)) / 28.0)));

      v_staff_floor_reduction :=
        least(3, greatest(0, floor(coalesce(v_staff.experience, 0)::numeric / 35.0)));

      if v_availability_factor > 0 then
        v_available_physio_count := v_available_physio_count + 1;
      end if;

    elsif v_staff.role_type = 'nutritionist' then
      v_staff_risk_pct :=
        least(3, greatest(0, round(coalesce(v_staff.loyalty, 0)::numeric / 40.0)));

      v_staff_recovery_pct :=
        least(4, greatest(0, round((coalesce(v_staff.efficiency, 0)::numeric + public.team_policy_staff_quality_bonus_v1(p_club_id)) / 30.0)));

      v_staff_daily_recovery :=
        least(3, greatest(0, floor(coalesce(v_staff.expertise, 0)::numeric / 30.0)));

      v_staff_floor_reduction :=
        least(2, greatest(0, floor((coalesce(v_staff.efficiency, 0)::numeric + public.team_policy_staff_quality_bonus_v1(p_club_id)) / 40.0)));

      if v_availability_factor > 0 then
        v_available_nutritionist_count := v_available_nutritionist_count + 1;
      end if;
    end if;

    v_risk_reduction_pct :=
      v_risk_reduction_pct + (v_staff_risk_pct * v_availability_factor);

    v_recovery_duration_reduction_pct :=
      v_recovery_duration_reduction_pct + (v_staff_recovery_pct * v_availability_factor);

    v_daily_recovery_bonus :=
      v_daily_recovery_bonus + (v_staff_daily_recovery * v_availability_factor);

    v_fatigue_floor_reduction :=
      v_fatigue_floor_reduction + (v_staff_floor_reduction * v_availability_factor);
  end loop;

  if v_primary_staff_id is null then
    return;
  end if;

  staff_id := v_primary_staff_id;

  staff_name :=
    v_primary_staff_name
    || case when v_available_physio_count > 0 then ' + ' || v_available_physio_count::text || ' Physio' else '' end
    || case when v_available_nutritionist_count > 0 then ' + ' || v_available_nutritionist_count::text || ' Nutritionist' else '' end;

  specialization := 'Medical Staff';

  risk_multiplier :=
    round(1 - (least(30, greatest(0, v_risk_reduction_pct)) / 100.0), 4);

  recovery_duration_multiplier :=
    round(1 - (least(30, greatest(0, v_recovery_duration_reduction_pct)) / 100.0), 4);

  daily_recovery_bonus :=
    least(10, greatest(0, round(v_daily_recovery_bonus)))::integer;

  fatigue_floor_reduction :=
    least(10, greatest(0, round(v_fatigue_floor_reduction)))::integer;

  return next;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.start_club_asset_delivery_v2(p_club_id uuid, p_asset_key text, p_asset_level smallint, p_quantity integer DEFAULT 1)
 RETURNS club_infrastructure_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$declare
  v_uid uuid;
  v_key text;
  v_quantity integer;
  v_cfg public.infrastructure_asset_config%rowtype;
  v_current_game_date date;
  v_started_game_date date;
  v_complete_game_date date;
  v_existing_count integer := 0;
  v_pending_count integer := 0;
  v_total_after_order integer := 0;
  v_job public.club_infrastructure_jobs%rowtype;
  v_finance_tx_id uuid;
begin
  v_uid := auth.uid();

  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  v_key := lower(trim(coalesce(p_asset_key, '')));
  v_quantity := greatest(coalesce(p_quantity, 1), 1);

  if v_key = 'team_car_fleet' then
    v_key := 'team_car';
  end if;

  if v_key = 'logistics_truck' then
    raise exception 'Logistics Truck has been removed from the game';
  end if;

  if v_key not in (
    'team_car',
    'team_bus',
    'equipment_van',
    'mobile_workshop',
    'medical_van'
  ) then
    raise exception 'Unsupported asset delivery key: %', p_asset_key;
  end if;

  if p_asset_level is null or p_asset_level <= 0 then
    raise exception 'Asset level must be provided';
  end if;

  if not exists (
    select 1
    from public.clubs c
    left join public.club_memberships cm
      on cm.club_id = c.id
     and cm.user_id = v_uid
    where c.id = p_club_id
      and (
        c.owner_user_id = v_uid
        or cm.user_id is not null
      )
  ) then
    raise exception 'Not allowed to manage infrastructure assets for this club';
  end if;

  select *
  into v_cfg
  from public.infrastructure_asset_config
  where asset_key = v_key
    and asset_level = p_asset_level;

  if not found then
    raise exception 'Missing asset configuration for %, level %', v_key, p_asset_level;
  end if;

  v_current_game_date := public.get_current_game_date_date();

  if v_current_game_date is null then
    raise exception 'start_club_asset_delivery_v2: could not resolve current game date';
  end if;

  if v_key = 'team_car' then
    select count(*)
    into v_existing_count
    from public.club_team_cars
    where club_id = p_club_id
      and status <> 'sold';

  elsif v_key = 'team_bus' then
    select count(*)
    into v_existing_count
    from public.club_team_buses
    where club_id = p_club_id
      and status <> 'sold';

  elsif v_key = 'equipment_van' then
    select count(*)
    into v_existing_count
    from public.club_equipment_vans
    where club_id = p_club_id
      and status <> 'sold';

  elsif v_key = 'mobile_workshop' then
    select count(*)
    into v_existing_count
    from public.club_mobile_workshops
    where club_id = p_club_id
      and status <> 'sold';

  elsif v_key = 'medical_van' then
    select count(*)
    into v_existing_count
    from public.club_medical_vans
    where club_id = p_club_id
      and status <> 'sold';
  end if;

  select coalesce(sum(coalesce(j.asset_quantity, 1)), 0)::integer
  into v_pending_count
  from public.club_infrastructure_jobs j
  where j.club_id = p_club_id
    and j.job_type = 'asset_delivery'
    and j.target_key = v_key
    and j.status = 'pending';

  v_total_after_order := v_existing_count + v_pending_count + v_quantity;

  if v_total_after_order > v_cfg.max_total_quantity then
    raise exception
      'Garage limit reached for %. Existing %, pending %, requested %, max %',
      v_key,
      v_existing_count,
      v_pending_count,
      v_quantity,
      v_cfg.max_total_quantity;
  end if;

  v_started_game_date := v_current_game_date;
  v_complete_game_date := v_current_game_date + v_cfg.delivery_game_days;

  insert into public.club_infrastructure_jobs (
    club_id,
    job_type,
    target_key,
    status,
    facility_target_level,
    asset_level,
    asset_quantity,
    cost_cash,
    finance_transaction_id,
    started_at,
    complete_at,
    completed_at,
    duration_game_days,
    started_game_date,
    complete_game_date,
    created_by_user_id,
    metadata
  )
  values (
    p_club_id,
    'asset_delivery',
    v_key,
    'pending',
    null,
    p_asset_level,
    v_quantity,
    v_cfg.cost_cash * v_quantity,
    null,
    now(),
    now() + make_interval(days => v_cfg.delivery_game_days),
    null,
    v_cfg.delivery_game_days,
    v_started_game_date,
    v_complete_game_date,
    v_uid,
    jsonb_build_object(
      'kind', 'asset_delivery',
      'asset_key', v_key,
      'asset_level', p_asset_level,
      'asset_name', v_cfg.asset_name,
      'quantity', v_quantity,
      'unit_cost_cash', v_cfg.cost_cash,
      'cost_cash', v_cfg.cost_cash * v_quantity,
      'delivery_game_days', v_cfg.delivery_game_days,
      'started_game_date', v_started_game_date,
      'complete_game_date', v_complete_game_date,
      'support_value', v_cfg.support_value,
      'max_total_quantity', v_cfg.max_total_quantity,
      'max_assigned_per_event', v_cfg.max_assigned_per_event,
      'timing_model', 'game_days'
    )
  )
  returning * into v_job;

  perform set_config('finance.internal', '1', true);

  v_finance_tx_id := public.finance_spend_from_club(
    p_club_id := p_club_id,
    p_amount := v_cfg.cost_cash * v_quantity,
    p_type := 'infrastructure_asset_delivery_start',
    p_sink_code := 'SINK',
    p_idempotency_key := 'asset_delivery:' || v_job.id::text,
    p_metadata := jsonb_build_object(
      'job_id', v_job.id,
      'job_type', 'asset_delivery',
      'target_key', v_key,
      'asset_key', v_key,
      'asset_level', p_asset_level,
      'asset_name', v_cfg.asset_name,
      'quantity', v_quantity,
      'unit_cost_cash', v_cfg.cost_cash,
      'cost_cash', v_cfg.cost_cash * v_quantity,
      'delivery_game_days', v_cfg.delivery_game_days,
      'started_game_date', v_started_game_date,
      'complete_game_date', v_complete_game_date,
      'timing_model', 'game_days'
    )
  );

  update public.club_infrastructure_jobs
  set finance_transaction_id = v_finance_tx_id
  where id = v_job.id
  returning * into v_job;

  return v_job;
end;$function$
;

CREATE OR REPLACE FUNCTION public.finance_resolve_paying_club_id(p_club_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_finance_club_id uuid;
begin
  select
    case
      when c.club_type = 'developing' and c.parent_club_id is not null
        then c.parent_club_id
      else c.id
    end
  into v_finance_club_id
  from public.clubs c
  where c.id = p_club_id;

  if v_finance_club_id is null then
    raise exception 'Club not found: %', p_club_id;
  end if;

  return v_finance_club_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_liquidate_club_for_insolvency_non_ai_core_v1(p_club_id uuid, p_reason text, p_ref_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_finance_club_id uuid;
  v_reason text;
begin
  v_finance_club_id := public.finance_resolve_paying_club_id(p_club_id);

  perform pg_advisory_xact_lock(
    hashtextextended('finance_liquidation:' || v_finance_club_id::text, 0)
  );

  v_reason := coalesce(nullif(p_reason, ''), 'insolvency');

  insert into finance.club_insolvency_state (
    club_id,
    emergency_rescue_count,
    status
  )
  values (
    v_finance_club_id,
    0,
    'active'
  )
  on conflict (club_id) do nothing;

  update finance.club_insolvency_state
  set
    status = 'liquidated',
    liquidated_at = coalesce(liquidated_at, now()),
    liquidation_reason = coalesce(
      liquidation_reason,
      v_reason || coalesce(':' || nullif(p_ref_id, ''), '')
    )
  where club_id = v_finance_club_id
    and status <> 'liquidated';

  update finance.emergency_loans
  set status = 'liquidated'
  where club_id = v_finance_club_id
    and status = 'active';

  update public.clubs
  set deleted_at = coalesce(deleted_at, now())
  where id = v_finance_club_id
     or parent_club_id = v_finance_club_id;

  return jsonb_build_object(
    'ok', false,
    'status', 'liquidated',
    'club_id', v_finance_club_id,
    'reason', v_reason,
    'ref_id', p_ref_id
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_issue_emergency_loan_non_ai_core_v1(p_club_id uuid, p_reason text, p_ref_id text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare
  v_finance_club_id uuid;
  v_game_date date;
  v_key text;

  v_existing_transaction_id uuid;
  v_existing_loan_id uuid;

  v_state finance.club_insolvency_state%rowtype;

  v_loan_amount bigint := 50000;
  v_weekly_principal bigint := 10000;
  v_weekly_interest bigint := 5000;

  v_rescue_number integer;

  v_club_account_id uuid;
  v_lender_account_id uuid;

  v_transaction_id uuid;
  v_loan_id uuid;
  v_notification_id public.notifications.id%type;

  v_first_due_game_date date;
  v_final_due_game_date date;
begin
  v_finance_club_id := public.finance_resolve_paying_club_id(p_club_id);
  v_game_date := public.get_current_game_date_date();

  if v_game_date is null then
    raise exception 'finance_issue_emergency_loan: could not resolve current game date';
  end if;

  v_key := coalesce(
    nullif(p_idempotency_key, ''),
    'emergency_loan:' ||
    v_finance_club_id::text || ':' ||
    coalesce(nullif(p_reason, ''), 'unknown') || ':' ||
    coalesce(nullif(p_ref_id, ''), 'none')
  );

  perform pg_advisory_xact_lock(
    hashtextextended('finance_emergency_loan:' || v_finance_club_id::text, 0)
  );

  select t.id
  into v_existing_transaction_id
  from finance.transactions t
  where t.idempotency_key = v_key
  limit 1;

  if v_existing_transaction_id is not null then
    select l.id
    into v_existing_loan_id
    from finance.emergency_loans l
    where l.idempotency_key = v_key
    limit 1;

    if v_existing_loan_id is not null then
      v_notification_id := public.finance_create_emergency_loan_notification(v_existing_loan_id);
    end if;

    return jsonb_build_object(
      'ok', true,
      'status', 'already_exists',
      'club_id', v_finance_club_id,
      'loan_id', v_existing_loan_id,
      'transaction_id', v_existing_transaction_id,
      'notification_id', v_notification_id
    );
  end if;

  insert into finance.club_insolvency_state (
    club_id,
    emergency_rescue_count,
    status
  )
  values (
    v_finance_club_id,
    0,
    'active'
  )
  on conflict (club_id) do nothing;

  select *
  into v_state
  from finance.club_insolvency_state
  where club_id = v_finance_club_id
  for update;

  if v_state.status = 'liquidated' then
    return jsonb_build_object(
      'ok', false,
      'status', 'already_liquidated',
      'club_id', v_finance_club_id
    );
  end if;

  if v_state.emergency_rescue_count >= 3 then
    return public.finance_liquidate_club_for_insolvency(
      v_finance_club_id,
      coalesce(nullif(p_reason, ''), 'emergency_rescue_limit_reached'),
      p_ref_id
    );
  end if;

  v_rescue_number := v_state.emergency_rescue_count + 1;

  v_first_due_game_date := public.finance_next_emergency_loan_due_date(v_game_date);

  v_final_due_game_date :=
    (v_first_due_game_date + interval '28 days')::date;

  v_club_account_id :=
    public.finance_get_or_create_club_account(v_finance_club_id, 'CASH', 'main');

  insert into finance.accounts (
    system_code,
    currency,
    kind
  )
  values (
    'LENDER_OF_LAST_RESORT',
    'CASH',
    'main'
  )
  on conflict (system_code, currency, kind)
  where system_code is not null
  do update set system_code = excluded.system_code
  returning id
  into v_lender_account_id;

  insert into finance.transactions (
    type,
    idempotency_key,
    metadata
  )
  values (
    'emergency_loan_disbursement',
    v_key,
    jsonb_build_object(
      'club_id', v_finance_club_id,
      'requested_club_id', p_club_id,
      'reason', p_reason,
      'ref_id', p_ref_id,
      'rescue_number', v_rescue_number,
      'principal_amount', v_loan_amount,
      'weekly_principal_due', v_weekly_principal,
      'weekly_interest_due', v_weekly_interest,
      'weekly_total_due', v_weekly_principal + v_weekly_interest,
      'issued_game_date', v_game_date,
      'first_due_game_date', v_first_due_game_date,
      'final_due_game_date', v_final_due_game_date,
      'source', 'automatic_emergency_insolvency_rescue',
      'display_timestamp', jsonb_build_object(
        'season', extract(year from v_game_date)::integer - 1999,
        'month', extract(month from v_game_date)::integer,
        'day', extract(day from v_game_date)::integer,
        'hour', 0,
        'minute', 0
      ),
      'game_date', v_game_date,
      'in_game_date', v_game_date
    )
  )
  returning id
  into v_transaction_id;

  insert into finance.entries (
    transaction_id,
    account_id,
    amount
  )
  values
    (
      v_transaction_id,
      v_lender_account_id,
      -v_loan_amount
    ),
    (
      v_transaction_id,
      v_club_account_id,
      v_loan_amount
    );

  insert into finance.emergency_loans (
    club_id,
    rescue_number,
    principal_amount,
    outstanding_principal,
    weekly_principal_due,
    weekly_interest_due,
    issued_game_date,
    first_due_game_date,
    final_due_game_date,
    status,
    idempotency_key,
    metadata
  )
  values (
    v_finance_club_id,
    v_rescue_number,
    v_loan_amount,
    v_loan_amount,
    v_weekly_principal,
    v_weekly_interest,
    v_game_date,
    v_first_due_game_date,
    v_final_due_game_date,
    'active',
    v_key,
    jsonb_build_object(
      'transaction_id', v_transaction_id,
      'reason', p_reason,
      'ref_id', p_ref_id
    )
  )
  returning id
  into v_loan_id;

  if v_rescue_number = 3 then
    perform public.finance_create_liquidation_final_warning(
      v_finance_club_id,
      v_loan_id
    );
  end if;

  update finance.club_insolvency_state
  set
    emergency_rescue_count = v_rescue_number,
    last_rescue_game_date = v_game_date
  where club_id = v_finance_club_id;

  v_notification_id := public.finance_create_emergency_loan_notification(v_loan_id);

  return jsonb_build_object(
    'ok', true,
    'status', 'issued',
    'club_id', v_finance_club_id,
    'loan_id', v_loan_id,
    'transaction_id', v_transaction_id,
    'notification_id', v_notification_id,
    'rescue_number', v_rescue_number,
    'amount', v_loan_amount,
    'issued_game_date', v_game_date,
    'first_due_game_date', v_first_due_game_date,
    'final_due_game_date', v_final_due_game_date
  );
end;$function$
;

CREATE OR REPLACE FUNCTION public.finance_ensure_mandatory_funds_non_ai_core_v1(p_club_id uuid, p_required_amount bigint, p_reason text, p_ref_id text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_finance_club_id uuid;
  v_balance numeric;
  v_balance_bigint bigint;
  v_result jsonb;
  v_attempt integer := 0;
  v_loans_issued integer := 0;
  v_base_key text;
begin
  if p_required_amount is null or p_required_amount <= 0 then
    return jsonb_build_object(
      'ok', true,
      'status', 'not_required',
      'required_amount', coalesce(p_required_amount, 0)
    );
  end if;

  v_finance_club_id := public.finance_resolve_paying_club_id(p_club_id);

  perform pg_advisory_xact_lock(
    hashtextextended('finance_ensure_mandatory_funds:' || v_finance_club_id::text, 0)
  );

  v_base_key := coalesce(
    nullif(p_idempotency_key, ''),
    'mandatory_funds:' ||
    v_finance_club_id::text || ':' ||
    coalesce(nullif(p_reason, ''), 'unknown') || ':' ||
    coalesce(nullif(p_ref_id, ''), 'none')
  );

  loop
    select coalesce(cfs.current_balance, 0)
    into v_balance
    from public.club_finance_summary cfs
    where cfs.club_id = v_finance_club_id
    for update;

    v_balance_bigint := floor(coalesce(v_balance, 0))::bigint;

    if v_balance_bigint >= p_required_amount then
      return jsonb_build_object(
        'ok', true,
        'status', case when v_loans_issued > 0 then 'rescued' else 'sufficient_funds' end,
        'club_id', v_finance_club_id,
        'required_amount', p_required_amount,
        'current_balance', v_balance_bigint,
        'loans_issued', v_loans_issued
      );
    end if;

    v_attempt := v_attempt + 1;

    if v_attempt > 3 then
      return public.finance_liquidate_club_for_insolvency(
        v_finance_club_id,
        coalesce(nullif(p_reason, ''), 'mandatory_payment_failed'),
        p_ref_id
      );
    end if;

    v_result := public.finance_issue_emergency_loan(
      v_finance_club_id,
      p_reason,
      p_ref_id,
      v_base_key || ':rescue:' || v_attempt::text
    );

    if coalesce((v_result ->> 'ok')::boolean, false) is not true then
      return v_result;
    end if;

    if v_result ->> 'status' = 'issued' then
      v_loans_issued := v_loans_issued + 1;
    end if;
  end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_limit_active_facility_infrastructure_jobs()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_active_count integer;
begin
  if new.job_type = 'facility_upgrade'
     and new.status = 'pending' then

    select count(*)::integer
    into v_active_count
    from public.club_infrastructure_jobs j
    where j.club_id = new.club_id
      and j.job_type = 'facility_upgrade'
      and j.status = 'pending'
      and j.id <> new.id;

    if v_active_count >= 2 then
      raise exception
        'Maximum active facility jobs reached. You can only have 2 facility construction jobs active at the same time.';
    end if;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.quote_infrastructure_job_cancellation(p_job_id uuid)
 RETURNS TABLE(job_id uuid, club_id uuid, job_type text, target_key text, status text, cost_cash bigint, duration_game_days integer, started_game_date date, current_game_date date, complete_game_date date, elapsed_game_days integer, free_refund_days integer, refund_percent numeric, refund_cash bigint, cancellation_cost_cash bigint, can_cancel boolean, reason text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$declare
  v_job public.club_infrastructure_jobs%rowtype;
  v_current_game_date date;
  v_elapsed_days integer;
  v_free_days integer := 2;
  v_refund_percent numeric := 0;
  v_refund_cash bigint := 0;
  v_can_cancel boolean := true;
  v_reason text := 'Cancellation quote available.';
begin
  select *
  into v_job
  from public.club_infrastructure_jobs
  where id = p_job_id
  limit 1;

  if not found then
    raise exception 'Infrastructure job not found: %', p_job_id;
  end if;

  if not exists (
    select 1
    from public.clubs c
    left join public.club_memberships cm
      on cm.club_id = c.id
     and cm.user_id = auth.uid()
    where c.id = v_job.club_id
      and (
        c.owner_user_id = auth.uid()
        or cm.user_id is not null
      )
  ) then
    raise exception 'Not allowed to view cancellation quote for this job';
  end if;

  v_current_game_date := public.get_current_game_date_date();

  if v_current_game_date is null then
    raise exception 'quote_infrastructure_job_cancellation: could not resolve current game date';
  end if;

  /*
    Asset deliveries:
    - Can be cancelled only while pending.
    - Always receive 100% refund before delivery completes.
    - Facility jobs continue to use the normal cancellation formula below.
  */
  if v_job.job_type = 'asset_delivery' then
    if v_job.status <> 'pending' then
      raise exception 'Only pending asset deliveries can be cancelled';
    end if;

    return query
    select
      v_job.id as job_id,
      v_job.club_id,
      v_job.job_type::text,
      v_job.target_key::text,
      v_job.status::text,
      v_job.cost_cash::bigint,
      v_job.duration_game_days::integer,
      v_job.started_game_date,
      v_current_game_date as current_game_date,
      v_job.complete_game_date,
      greatest(
        v_current_game_date - coalesce(v_job.started_game_date, v_current_game_date),
        0
      )::integer as elapsed_game_days,
      0::integer as free_refund_days,
      100.00::numeric as refund_percent,
      coalesce(v_job.cost_cash, 0)::bigint as refund_cash,
      0::bigint as cancellation_cost_cash,
      true as can_cancel,
      'Full refund: asset delivery can be cancelled at any time before delivery completes.'::text as reason;

    return;
  end if;

  v_elapsed_days := greatest(
    v_current_game_date - coalesce(v_job.started_game_date, v_current_game_date),
    0
  );

  if v_job.status <> 'pending' then
    v_can_cancel := false;
    v_reason := 'Only pending jobs can be cancelled.';
    v_refund_percent := 0;
  elsif v_job.complete_game_date is not null
        and v_current_game_date >= v_job.complete_game_date then
    v_can_cancel := false;
    v_reason := 'This job is already due for completion and can no longer be cancelled.';
    v_refund_percent := 0;
  elsif coalesce(v_job.duration_game_days, 0) <= 0 then
    v_can_cancel := false;
    v_reason := 'This job has no valid game-day duration.';
    v_refund_percent := 0;
  elsif v_elapsed_days <= v_free_days then
    v_can_cancel := true;
    v_reason := 'Full refund: cancelled inside the first 48 game hours.';
    v_refund_percent := 100;
  else
    v_can_cancel := true;
    v_reason := 'Partial refund based on remaining construction time.';
    v_refund_percent := greatest(
      least(
        (
          (v_job.duration_game_days - v_elapsed_days)::numeric
          / greatest((v_job.duration_game_days - v_free_days), 1)::numeric
        ) * 100,
        100
      ),
      0
    );
  end if;

  v_refund_cash := floor(coalesce(v_job.cost_cash, 0)::numeric * v_refund_percent / 100)::bigint;

  return query
  select
    v_job.id as job_id,
    v_job.club_id,
    v_job.job_type::text,
    v_job.target_key::text,
    v_job.status::text,
    v_job.cost_cash::bigint,
    v_job.duration_game_days::integer,
    v_job.started_game_date,
    v_current_game_date,
    v_job.complete_game_date,
    v_elapsed_days,
    v_free_days,
    round(v_refund_percent, 2),
    v_refund_cash,
    greatest(coalesce(v_job.cost_cash, 0) - v_refund_cash, 0)::bigint,
    v_can_cancel,
    v_reason;
end;$function$
;

CREATE OR REPLACE FUNCTION public.finance_credit_to_club(p_club_id uuid, p_amount bigint, p_type text DEFAULT 'income'::text, p_source_code text DEFAULT 'SINK'::text, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid;
  v_role text;
  v_internal boolean := coalesce(current_setting('finance.internal', true), '') = '1';

  v_club_acct uuid;
  v_source_acct uuid;
  v_tx uuid;

  v_game_ts timestamptz;
  v_game_metadata jsonb;
  v_metadata jsonb;
begin
  v_uid := auth.uid();
  v_role := current_setting('request.jwt.claim.role', true);

  if v_internal and v_uid is null then
    select c.owner_user_id
    into v_uid
    from public.clubs c
    where c.id = p_club_id
    limit 1;
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'Amount must be > 0';
  end if;

  if v_uid is not null and coalesce(v_role, '') <> 'service_role' and not v_internal then
    if not finance.can_spend_from_club(p_club_id, v_uid) then
      raise exception 'Not allowed to credit this club';
    end if;
  end if;

  v_game_ts := public.get_current_game_timestamp();

  v_game_metadata := jsonb_build_object(
    'game_date',
    jsonb_build_object(
      'season', public.season_from_game_timestamp(v_game_ts),
      'month', extract(month from v_game_ts at time zone 'UTC')::int,
      'day', extract(day from v_game_ts at time zone 'UTC')::int,
      'hour', extract(hour from v_game_ts at time zone 'UTC')::int,
      'minute', extract(minute from v_game_ts at time zone 'UTC')::int
    )
  );

  v_metadata := coalesce(p_metadata, '{}'::jsonb) || v_game_metadata;

  perform public.finance_get_or_create_club_account(p_club_id, 'CASH', 'main');

  select a.id
  into v_club_acct
  from finance.accounts a
  where a.club_id = p_club_id
    and a.currency = 'CASH'
    and a.kind = 'main';

  select a.id
  into v_source_acct
  from finance.accounts a
  where a.system_code = p_source_code
    and a.currency = 'CASH'
    and a.kind = 'main';

  if v_source_acct is null then
    raise exception 'Unknown source_code: %', p_source_code;
  end if;

  if p_idempotency_key is not null then
    insert into finance.transactions(type, created_by, idempotency_key, metadata)
    values (p_type, v_uid, p_idempotency_key, v_metadata)
    on conflict (created_by, idempotency_key) do nothing
    returning id into v_tx;

    if v_tx is null then
      select t.id
      into v_tx
      from finance.transactions t
      where t.created_by is not distinct from v_uid
        and t.idempotency_key = p_idempotency_key
      order by t.created_at desc
      limit 1;

      if v_tx is not null then
        return v_tx;
      end if;

      select t.id
      into v_tx
      from finance.transactions t
      where t.idempotency_key = p_idempotency_key
      order by t.created_at desc
      limit 1;

      if v_tx is not null then
        return v_tx;
      end if;
    end if;
  else
    insert into finance.transactions(type, created_by, metadata)
    values (p_type, v_uid, v_metadata)
    returning id into v_tx;
  end if;

  insert into finance.account_balances(account_id, balance)
  values (v_club_acct, 0)
  on conflict (account_id) do nothing;

  insert into finance.account_balances(account_id, balance)
  values (v_source_acct, 0)
  on conflict (account_id) do nothing;

  insert into finance.entries(transaction_id, account_id, amount, memo)
  values
    (v_tx, v_source_acct, -p_amount, 'income source debit'),
    (v_tx, v_club_acct,    p_amount, 'income club credit');

  return v_tx;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.cancel_infrastructure_job(p_job_id uuid)
 RETURNS TABLE(ok boolean, job_id uuid, club_id uuid, job_type text, target_key text, refund_percent numeric, refund_cash bigint, cancellation_cost_cash bigint, finance_transaction_id uuid, status text, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$declare
  v_uid uuid;
  v_job public.club_infrastructure_jobs%rowtype;

  v_quote jsonb;
  v_can_cancel boolean := false;

  v_refund_percent numeric := 0;
  v_refund_cash bigint := 0;
  v_cancellation_cost_cash bigint := 0;

  v_refund_tx_id uuid;
  v_message text;
  v_cancelled_at timestamptz := now();
begin
  v_uid := auth.uid();

  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  -- 1) Load and lock job
  select *
  into v_job
  from public.club_infrastructure_jobs
  where id = p_job_id
  for update;

  if not found then
    raise exception 'Infrastructure job not found: %', p_job_id;
  end if;

  -- 2) Validate club access
  if not exists (
    select 1
    from public.clubs c
    left join public.club_memberships cm
      on cm.club_id = c.id
     and cm.user_id = v_uid
    where c.id = v_job.club_id
      and (
        c.owner_user_id = v_uid
        or cm.user_id is not null
      )
  ) then
    raise exception 'Not allowed to cancel this infrastructure job';
  end if;

  -- 3) Only pending jobs can be cancelled
  if v_job.status <> 'pending' then
    raise exception 'Only pending infrastructure jobs can be cancelled';
  end if;

  -- 4) Quote is now the single source of truth for cancellation/refund logic.
  --    This is important for asset deliveries: full refund must come from quote RPC.
  select to_jsonb(q)
  into v_quote
  from public.quote_infrastructure_job_cancellation(v_job.id) q
  limit 1;

  if v_quote is null then
    raise exception 'Could not quote cancellation for infrastructure job: %', v_job.id;
  end if;

  if not (v_quote ? 'can_cancel') then
    raise exception 'Cancellation quote did not return can_cancel';
  end if;

  v_can_cancel := coalesce((v_quote ->> 'can_cancel')::boolean, false);
  v_message := coalesce(
    nullif(v_quote ->> 'reason', ''),
    nullif(v_quote ->> 'message', ''),
    'Cancellation quote available.'
  );

  if v_can_cancel = false then
    raise exception '%', v_message;
  end if;

  if not (v_quote ? 'refund_percent') then
    raise exception 'Cancellation quote did not return refund_percent';
  end if;

  if not (v_quote ? 'refund_cash') then
    raise exception 'Cancellation quote did not return refund_cash';
  end if;

  if not (v_quote ? 'cancellation_cost_cash') then
    raise exception 'Cancellation quote did not return cancellation_cost_cash';
  end if;

  v_refund_percent := coalesce((v_quote ->> 'refund_percent')::numeric, 0);
  v_refund_cash := coalesce((v_quote ->> 'refund_cash')::bigint, 0);
  v_cancellation_cost_cash := coalesce((v_quote ->> 'cancellation_cost_cash')::bigint, 0);

  if v_refund_cash < 0 then
    raise exception 'Cancellation quote returned invalid negative refund_cash: %', v_refund_cash;
  end if;

  if v_cancellation_cost_cash < 0 then
    raise exception 'Cancellation quote returned invalid negative cancellation_cost_cash: %', v_cancellation_cost_cash;
  end if;

  -- 5) Refund club using the exact amount from quote RPC
  if v_refund_cash > 0 then
    perform set_config('finance.internal', '1', true);

    v_refund_tx_id := public.finance_credit_to_club(
      p_club_id := v_job.club_id,
      p_amount := v_refund_cash,
      p_type := 'infrastructure_job_refund',
      p_source_code := 'SINK',
      p_idempotency_key := 'infra_job_cancel:' || v_job.id::text,
      p_metadata := jsonb_build_object(
        'job_id', v_job.id,
        'original_finance_transaction_id', v_job.finance_transaction_id,
        'job_type', v_job.job_type,
        'target_key', v_job.target_key,
        'facility_target_level', v_job.facility_target_level,
        'asset_level', v_job.asset_level,
        'asset_quantity', v_job.asset_quantity,
        'cost_cash', v_job.cost_cash,
        'refund_percent', round(v_refund_percent, 2),
        'refund_cash', v_refund_cash,
        'cancellation_cost_cash', v_cancellation_cost_cash,
        'duration_game_days', v_job.duration_game_days,
        'started_game_date', v_job.started_game_date,
        'complete_game_date', v_job.complete_game_date,
        'quote', v_quote,
        'reason', 'infrastructure_job_cancelled'
      )
    );
  end if;

  -- 6) Mark job as cancelled
  update public.club_infrastructure_jobs
  set
    status = 'cancelled',
    cancelled_at = v_cancelled_at,
    cancelled_by_user_id = v_uid,
    cancellation_finance_transaction_id = v_refund_tx_id,
    refund_cash = v_refund_cash,
    cancellation_cost_cash = v_cancellation_cost_cash,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'cancellation',
      jsonb_build_object(
        'cancelled_at', v_cancelled_at,
        'cancelled_by_user_id', v_uid,
        'refund_percent', round(v_refund_percent, 2),
        'refund_cash', v_refund_cash,
        'cancellation_cost_cash', v_cancellation_cost_cash,
        'refund_finance_transaction_id', v_refund_tx_id,
        'quote', v_quote
      )
    )
  where id = v_job.id;

  -- 7) Return same shape as before
  return query
  select
    true,
    v_job.id,
    v_job.club_id,
    v_job.job_type::text,
    v_job.target_key::text,
    round(v_refund_percent, 2),
    v_refund_cash,
    v_cancellation_cost_cash,
    v_refund_tx_id,
    'cancelled'::text,
    v_message;
end;$function$
;

CREATE OR REPLACE FUNCTION public.finance_create_emergency_loan_notification(p_loan_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_loan finance.emergency_loans%rowtype;
  v_club public.clubs%rowtype;
  v_state finance.club_insolvency_state%rowtype;

  v_type_id public.notification_types.id%type;
  v_notification_id public.notifications.id%type;
  v_existing_notification_id public.notifications.id%type;

  v_owner_user_id uuid;

  v_reason text;
  v_reason_label text;

  v_weeks integer;
  v_weekly_total bigint;
  v_total_interest bigint;
  v_total_repayment bigint;

  v_title text;
  v_message text;
begin
  select *
  into v_loan
  from finance.emergency_loans
  where id = p_loan_id;

  if v_loan.id is null then
    raise exception 'Emergency loan not found: %', p_loan_id;
  end if;

  select *
  into v_club
  from public.clubs
  where id = v_loan.club_id;

  if v_club.id is null then
    raise exception 'Club not found for emergency loan: %', v_loan.club_id;
  end if;

  v_owner_user_id := v_club.owner_user_id;

  if v_owner_user_id is null then
    return null;
  end if;

  select *
  into v_state
  from finance.club_insolvency_state
  where club_id = v_loan.club_id;

  select id
  into v_type_id
  from public.notification_types
  where code = 'FINANCE_EMERGENCY_LOAN_GRANTED'
    and is_active = true
  limit 1;

  if v_type_id is null then
    raise exception 'Notification type FINANCE_EMERGENCY_LOAN_GRANTED is missing or inactive';
  end if;

  select n.id
  into v_existing_notification_id
  from public.notifications n
  join public.notification_types nt
    on nt.id = n.type_id
  where nt.code = 'FINANCE_EMERGENCY_LOAN_GRANTED'
    and n.payload_json ->> 'loan_id' = p_loan_id::text
  limit 1;

  if v_existing_notification_id is not null then
    insert into public.user_notifications (
      user_id,
      notification_id,
      status,
      read_at,
      deleted_at,
      created_at
    )
    select
      v_owner_user_id,
      v_existing_notification_id,
      'unread',
      null,
      null,
      now()
    where not exists (
      select 1
      from public.user_notifications un
      where un.user_id = v_owner_user_id
        and un.notification_id = v_existing_notification_id
    );

    return v_existing_notification_id;
  end if;

  v_reason := coalesce(v_loan.metadata ->> 'reason', 'mandatory_payment_failed');

  v_reason_label :=
    case v_reason
      when 'rider_salary_payday' then 'rider salary payday'
      when 'staff_salary_payday' then 'staff salary payday'
      when 'tax_monthly_adjustment' then 'monthly tax adjustment'
      when 'emergency_loan_repayment' then 'emergency loan repayment'
      when 'manual_test_required_payroll' then 'manual payroll funding test'
      else replace(v_reason, '_', ' ')
    end;

  v_weeks := ceil(v_loan.principal_amount::numeric / v_loan.weekly_principal_due::numeric)::integer;
  v_weekly_total := v_loan.weekly_principal_due + v_loan.weekly_interest_due;
  v_total_interest := v_weeks * v_loan.weekly_interest_due;
  v_total_repayment := v_loan.principal_amount + v_total_interest;

  v_title := 'Emergency loan granted: $' || v_loan.principal_amount::text;

  v_message :=
    'Your club received an emergency loan of $' || v_loan.principal_amount::text ||
    ' because it could not cover ' || v_reason_label || '. ' ||
    'Repayment is $' || v_weekly_total::text || ' per week: $' ||
    v_loan.weekly_principal_due::text || ' principal plus $' ||
    v_loan.weekly_interest_due::text || ' emergency interest. ' ||
    'Total repayment is $' || v_total_repayment::text ||
    ' by ' || v_loan.final_due_game_date::text || '. ' ||
    'Emergency rescue ' || coalesce(v_state.emergency_rescue_count, v_loan.rescue_number)::text ||
    ' of 3 has now been used. If the club cannot pay another mandatory obligation after all 3 rescues are used, the club will be liquidated. Optional purchases and upgrades will not trigger emergency loans.';

  insert into public.notifications (
    type_id,
    title,
    message,
    source,
    created_by_user_id,
    action_url,
    payload_json,
    expires_at,
    created_at
  )
  values (
    v_type_id,
    v_title,
    v_message,
    'game',
    null,
    '/dashboard/finance?tab=transactions',
    jsonb_build_object(
      'club_id', v_loan.club_id,
      'club_name', v_club.name,
      'loan_id', v_loan.id,
      'loan_transaction_id', v_loan.metadata ->> 'transaction_id',
      'reason', v_reason,
      'reason_label', v_reason_label,
      'rescue_number', v_loan.rescue_number,
      'rescues_used_lifetime', coalesce(v_state.emergency_rescue_count, v_loan.rescue_number),
      'max_lifetime_rescues', 3,
      'principal_amount', v_loan.principal_amount,
      'outstanding_principal', v_loan.outstanding_principal,
      'weekly_principal_due', v_loan.weekly_principal_due,
      'weekly_interest_due', v_loan.weekly_interest_due,
      'weekly_total_due', v_weekly_total,
      'repayment_weeks', v_weeks,
      'total_interest', v_total_interest,
      'total_repayment', v_total_repayment,
      'issued_game_date', v_loan.issued_game_date,
      'first_due_game_date', v_loan.first_due_game_date,
      'final_due_game_date', v_loan.final_due_game_date,
      'liquidation_rule', 'After 3 lifetime emergency rescues, the next unpaid mandatory obligation liquidates the club.',
      'optional_spending_rule', 'Optional purchases, upgrades, transfers, staff courses, scouting, and camps do not trigger emergency loans; they are blocked if funds are insufficient.'
    ),
    null,
    now()
  )
  returning id
  into v_notification_id;

  insert into public.user_notifications (
    user_id,
    notification_id,
    status,
    read_at,
    deleted_at,
    created_at
  )
  values (
    v_owner_user_id,
    v_notification_id,
    'unread',
    null,
    null,
    now()
  );

  return v_notification_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.quote_infrastructure_job_cancellation_admin(p_job_id uuid)
 RETURNS TABLE(job_id uuid, club_id uuid, job_type text, target_key text, status text, cost_cash bigint, duration_game_days integer, started_game_date date, current_game_date date, complete_game_date date, elapsed_game_days integer, free_refund_days integer, refund_percent numeric, refund_cash bigint, cancellation_cost_cash bigint, can_cancel boolean, reason text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_job public.club_infrastructure_jobs%rowtype;
  v_current_game_date date;
  v_elapsed_days integer;
  v_free_days integer := 2;
  v_refund_percent numeric := 0;
  v_refund_cash bigint := 0;
  v_can_cancel boolean := true;
  v_reason text := 'Cancellation quote available.';
begin
  select *
  into v_job
  from public.club_infrastructure_jobs
  where id = p_job_id
  limit 1;

  if not found then
    raise exception 'Infrastructure job not found: %', p_job_id;
  end if;

  v_current_game_date := public.get_current_game_date_date();

  if v_current_game_date is null then
    raise exception 'quote_infrastructure_job_cancellation_admin: could not resolve current game date';
  end if;

  v_elapsed_days := greatest(
    v_current_game_date - coalesce(v_job.started_game_date, v_current_game_date),
    0
  );

  if v_job.status <> 'pending' then
    v_can_cancel := false;
    v_reason := 'Only pending jobs can be cancelled.';
    v_refund_percent := 0;
  elsif v_job.complete_game_date is not null
        and v_current_game_date >= v_job.complete_game_date then
    v_can_cancel := false;
    v_reason := 'This job is already due for completion and can no longer be cancelled.';
    v_refund_percent := 0;
  elsif coalesce(v_job.duration_game_days, 0) <= 0 then
    v_can_cancel := false;
    v_reason := 'This job has no valid game-day duration.';
    v_refund_percent := 0;
  elsif v_elapsed_days <= v_free_days then
    v_can_cancel := true;
    v_reason := 'Full refund: cancelled inside the first 48 game hours.';
    v_refund_percent := 100;
  else
    v_can_cancel := true;
    v_reason := 'Partial refund based on remaining construction time.';
    v_refund_percent := greatest(
      least(
        (
          (v_job.duration_game_days - v_elapsed_days)::numeric
          / greatest((v_job.duration_game_days - v_free_days), 1)::numeric
        ) * 100,
        100
      ),
      0
    );
  end if;

  v_refund_cash := floor(coalesce(v_job.cost_cash, 0)::numeric * v_refund_percent / 100)::bigint;

  return query
  select
    v_job.id,
    v_job.club_id,
    v_job.job_type::text,
    v_job.target_key::text,
    v_job.status::text,
    v_job.cost_cash::bigint,
    v_job.duration_game_days::integer,
    v_job.started_game_date,
    v_current_game_date,
    v_job.complete_game_date,
    v_elapsed_days,
    v_free_days,
    round(v_refund_percent, 2),
    v_refund_cash,
    greatest(coalesce(v_job.cost_cash, 0) - v_refund_cash, 0)::bigint,
    v_can_cancel,
    v_reason;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_create_emergency_loan_repaid_notification(p_loan_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_loan finance.emergency_loans%rowtype;
  v_club public.clubs%rowtype;
  v_state finance.club_insolvency_state%rowtype;

  v_type_id public.notification_types.id%type;
  v_notification_id public.notifications.id%type;
  v_existing_notification_id public.notifications.id%type;

  v_owner_user_id uuid;

  v_weeks integer;
  v_total_interest bigint;
  v_total_repayment bigint;

  v_title text;
  v_message text;
begin
  select *
  into v_loan
  from finance.emergency_loans
  where id = p_loan_id;

  if v_loan.id is null then
    raise exception 'Emergency loan not found: %', p_loan_id;
  end if;

  select *
  into v_club
  from public.clubs
  where id = v_loan.club_id;

  if v_club.id is null then
    raise exception 'Club not found for emergency loan: %', v_loan.club_id;
  end if;

  v_owner_user_id := v_club.owner_user_id;

  if v_owner_user_id is null then
    return null;
  end if;

  select *
  into v_state
  from finance.club_insolvency_state
  where club_id = v_loan.club_id;

  select id
  into v_type_id
  from public.notification_types
  where code = 'FINANCE_EMERGENCY_LOAN_REPAID'
    and is_active = true
  limit 1;

  if v_type_id is null then
    raise exception 'Notification type FINANCE_EMERGENCY_LOAN_REPAID is missing or inactive';
  end if;

  select n.id
  into v_existing_notification_id
  from public.notifications n
  join public.notification_types nt
    on nt.id = n.type_id
  where nt.code = 'FINANCE_EMERGENCY_LOAN_REPAID'
    and n.payload_json ->> 'loan_id' = p_loan_id::text
  limit 1;

  if v_existing_notification_id is not null then
    insert into public.user_notifications (
      user_id,
      notification_id,
      status,
      read_at,
      deleted_at,
      created_at
    )
    select
      v_owner_user_id,
      v_existing_notification_id,
      'unread',
      null,
      null,
      now()
    where not exists (
      select 1
      from public.user_notifications un
      where un.user_id = v_owner_user_id
        and un.notification_id = v_existing_notification_id
    );

    return v_existing_notification_id;
  end if;

  v_weeks := ceil(v_loan.principal_amount::numeric / v_loan.weekly_principal_due::numeric)::integer;
  v_total_interest := v_weeks * v_loan.weekly_interest_due;
  v_total_repayment := v_loan.principal_amount + v_total_interest;

  v_title := 'Emergency loan fully repaid';

  v_message :=
    'Your emergency loan has been fully repaid. Total repayment was $' ||
    v_total_repayment::text || ': $' ||
    v_loan.principal_amount::text || ' principal plus $' ||
    v_total_interest::text || ' emergency interest. ' ||
    'Important: the emergency rescue counter does not reset. This club has used ' ||
    coalesce(v_state.emergency_rescue_count, v_loan.rescue_number)::text ||
    ' of 3 lifetime rescues. If all 3 rescues are used and the club cannot pay another mandatory obligation, the club will be liquidated.';

  insert into public.notifications (
    type_id,
    title,
    message,
    source,
    created_by_user_id,
    action_url,
    payload_json,
    expires_at,
    created_at
  )
  values (
    v_type_id,
    v_title,
    v_message,
    'game',
    null,
    '/dashboard/finance?tab=transactions',
    jsonb_build_object(
      'club_id', v_loan.club_id,
      'club_name', v_club.name,
      'loan_id', v_loan.id,
      'rescue_number', v_loan.rescue_number,
      'rescues_used_lifetime', coalesce(v_state.emergency_rescue_count, v_loan.rescue_number),
      'max_lifetime_rescues', 3,
      'principal_amount', v_loan.principal_amount,
      'total_interest', v_total_interest,
      'total_repayment', v_total_repayment,
      'issued_game_date', v_loan.issued_game_date,
      'final_due_game_date', v_loan.final_due_game_date,
      'counter_rule', 'Emergency rescue counter is lifetime-based and does not reset after repayment.',
      'liquidation_rule', 'After 3 lifetime emergency rescues, the next unpaid mandatory obligation liquidates the club.'
    ),
    null,
    now()
  )
  returning id
  into v_notification_id;

  insert into public.user_notifications (
    user_id,
    notification_id,
    status,
    read_at,
    deleted_at,
    created_at
  )
  values (
    v_owner_user_id,
    v_notification_id,
    'unread',
    null,
    null,
    now()
  );

  return v_notification_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_charge_emergency_loan_weekly_payment(p_loan_id uuid, p_due_game_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_loan finance.emergency_loans%rowtype;
  v_current_game_date date;
  v_due_game_date date;
  v_week_key text;

  v_existing_run finance.emergency_loan_repayment_runs%rowtype;

  v_principal_due bigint;
  v_interest_due bigint;
  v_total_due bigint;
  v_new_outstanding bigint;

  v_funds_result jsonb;

  v_club_account_id uuid;
  v_lender_account_id uuid;

  v_principal_key text;
  v_interest_key text;

  v_principal_transaction_id uuid;
  v_interest_transaction_id uuid;
  v_run_id uuid;
  v_notification_id public.notifications.id%type;

  v_display_timestamp jsonb;
begin
  v_current_game_date := public.get_current_game_date_date();

  if v_current_game_date is null then
    raise exception 'finance_charge_emergency_loan_weekly_payment: could not resolve current game date';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('finance_emergency_loan_repayment:' || p_loan_id::text, 0)
  );

  select *
  into v_loan
  from finance.emergency_loans
  where id = p_loan_id
  for update;

  if v_loan.id is null then
    return jsonb_build_object(
      'ok', false,
      'status', 'loan_not_found',
      'loan_id', p_loan_id
    );
  end if;

  if v_loan.status <> 'active' then
    return jsonb_build_object(
      'ok', true,
      'status', 'loan_not_active',
      'loan_id', v_loan.id,
      'loan_status', v_loan.status
    );
  end if;

  if coalesce(v_loan.outstanding_principal, 0) <= 0 then
    update finance.emergency_loans
    set status = 'repaid'
    where id = v_loan.id
      and status = 'active';

    v_notification_id := public.finance_create_emergency_loan_repaid_notification(v_loan.id);

    return jsonb_build_object(
      'ok', true,
      'status', 'repaid',
      'loan_id', v_loan.id,
      'notification_id', v_notification_id
    );
  end if;

  if p_due_game_date is not null then
    v_due_game_date := p_due_game_date;

    if v_due_game_date < v_loan.first_due_game_date
       or v_due_game_date > v_loan.final_due_game_date
       or ((v_due_game_date - v_loan.first_due_game_date) % 7) <> 0 then
      return jsonb_build_object(
        'ok', false,
        'status', 'invalid_due_game_date',
        'loan_id', v_loan.id,
        'due_game_date', v_due_game_date,
        'first_due_game_date', v_loan.first_due_game_date,
        'final_due_game_date', v_loan.final_due_game_date
      );
    end if;

    if v_current_game_date < v_due_game_date then
      return jsonb_build_object(
        'ok', true,
        'status', 'not_due',
        'loan_id', v_loan.id,
        'current_game_date', v_current_game_date,
        'due_game_date', v_due_game_date
      );
    end if;
  else
    if v_current_game_date < v_loan.first_due_game_date then
      return jsonb_build_object(
        'ok', true,
        'status', 'not_due',
        'loan_id', v_loan.id,
        'current_game_date', v_current_game_date,
        'first_due_game_date', v_loan.first_due_game_date
      );
    end if;

    select gs.due_date::date
    into v_due_game_date
    from generate_series(
      v_loan.first_due_game_date,
      least(v_current_game_date, v_loan.final_due_game_date),
      interval '7 days'
    ) as gs(due_date)
    where not exists (
      select 1
      from finance.emergency_loan_repayment_runs r
      where r.loan_id = v_loan.id
        and r.week_key = to_char(gs.due_date::date, 'IYYY-IW')
        and r.status in ('charged', 'already_exists')
    )
    order by gs.due_date::date
    limit 1;

    if v_due_game_date is null then
      return jsonb_build_object(
        'ok', true,
        'status', 'no_due_payment',
        'loan_id', v_loan.id,
        'current_game_date', v_current_game_date
      );
    end if;
  end if;

  v_week_key := to_char(v_due_game_date, 'IYYY-IW');

  select *
  into v_existing_run
  from finance.emergency_loan_repayment_runs
  where loan_id = v_loan.id
    and week_key = v_week_key
  limit 1;

  if v_existing_run.id is not null then
    return jsonb_build_object(
      'ok', true,
      'status', 'already_processed',
      'loan_id', v_loan.id,
      'week_key', v_week_key,
      'run_id', v_existing_run.id,
      'principal_transaction_id', v_existing_run.principal_transaction_id,
      'interest_transaction_id', v_existing_run.interest_transaction_id
    );
  end if;

  v_principal_due := least(v_loan.outstanding_principal, v_loan.weekly_principal_due);
  v_interest_due := case
    when v_principal_due > 0 then v_loan.weekly_interest_due
    else 0
  end;

  v_total_due := v_principal_due + v_interest_due;

  if v_total_due <= 0 then
    update finance.emergency_loans
    set status = 'repaid'
    where id = v_loan.id
      and status = 'active';

    v_notification_id := public.finance_create_emergency_loan_repaid_notification(v_loan.id);

    return jsonb_build_object(
      'ok', true,
      'status', 'repaid',
      'loan_id', v_loan.id,
      'notification_id', v_notification_id
    );
  end if;

  v_funds_result := public.finance_ensure_mandatory_funds(
    v_loan.club_id,
    v_total_due,
    'emergency_loan_repayment',
    v_loan.id::text || ':' || v_due_game_date::text,
    'mandatory_funds:emergency_loan_repayment:' ||
      v_loan.club_id::text || ':' ||
      v_loan.id::text || ':' ||
      v_week_key
  );

  if coalesce((v_funds_result ->> 'ok')::boolean, false) is not true then
    insert into finance.emergency_loan_repayment_runs (
      loan_id,
      club_id,
      week_key,
      due_game_date,
      principal_due,
      interest_due,
      principal_transaction_id,
      interest_transaction_id,
      status,
      metadata
    )
    values (
      v_loan.id,
      v_loan.club_id,
      v_week_key,
      v_due_game_date,
      v_principal_due,
      v_interest_due,
      null,
      null,
      case
        when v_funds_result ->> 'status' = 'liquidated' then 'club_liquidated'
        else 'skipped'
      end,
      jsonb_build_object(
        'funds_result', v_funds_result
      )
    )
    on conflict (loan_id, week_key) do nothing;

    return jsonb_build_object(
      'ok', false,
      'status', coalesce(v_funds_result ->> 'status', 'funding_failed'),
      'loan_id', v_loan.id,
      'club_id', v_loan.club_id,
      'week_key', v_week_key,
      'due_game_date', v_due_game_date,
      'principal_due', v_principal_due,
      'interest_due', v_interest_due,
      'total_due', v_total_due,
      'funds_result', v_funds_result
    );
  end if;

  v_club_account_id :=
    public.finance_get_or_create_club_account(v_loan.club_id, 'CASH', 'main');

  insert into finance.accounts (
    system_code,
    currency,
    kind
  )
  values (
    'LENDER_OF_LAST_RESORT',
    'CASH',
    'main'
  )
  on conflict (system_code, currency, kind)
  where system_code is not null
  do update set system_code = excluded.system_code
  returning id
  into v_lender_account_id;

  v_display_timestamp := jsonb_build_object(
    'season', extract(year from v_due_game_date)::integer - 1999,
    'month', extract(month from v_due_game_date)::integer,
    'day', extract(day from v_due_game_date)::integer,
    'hour', 0,
    'minute', 0
  );

  v_principal_key :=
    'emergency_loan_principal_repayment:' ||
    v_loan.id::text || ':' ||
    v_week_key;

  select t.id
  into v_principal_transaction_id
  from finance.transactions t
  where t.idempotency_key = v_principal_key
  limit 1;

  if v_principal_transaction_id is null then
    insert into finance.transactions (
      type,
      idempotency_key,
      metadata
    )
    values (
      'emergency_loan_principal_repayment',
      v_principal_key,
      jsonb_build_object(
        'club_id', v_loan.club_id,
        'loan_id', v_loan.id,
        'rescue_number', v_loan.rescue_number,
        'due_game_date', v_due_game_date,
        'week_key', v_week_key,
        'principal_due', v_principal_due,
        'outstanding_before', v_loan.outstanding_principal,
        'outstanding_after', greatest(v_loan.outstanding_principal - v_principal_due, 0),
        'game_date', v_due_game_date,
        'in_game_date', v_due_game_date,
        'display_timestamp', v_display_timestamp,
        'source', 'weekly_emergency_loan_repayment'
      )
    )
    returning id
    into v_principal_transaction_id;

    insert into finance.entries (
      transaction_id,
      account_id,
      amount
    )
    values
      (
        v_principal_transaction_id,
        v_club_account_id,
        -v_principal_due
      ),
      (
        v_principal_transaction_id,
        v_lender_account_id,
        v_principal_due
      );
  end if;

  if v_interest_due > 0 then
    v_interest_key :=
      'emergency_loan_interest:' ||
      v_loan.id::text || ':' ||
      v_week_key;

    select t.id
    into v_interest_transaction_id
    from finance.transactions t
    where t.idempotency_key = v_interest_key
    limit 1;

    if v_interest_transaction_id is null then
      insert into finance.transactions (
        type,
        idempotency_key,
        metadata
      )
      values (
        'emergency_loan_interest',
        v_interest_key,
        jsonb_build_object(
          'club_id', v_loan.club_id,
          'loan_id', v_loan.id,
          'rescue_number', v_loan.rescue_number,
          'due_game_date', v_due_game_date,
          'week_key', v_week_key,
          'interest_due', v_interest_due,
          'weekly_principal_due', v_principal_due,
          'weekly_total_due', v_total_due,
          'game_date', v_due_game_date,
          'in_game_date', v_due_game_date,
          'display_timestamp', v_display_timestamp,
          'source', 'weekly_emergency_loan_interest'
        )
      )
      returning id
      into v_interest_transaction_id;

      insert into finance.entries (
        transaction_id,
        account_id,
        amount
      )
      values
        (
          v_interest_transaction_id,
          v_club_account_id,
          -v_interest_due
        ),
        (
          v_interest_transaction_id,
          v_lender_account_id,
          v_interest_due
        );
    end if;
  end if;

  v_new_outstanding := greatest(v_loan.outstanding_principal - v_principal_due, 0);

  update finance.emergency_loans
  set
    outstanding_principal = v_new_outstanding,
    status = case
      when v_new_outstanding <= 0 then 'repaid'
      else status
    end
  where id = v_loan.id;

  insert into finance.emergency_loan_repayment_runs (
    loan_id,
    club_id,
    week_key,
    due_game_date,
    principal_due,
    interest_due,
    principal_transaction_id,
    interest_transaction_id,
    status,
    metadata
  )
  values (
    v_loan.id,
    v_loan.club_id,
    v_week_key,
    v_due_game_date,
    v_principal_due,
    v_interest_due,
    v_principal_transaction_id,
    v_interest_transaction_id,
    'charged',
    jsonb_build_object(
      'funds_result', v_funds_result,
      'outstanding_before', v_loan.outstanding_principal,
      'outstanding_after', v_new_outstanding
    )
  )
  returning id
  into v_run_id;

  if v_new_outstanding <= 0 then
    v_notification_id := public.finance_create_emergency_loan_repaid_notification(v_loan.id);
  end if;

  return jsonb_build_object(
    'ok', true,
    'status', case when v_new_outstanding <= 0 then 'repaid' else 'charged' end,
    'loan_id', v_loan.id,
    'club_id', v_loan.club_id,
    'run_id', v_run_id,
    'week_key', v_week_key,
    'due_game_date', v_due_game_date,
    'principal_due', v_principal_due,
    'interest_due', v_interest_due,
    'total_due', v_total_due,
    'outstanding_before', v_loan.outstanding_principal,
    'outstanding_after', v_new_outstanding,
    'principal_transaction_id', v_principal_transaction_id,
    'interest_transaction_id', v_interest_transaction_id,
    'notification_id', v_notification_id
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_process_weekly_emergency_loan_repayments()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_current_game_date date;

  v_loan record;
  v_result jsonb;
  v_status text;

  v_loans_processed integer := 0;
  v_payments_charged integer := 0;
  v_loans_repaid integer := 0;
  v_loans_not_due integer := 0;
  v_loans_liquidated integer := 0;
  v_already_processed integer := 0;
  v_failed integer := 0;

  v_errors jsonb := '[]'::jsonb;
begin
  v_current_game_date := public.get_current_game_date_date();

  if v_current_game_date is null then
    raise exception 'finance_process_weekly_emergency_loan_repayments: could not resolve current game date';
  end if;

  /*
    One emergency-loan repayment per club per week.
    Oldest active due loan first.

    This prevents stacked repayment spirals where two active loans charge
    $30,000 in the same week.
  */
  for v_loan in
    with due_loans as (
      select
        l.*,
        row_number() over (
          partition by l.club_id
          order by l.first_due_game_date asc, l.created_at asc
        ) as club_due_rank
      from finance.emergency_loans l
      where l.status = 'active'
        and l.outstanding_principal > 0
        and l.first_due_game_date <= v_current_game_date
    )
    select
      dl.id,
      dl.club_id
    from due_loans dl
    where dl.club_due_rank = 1
    order by dl.first_due_game_date asc, dl.created_at asc
  loop
    v_loans_processed := v_loans_processed + 1;

    begin
      v_result := public.finance_charge_emergency_loan_weekly_payment(
        v_loan.id,
        null
      );

      v_status := coalesce(v_result ->> 'status', 'unknown');

      if v_status = 'charged' then
        v_payments_charged := v_payments_charged + 1;

      elsif v_status = 'repaid' then
        v_payments_charged := v_payments_charged + 1;
        v_loans_repaid := v_loans_repaid + 1;

      elsif v_status in ('not_due', 'no_due_payment', 'loan_not_active') then
        v_loans_not_due := v_loans_not_due + 1;

      elsif v_status = 'already_processed' then
        v_already_processed := v_already_processed + 1;

      elsif v_status in ('liquidated', 'already_liquidated') then
        v_loans_liquidated := v_loans_liquidated + 1;

      else
        v_failed := v_failed + 1;
        v_errors := v_errors || jsonb_build_array(
          jsonb_build_object(
            'loan_id', v_loan.id,
            'club_id', v_loan.club_id,
            'status', v_status,
            'result', v_result
          )
        );
      end if;

    exception when others then
      v_failed := v_failed + 1;
      v_errors := v_errors || jsonb_build_array(
        jsonb_build_object(
          'loan_id', v_loan.id,
          'club_id', v_loan.club_id,
          'error', sqlerrm
        )
      );
    end;
  end loop;

  /*
    Count active loans that exist but are not due yet.
    This is only reporting, not processing.
  */
  select count(*)
  into v_loans_not_due
  from finance.emergency_loans l
  where l.status = 'active'
    and l.outstanding_principal > 0
    and l.first_due_game_date > v_current_game_date;

  return jsonb_build_object(
    'ok', v_failed = 0,
    'current_game_date', v_current_game_date,
    'mode', 'one_repayment_per_club_per_week_oldest_first',
    'loans_processed', v_loans_processed,
    'payments_charged', v_payments_charged,
    'loans_repaid', v_loans_repaid,
    'loans_not_due', v_loans_not_due,
    'loans_liquidated', v_loans_liquidated,
    'already_processed', v_already_processed,
    'failed', v_failed,
    'errors', v_errors
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.start_club_asset_delivery_api(p_club_id uuid, p_asset_key text, p_asset_level integer DEFAULT 1, p_quantity integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_finance_club_id uuid;
  v_asset_key text;
  v_asset_level smallint;
  v_quantity integer;

  v_config public.infrastructure_asset_config%rowtype;
  v_required_amount bigint;
  v_current_balance numeric := 0;
  v_shortfall numeric := 0;

  v_job public.club_infrastructure_jobs%rowtype;
  v_error_text text;
begin
  if p_club_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'MISSING_CLUB_ID',
      'title', 'Club not found',
      'message', 'The asset delivery could not be started because the club could not be resolved.'
    );
  end if;

  v_asset_key := lower(trim(coalesce(p_asset_key, '')));

  if v_asset_key = '' then
    return jsonb_build_object(
      'ok', false,
      'code', 'MISSING_ASSET_KEY',
      'title', 'Asset not selected',
      'message', 'Please select an asset before starting delivery.'
    );
  end if;

  if v_asset_key = 'team_car_fleet' then
    v_asset_key := 'team_car';
  end if;

  if p_asset_level is null or p_asset_level < 1 or p_asset_level > 32767 then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_ASSET_LEVEL',
      'title', 'Invalid asset level',
      'message', 'The selected asset level is invalid.'
    );
  end if;

  if p_quantity is null or p_quantity < 1 then
    return jsonb_build_object(
      'ok', false,
      'code', 'INVALID_QUANTITY',
      'title', 'Invalid quantity',
      'message', 'The selected asset quantity is invalid.'
    );
  end if;

  v_asset_level := p_asset_level::smallint;
  v_quantity := p_quantity;

  v_finance_club_id := public.finance_resolve_paying_club_id(p_club_id);

  if v_finance_club_id is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'CLUB_NOT_FOUND',
      'title', 'Club not found',
      'message', 'The asset delivery could not be started because the paying club could not be resolved.'
    );
  end if;

  select *
  into v_config
  from public.infrastructure_asset_config
  where asset_key = v_asset_key
    and asset_level = v_asset_level
  limit 1;

  if v_config.asset_key is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'ASSET_CONFIG_MISSING',
      'title', 'Asset configuration missing',
      'message', 'This asset level is not configured yet.',
      'asset_key', v_asset_key,
      'asset_level', v_asset_level
    );
  end if;

  v_required_amount := coalesce(v_config.cost_cash, 0)::bigint * v_quantity::bigint;

  select coalesce(cfs.current_balance, 0)
  into v_current_balance
  from public.club_finance_summary cfs
  where cfs.club_id = v_finance_club_id;

  v_current_balance := coalesce(v_current_balance, 0);
  v_shortfall := greatest(v_required_amount::numeric - v_current_balance, 0);

  /*
    Important:
    Optional asset purchases must be blocked when funds are insufficient.
    They must NOT trigger emergency loans.
  */
  if v_current_balance < v_required_amount then
    return jsonb_build_object(
      'ok', false,
      'code', 'INSUFFICIENT_FUNDS',
      'title', 'Not enough funds',
      'message',
        'Your club cannot acquire this asset because the purchase would exceed the available balance. Emergency loans are only used for mandatory obligations such as rider salaries, staff salaries, tax adjustments, and emergency loan repayments. Optional purchases, upgrades, transfers, staff courses, scouting, and training camps are blocked when funds are insufficient.',
      'club_id', v_finance_club_id,
      'asset_key', v_asset_key,
      'asset_level', v_asset_level,
      'asset_name', v_config.asset_name,
      'quantity', v_quantity,
      'unit_cost_cash', v_config.cost_cash,
      'required_amount', v_required_amount,
      'current_balance', v_current_balance,
      'shortfall', v_shortfall,
      'emergency_loan_available', false,
      'blocked_action', 'asset_acquisition'
    );
  end if;

  /*
    Only call the original delivery function after we have confirmed
    the club can afford the asset.
  */
  select *
  into v_job
  from public.start_club_asset_delivery_v2(
    v_finance_club_id,
    v_asset_key,
    v_asset_level,
    v_quantity
  );

  return jsonb_build_object(
    'ok', true,
    'job', to_jsonb(v_job),
    'club_id', v_finance_club_id,
    'asset_key', v_asset_key,
    'asset_level', v_asset_level,
    'asset_name', v_config.asset_name,
    'quantity', v_quantity,
    'required_amount', v_required_amount,
    'current_balance_before', v_current_balance
  );

exception
  when others then
    v_error_text := coalesce(sqlerrm, '');

    /*
      Re-check balance before calling it insufficient funds.
      This prevents false Not enough funds messages for rich clubs.
    */
    select coalesce(cfs.current_balance, 0)
    into v_current_balance
    from public.club_finance_summary cfs
    where cfs.club_id = coalesce(v_finance_club_id, p_club_id);

    v_current_balance := coalesce(v_current_balance, 0);

    if v_required_amount is not null
       and v_current_balance < v_required_amount then
      return jsonb_build_object(
        'ok', false,
        'code', 'INSUFFICIENT_FUNDS',
        'title', 'Not enough funds',
        'message',
          'Your club cannot acquire this asset because the purchase would exceed the available balance. Emergency loans are only used for mandatory obligations such as rider salaries, staff salaries, tax adjustments, and emergency loan repayments. Optional purchases, upgrades, transfers, staff courses, scouting, and training camps are blocked when funds are insufficient.',
        'club_id', coalesce(v_finance_club_id, p_club_id),
        'asset_key', v_asset_key,
        'asset_level', p_asset_level,
        'quantity', p_quantity,
        'required_amount', v_required_amount,
        'current_balance', v_current_balance,
        'shortfall', greatest(v_required_amount::numeric - v_current_balance, 0),
        'emergency_loan_available', false,
        'blocked_action', 'asset_acquisition',
        'technical_message', v_error_text
      );
    end if;

    return jsonb_build_object(
      'ok', false,
      'code', 'ASSET_DELIVERY_FAILED',
      'title', 'Could not start asset delivery',
      'message',
        'The asset delivery could not be started because an unexpected backend error occurred. Please try again.',
      'club_id', coalesce(v_finance_club_id, p_club_id),
      'asset_key', v_asset_key,
      'asset_level', p_asset_level,
      'quantity', p_quantity,
      'required_amount', v_required_amount,
      'current_balance', v_current_balance,
      'technical_message', v_error_text
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.debug_start_club_asset_delivery_v2_call(p_club_id uuid, p_asset_key text, p_asset_level integer DEFAULT 1, p_quantity integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_job public.club_infrastructure_jobs%rowtype;

  v_sqlstate text;
  v_message text;
  v_detail text;
  v_hint text;
  v_context text;
begin
  begin
    select *
    into v_job
    from public.start_club_asset_delivery_v2(
      p_club_id,
      p_asset_key,
      p_asset_level::smallint,
      p_quantity
    );

    raise exception 'DEBUG_ROLLBACK_SUCCESS';

  exception when others then
    get stacked diagnostics
      v_sqlstate = returned_sqlstate,
      v_message = message_text,
      v_detail = pg_exception_detail,
      v_hint = pg_exception_hint,
      v_context = pg_exception_context;

    if v_message = 'DEBUG_ROLLBACK_SUCCESS' then
      return jsonb_build_object(
        'ok', true,
        'would_succeed', true,
        'rolled_back', true,
        'message', 'Original delivery function would succeed. No job was created because this was a debug rollback.',
        'job_preview', to_jsonb(v_job)
      );
    end if;

    return jsonb_build_object(
      'ok', false,
      'would_succeed', false,
      'rolled_back', true,
      'sqlstate', v_sqlstate,
      'message', v_message,
      'detail', v_detail,
      'hint', v_hint,
      'context', v_context
    );
  end;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_create_liquidation_final_warning(p_club_id uuid, p_loan_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_club public.clubs%rowtype;
  v_state finance.club_insolvency_state%rowtype;
  v_balance numeric := 0;

  v_type_id public.notification_types.id%type;
  v_notification_id public.notifications.id%type;
  v_email_outbox_id bigint;

  v_subject text;
  v_body text;
  v_idempotency_key text;
begin
  select *
  into v_club
  from public.clubs
  where id = p_club_id;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'code', 'CLUB_NOT_FOUND'
    );
  end if;

  select *
  into v_state
  from finance.club_insolvency_state
  where club_id = p_club_id;

  select coalesce(current_balance, 0)
  into v_balance
  from public.club_finance_summary
  where club_id = p_club_id;

  if coalesce(v_state.emergency_rescue_count, 0) < 3 then
    return jsonb_build_object(
      'ok', true,
      'status', 'not_needed',
      'reason', 'club_has_not_used_all_rescues'
    );
  end if;

  select id
  into v_type_id
  from public.notification_types
  where code = 'FINANCE_LIQUIDATION_FINAL_WARNING'
    and is_active = true
  limit 1;

  if v_type_id is null then
    raise exception 'Missing or inactive notification type FINANCE_LIQUIDATION_FINAL_WARNING';
  end if;

  v_idempotency_key :=
    'liquidation_final_warning:' || p_club_id::text || ':rescue_count_3';

  v_subject :=
    'Final emergency rescue used — your club is at liquidation risk';

  v_body :=
    'Your club "' || coalesce(v_club.name, 'Unknown club') || '" has now used all 3 lifetime emergency rescues.' || chr(10) || chr(10) ||
    'Emergency loans are no longer available for this club.' || chr(10) ||
    'If the club cannot pay another mandatory obligation, such as rider salaries, staff salaries, tax adjustments, or emergency loan repayments, the club will be liquidated.' || chr(10) || chr(10) ||
    'Current balance: $' || coalesce(round(v_balance)::text, '0') || chr(10) ||
    'Rescues used: 3 / 3' || chr(10) || chr(10) ||
    'Optional purchases, upgrades, transfers, staff courses, scouting, and training camps will continue to be blocked when funds are insufficient.';

  insert into public.notifications (
    type_id,
    title,
    message,
    source,
    created_by_user_id,
    action_url,
    payload_json,
    expires_at,
    created_at
  )
  select
    v_type_id,
    'Final emergency rescue used',
    'Your club has used all 3 lifetime emergency rescues. If it cannot pay another mandatory obligation, it will be liquidated.',
    'game',
    null,
    '/dashboard/finance',
    jsonb_build_object(
      'club_id', p_club_id,
      'club_name', v_club.name,
      'loan_id', p_loan_id,
      'current_balance', v_balance,
      'rescues_used_lifetime', 3,
      'max_lifetime_rescues', 3,
      'liquidation_rule', 'After 3 lifetime emergency rescues, the next unpaid mandatory obligation liquidates the club.'
    ),
    null,
    now()
  where not exists (
    select 1
    from public.notifications n
    where n.type_id = v_type_id
      and n.payload_json ->> 'club_id' = p_club_id::text
      and n.payload_json ->> 'rescues_used_lifetime' = '3'
  )
  returning id
  into v_notification_id;

  if v_notification_id is not null and v_club.owner_user_id is not null then
    insert into public.user_notifications (
      user_id,
      notification_id,
      status,
      read_at,
      deleted_at,
      created_at
    )
    values (
      v_club.owner_user_id,
      v_notification_id,
      'unread',
      null,
      null,
      now()
    )
    on conflict do nothing;
  end if;

  if v_club.owner_user_id is not null then
    insert into public.email_outbox (
      user_id,
      club_id,
      email_type,
      subject,
      body_text,
      payload_json,
      idempotency_key,
      status
    )
    values (
      v_club.owner_user_id,
      p_club_id,
      'FINANCE_LIQUIDATION_FINAL_WARNING',
      v_subject,
      v_body,
      jsonb_build_object(
        'club_id', p_club_id,
        'club_name', v_club.name,
        'loan_id', p_loan_id,
        'current_balance', v_balance,
        'rescues_used_lifetime', 3,
        'max_lifetime_rescues', 3
      ),
      v_idempotency_key,
      'pending'
    )
    on conflict (idempotency_key) do nothing
    returning id
    into v_email_outbox_id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'status', 'created_or_already_exists',
    'club_id', p_club_id,
    'notification_id', v_notification_id,
    'email_outbox_id', v_email_outbox_id
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.email_outbox_claim_pending(p_limit integer DEFAULT 10)
 RETURNS SETOF email_outbox
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  return query
  update public.email_outbox eo
  set
    status = 'sending',
    attempts = eo.attempts + 1
  where eo.id in (
    select id
    from public.email_outbox
    where status = 'pending'
      and attempts < 5
    order by created_at asc
    limit greatest(p_limit, 1)
    for update skip locked
  )
  returning eo.*;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.assert_club_active(p_club_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_club_id is null then
    raise exception 'CLUB_NOT_FOUND: club id is required';
  end if;

  if public.is_club_liquidated(p_club_id) then
    raise exception
      'CLUB_LIQUIDATED: This club has been liquidated and can no longer perform game actions.';
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_club_access_status(p_club_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid;
  v_row record;
  v_is_liquidated boolean;
begin
  v_uid := auth.uid();

  if v_uid is null then
    return jsonb_build_object(
      'ok', false,
      'code', 'NOT_AUTHENTICATED',
      'can_play', false,
      'message', 'Not authenticated'
    );
  end if;

  select
    c.id,
    c.name,
    c.deleted_at,
    c.owner_user_id,
    cis.status as insolvency_status,
    cis.emergency_rescue_count,
    cis.liquidated_at,
    cis.liquidation_reason
  into v_row
  from public.clubs c
  left join finance.club_insolvency_state cis
    on cis.club_id = c.id
  left join public.club_memberships cm
    on cm.club_id = c.id
   and cm.user_id = v_uid
  where c.id = p_club_id
    and (
      c.owner_user_id = v_uid
      or cm.user_id is not null
    )
  limit 1;

  if not found then
    return jsonb_build_object(
      'ok', false,
      'code', 'CLUB_NOT_FOUND_OR_FORBIDDEN',
      'can_play', false,
      'message', 'Club not found or access denied'
    );
  end if;

  v_is_liquidated :=
    v_row.deleted_at is not null
    or coalesce(v_row.insolvency_status, 'active') = 'liquidated'
    or v_row.liquidated_at is not null;

  return jsonb_build_object(
    'ok', true,
    'club_id', v_row.id,
    'club_name', v_row.name,
    'can_play', not v_is_liquidated,
    'is_liquidated', v_is_liquidated,
    'deleted_at', v_row.deleted_at,
    'insolvency_status', coalesce(v_row.insolvency_status, 'active'),
    'emergency_rescue_count', coalesce(v_row.emergency_rescue_count, 0),
    'liquidated_at', v_row.liquidated_at,
    'liquidation_reason', v_row.liquidation_reason,
    'message',
      case
        when v_is_liquidated then
          'This club has been liquidated and can no longer perform game actions.'
        else
          'Club is active.'
      end
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_cleanup_liquidated_club(p_club_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_released_riders integer := 0;
  v_deleted_staff integer := 0;
  v_cancelled_jobs integer := 0;
begin
  -- Release riders.
  -- IMPORTANT: adjust status value if your release system uses a different one.
  update public.rider_contracts rc
  set
    status = 'released',
    ended_at = now()
  where rc.club_id = p_club_id
    and rc.status = 'active';

  get diagnostics v_released_riders = row_count;

  -- Delete staff.
  delete from public.club_staff cs
  where cs.club_id = p_club_id;

  get diagnostics v_deleted_staff = row_count;

  -- Cancel pending infrastructure jobs.
  update public.club_infrastructure_jobs j
  set
    status = 'cancelled',
    completed_at = now(),
    metadata = coalesce(j.metadata, '{}'::jsonb) || jsonb_build_object(
      'cancelled_reason', 'club_liquidated',
      'cancelled_at', now()
    )
  where j.club_id = p_club_id
    and j.status = 'pending';

  get diagnostics v_cancelled_jobs = row_count;

  return jsonb_build_object(
    'ok', true,
    'club_id', p_club_id,
    'released_riders', v_released_riders,
    'deleted_staff', v_deleted_staff,
    'cancelled_jobs', v_cancelled_jobs
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.detach_my_liquidated_club(p_club_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid;
  v_deleted_memberships integer := 0;
begin
  v_uid := auth.uid();

  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  if not exists (
    select 1
    from public.clubs c
    where c.id = p_club_id
      and c.owner_user_id = v_uid
      and c.deleted_at is not null
  ) then
    raise exception 'This club is not a liquidated club owned by the current user';
  end if;

  delete from public.club_memberships cm
  where cm.club_id = p_club_id
    and cm.user_id = v_uid;

  get diagnostics v_deleted_memberships = row_count;

  return jsonb_build_object(
    'ok', true,
    'club_id', p_club_id,
    'deleted_memberships', v_deleted_memberships,
    'message', 'Liquidated club detached from current user session.'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.quote_infrastructure_asset_repair(p_asset_key text, p_asset_id uuid)
 RETURNS TABLE(asset_key text, asset_id uuid, club_id uuid, display_name text, asset_level smallint, status text, assignment_locked boolean, condition_percent numeric, missing_condition numeric, repair_cost_cash bigint, duration_game_days integer, can_repair boolean, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid;
  v_key text;
  v_asset record;
  v_cfg record;
  v_missing numeric;
  v_cost bigint;
  v_duration integer;
  v_can boolean;
  v_reason text;
begin
  v_uid := auth.uid();
  v_key := lower(trim(coalesce(p_asset_key, '')));

  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  if v_key = 'team_car_fleet' then
    v_key := 'team_car';
  end if;

  if v_key not in (
    'team_car',
    'team_bus',
    'equipment_van',
    'mobile_workshop',
    'medical_van'
  ) then
    raise exception 'Unsupported repair asset key: %', p_asset_key;
  end if;

  select *
  into v_asset
  from (
    select
      'team_car'::text as asset_key,
      tc.id as asset_id,
      tc.club_id,
      tc.display_name,
      tc.asset_level,
      tc.status,
      tc.assignment_locked,
      tc.condition_percent
    from public.club_team_cars tc
    where v_key = 'team_car'
      and tc.id = p_asset_id

    union all

    select
      'team_bus'::text as asset_key,
      tb.id as asset_id,
      tb.club_id,
      tb.display_name,
      tb.asset_level,
      tb.status,
      tb.assignment_locked,
      tb.condition_percent
    from public.club_team_buses tb
    where v_key = 'team_bus'
      and tb.id = p_asset_id

    union all

    select
      'equipment_van'::text as asset_key,
      ev.id as asset_id,
      ev.club_id,
      ev.display_name,
      ev.asset_level,
      ev.status,
      ev.assignment_locked,
      ev.condition_percent
    from public.club_equipment_vans ev
    where v_key = 'equipment_van'
      and ev.id = p_asset_id

    union all

    select
      'mobile_workshop'::text as asset_key,
      mw.id as asset_id,
      mw.club_id,
      mw.display_name,
      mw.asset_level,
      mw.status,
      mw.assignment_locked,
      mw.condition_percent
    from public.club_mobile_workshops mw
    where v_key = 'mobile_workshop'
      and mw.id = p_asset_id

    union all

    select
      'medical_van'::text as asset_key,
      mv.id as asset_id,
      mv.club_id,
      mv.display_name,
      mv.asset_level,
      mv.status,
      mv.assignment_locked,
      mv.condition_percent
    from public.club_medical_vans mv
    where v_key = 'medical_van'
      and mv.id = p_asset_id
  ) asset_row
  limit 1;

  if not found then
    raise exception 'Asset not found: % %', v_key, p_asset_id;
  end if;

  if not exists (
    select 1
    from public.clubs c
    left join public.club_memberships cm
      on cm.club_id = c.id
     and cm.user_id = v_uid
    where c.id = v_asset.club_id
      and (
        c.owner_user_id = v_uid
        or cm.user_id is not null
      )
  ) then
    raise exception 'Not allowed to repair this asset';
  end if;

  select *
  into v_cfg
  from public.infrastructure_asset_config cfg
  where cfg.asset_key = v_key
    and cfg.asset_level = v_asset.asset_level;

  if not found then
    raise exception 'Missing asset config for %, level %', v_key, v_asset.asset_level;
  end if;

  v_missing := round(greatest(100 - coalesce(v_asset.condition_percent, 0), 0), 2);
  v_cost := ceil(v_missing * coalesce(v_cfg.repair_cost_per_condition_point, 0))::bigint;

  v_duration :=
    case
      when v_missing <= 0 then 0
      else greatest(
        1,
        ceil(v_missing / greatest(coalesce(v_cfg.repair_points_per_game_day, 1), 1))::integer
      )
    end;

  v_can := true;
  v_reason := 'Repair quote available.';

  if v_asset.status <> 'available' then
    v_can := false;
    v_reason := 'Only available assets can be repaired.';
  elsif coalesce(v_asset.assignment_locked, false) then
    v_can := false;
    v_reason := 'Asset is locked to an active race or tour.';
  elsif v_missing <= 0 then
    v_can := false;
    v_reason := 'Asset condition is already 100%.';
  elsif exists (
    select 1
    from public.club_infrastructure_asset_repair_jobs rj
    where rj.asset_key = v_key
      and rj.asset_id = p_asset_id
      and rj.status = 'pending'
  ) then
    v_can := false;
    v_reason := 'A repair job is already pending for this asset.';
  end if;

  return query
  select
    v_key::text,
    p_asset_id,
    v_asset.club_id::uuid,
    v_asset.display_name::text,
    v_asset.asset_level::smallint,
    v_asset.status::text,
    v_asset.assignment_locked::boolean,
    v_asset.condition_percent::numeric,
    v_missing::numeric,
    v_cost::bigint,
    v_duration::integer,
    v_can::boolean,
    v_reason::text;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.quote_infrastructure_asset_sale(p_asset_key text, p_asset_id uuid)
 RETURNS TABLE(asset_key text, asset_id uuid, club_id uuid, display_name text, asset_level smallint, status text, assignment_locked boolean, purchase_cost_cash bigint, condition_percent numeric, sale_value_cash bigint, can_sell boolean, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid;
  v_key text;
  v_asset record;
  v_sale_value bigint;
  v_min_value bigint;
  v_can boolean;
  v_reason text;
begin
  v_uid := auth.uid();
  v_key := lower(trim(coalesce(p_asset_key, '')));

  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  if v_key = 'team_car_fleet' then
    v_key := 'team_car';
  end if;

  if v_key not in (
    'team_car',
    'team_bus',
    'equipment_van',
    'mobile_workshop',
    'medical_van'
  ) then
    raise exception 'Unsupported sale asset key: %', p_asset_key;
  end if;

  select *
  into v_asset
  from (
    select
      'team_car'::text as asset_key,
      tc.id as asset_id,
      tc.club_id,
      tc.display_name,
      tc.asset_level,
      tc.status,
      tc.assignment_locked,
      tc.purchase_cost_cash,
      tc.condition_percent
    from public.club_team_cars tc
    where v_key = 'team_car'
      and tc.id = p_asset_id

    union all

    select
      'team_bus'::text as asset_key,
      tb.id as asset_id,
      tb.club_id,
      tb.display_name,
      tb.asset_level,
      tb.status,
      tb.assignment_locked,
      tb.purchase_cost_cash,
      tb.condition_percent
    from public.club_team_buses tb
    where v_key = 'team_bus'
      and tb.id = p_asset_id

    union all

    select
      'equipment_van'::text as asset_key,
      ev.id as asset_id,
      ev.club_id,
      ev.display_name,
      ev.asset_level,
      ev.status,
      ev.assignment_locked,
      ev.purchase_cost_cash,
      ev.condition_percent
    from public.club_equipment_vans ev
    where v_key = 'equipment_van'
      and ev.id = p_asset_id

    union all

    select
      'mobile_workshop'::text as asset_key,
      mw.id as asset_id,
      mw.club_id,
      mw.display_name,
      mw.asset_level,
      mw.status,
      mw.assignment_locked,
      mw.purchase_cost_cash,
      mw.condition_percent
    from public.club_mobile_workshops mw
    where v_key = 'mobile_workshop'
      and mw.id = p_asset_id

    union all

    select
      'medical_van'::text as asset_key,
      mv.id as asset_id,
      mv.club_id,
      mv.display_name,
      mv.asset_level,
      mv.status,
      mv.assignment_locked,
      mv.purchase_cost_cash,
      mv.condition_percent
    from public.club_medical_vans mv
    where v_key = 'medical_van'
      and mv.id = p_asset_id
  ) asset_row
  limit 1;

  if not found then
    raise exception 'Asset not found: % %', v_key, p_asset_id;
  end if;

  if not exists (
    select 1
    from public.clubs c
    left join public.club_memberships cm
      on cm.club_id = c.id
     and cm.user_id = v_uid
    where c.id = v_asset.club_id
      and (
        c.owner_user_id = v_uid
        or cm.user_id is not null
      )
  ) then
    raise exception 'Not allowed to sell this asset';
  end if;

  v_min_value := round(coalesce(v_asset.purchase_cost_cash, 0) * 0.20)::bigint;

  v_sale_value := greatest(
    v_min_value,
    round(
      coalesce(v_asset.purchase_cost_cash, 0)
      * 0.60
      * (coalesce(v_asset.condition_percent, 0) / 100.0)
    )::bigint
  );

  v_can := true;
  v_reason := 'Sale quote available.';

  if v_asset.status = 'sold' then
    v_can := false;
    v_reason := 'Asset is already sold.';
  elsif v_asset.status = 'assigned' then
    v_can := false;
    v_reason := 'Asset is assigned to an active race or tour.';
  elsif v_asset.status = 'in_repair' then
    v_can := false;
    v_reason := 'Asset is currently in repair.';
  elsif coalesce(v_asset.assignment_locked, false) then
    v_can := false;
    v_reason := 'Asset is locked to an active race or tour.';
  end if;

  return query
  select
    v_key::text,
    p_asset_id,
    v_asset.club_id::uuid,
    v_asset.display_name::text,
    v_asset.asset_level::smallint,
    v_asset.status::text,
    v_asset.assignment_locked::boolean,
    v_asset.purchase_cost_cash::bigint,
    v_asset.condition_percent::numeric,
    v_sale_value::bigint,
    v_can::boolean,
    v_reason::text;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.start_infrastructure_asset_repair(p_asset_key text, p_asset_id uuid)
 RETURNS club_infrastructure_asset_repair_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_quote record;
  v_current_game_date date;
  v_job public.club_infrastructure_asset_repair_jobs%rowtype;
  v_tx_id uuid;
begin
  select *
  into v_quote
  from public.quote_infrastructure_asset_repair(p_asset_key, p_asset_id);

  if not coalesce(v_quote.can_repair, false) then
    raise exception '%', v_quote.reason;
  end if;

  v_current_game_date := public.get_current_game_date_date();

  if v_current_game_date is null then
    raise exception 'start_infrastructure_asset_repair: could not resolve current game date';
  end if;

  insert into public.club_infrastructure_asset_repair_jobs (
    club_id,
    asset_key,
    asset_id,
    status,
    condition_before,
    condition_target,
    repair_points,
    cost_cash,
    duration_game_days,
    started_game_date,
    complete_game_date,
    finance_transaction_id,
    created_by_user_id,
    metadata
  )
  values (
    v_quote.club_id,
    v_quote.asset_key,
    v_quote.asset_id,
    'pending',
    v_quote.condition_percent,
    100,
    v_quote.missing_condition,
    v_quote.repair_cost_cash,
    v_quote.duration_game_days,
    v_current_game_date,
    v_current_game_date + v_quote.duration_game_days,
    null,
    auth.uid(),
    jsonb_build_object(
      'asset_key', v_quote.asset_key,
      'asset_id', v_quote.asset_id,
      'display_name', v_quote.display_name,
      'asset_level', v_quote.asset_level,
      'condition_before', v_quote.condition_percent,
      'condition_target', 100,
      'missing_condition', v_quote.missing_condition,
      'cost_cash', v_quote.repair_cost_cash,
      'duration_game_days', v_quote.duration_game_days
    )
  )
  returning * into v_job;

  perform set_config('finance.internal', '1', true);

  v_tx_id := public.finance_spend_from_club(
    p_club_id := v_quote.club_id,
    p_amount := v_quote.repair_cost_cash,
    p_type := 'infrastructure_asset_repair',
    p_sink_code := 'SINK',
    p_idempotency_key := 'asset_repair:' || v_job.id::text,
    p_metadata := jsonb_build_object(
      'repair_job_id', v_job.id,
      'asset_key', v_quote.asset_key,
      'asset_id', v_quote.asset_id,
      'display_name', v_quote.display_name,
      'asset_level', v_quote.asset_level,
      'condition_before', v_quote.condition_percent,
      'condition_target', 100,
      'missing_condition', v_quote.missing_condition,
      'cost_cash', v_quote.repair_cost_cash,
      'duration_game_days', v_quote.duration_game_days
    )
  );

  update public.club_infrastructure_asset_repair_jobs
  set finance_transaction_id = v_tx_id
  where id = v_job.id
  returning * into v_job;

  if v_quote.asset_key = 'team_car' then
    update public.club_team_cars
    set
      status = 'in_repair',
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'active_repair_job_id', v_job.id
      )
    where id = v_quote.asset_id;

  elsif v_quote.asset_key = 'team_bus' then
    update public.club_team_buses
    set
      status = 'in_repair',
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'active_repair_job_id', v_job.id
      )
    where id = v_quote.asset_id;

  elsif v_quote.asset_key = 'equipment_van' then
    update public.club_equipment_vans
    set
      status = 'in_repair',
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'active_repair_job_id', v_job.id
      )
    where id = v_quote.asset_id;

  elsif v_quote.asset_key = 'mobile_workshop' then
    update public.club_mobile_workshops
    set
      status = 'in_repair',
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'active_repair_job_id', v_job.id
      )
    where id = v_quote.asset_id;

  elsif v_quote.asset_key = 'medical_van' then
    update public.club_medical_vans
    set
      status = 'in_repair',
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'active_repair_job_id', v_job.id
      )
    where id = v_quote.asset_id;
  end if;

  return v_job;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sell_infrastructure_asset(p_asset_key text, p_asset_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_quote record;
  v_current_game_date date;
  v_tx_id uuid;
begin
  select *
  into v_quote
  from public.quote_infrastructure_asset_sale(p_asset_key, p_asset_id);

  if not coalesce(v_quote.can_sell, false) then
    raise exception '%', v_quote.reason;
  end if;

  v_current_game_date := public.get_current_game_date_date();

  if v_current_game_date is null then
    raise exception 'sell_infrastructure_asset: could not resolve current game date';
  end if;

  perform set_config('finance.internal', '1', true);

  v_tx_id := public.finance_credit_to_club(
    p_club_id := v_quote.club_id,
    p_amount := v_quote.sale_value_cash,
    p_type := 'infrastructure_asset_sale',
    p_source_code := 'SINK',
    p_idempotency_key := 'asset_sale:' || v_quote.asset_key || ':' || v_quote.asset_id::text,
    p_metadata := jsonb_build_object(
      'asset_key', v_quote.asset_key,
      'asset_id', v_quote.asset_id,
      'display_name', v_quote.display_name,
      'asset_level', v_quote.asset_level,
      'purchase_cost_cash', v_quote.purchase_cost_cash,
      'condition_percent', v_quote.condition_percent,
      'sale_value_cash', v_quote.sale_value_cash
    )
  );

  if v_quote.asset_key = 'team_car' then
    update public.club_team_cars
    set
      status = 'sold',
      sold_game_date = v_current_game_date,
      current_assignment_type = null,
      current_assignment_id = null,
      current_assignment_label = null,
      assignment_locked = false,
      assignment_start_game_date = null,
      assignment_end_game_date = null,
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'sold_transaction_id', v_tx_id,
        'sold_game_date', v_current_game_date,
        'sale_value_cash', v_quote.sale_value_cash
      )
    where id = v_quote.asset_id;

    update public.club_infrastructure
    set team_car_fleet_quantity = greatest(team_car_fleet_quantity - 1, 0)
    where club_id = v_quote.club_id;

  elsif v_quote.asset_key = 'team_bus' then
    update public.club_team_buses
    set
      status = 'sold',
      sold_game_date = v_current_game_date,
      current_assignment_type = null,
      current_assignment_id = null,
      current_assignment_label = null,
      assignment_locked = false,
      assignment_start_game_date = null,
      assignment_end_game_date = null,
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'sold_transaction_id', v_tx_id,
        'sold_game_date', v_current_game_date,
        'sale_value_cash', v_quote.sale_value_cash
      )
    where id = v_quote.asset_id;

    update public.club_infrastructure
    set team_bus_quantity = greatest(team_bus_quantity - 1, 0)
    where club_id = v_quote.club_id;

  elsif v_quote.asset_key = 'equipment_van' then
    update public.club_equipment_vans
    set
      status = 'sold',
      sold_game_date = v_current_game_date,
      current_assignment_type = null,
      current_assignment_id = null,
      current_assignment_label = null,
      assignment_locked = false,
      assignment_start_game_date = null,
      assignment_end_game_date = null,
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'sold_transaction_id', v_tx_id,
        'sold_game_date', v_current_game_date,
        'sale_value_cash', v_quote.sale_value_cash
      )
    where id = v_quote.asset_id;

    update public.club_infrastructure
    set equipment_van_quantity = greatest(equipment_van_quantity - 1, 0)
    where club_id = v_quote.club_id;

  elsif v_quote.asset_key = 'mobile_workshop' then
    update public.club_mobile_workshops
    set
      status = 'sold',
      sold_game_date = v_current_game_date,
      current_assignment_type = null,
      current_assignment_id = null,
      current_assignment_label = null,
      assignment_locked = false,
      assignment_start_game_date = null,
      assignment_end_game_date = null,
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'sold_transaction_id', v_tx_id,
        'sold_game_date', v_current_game_date,
        'sale_value_cash', v_quote.sale_value_cash
      )
    where id = v_quote.asset_id;

    update public.club_infrastructure
    set mobile_workshop_quantity = greatest(mobile_workshop_quantity - 1, 0)
    where club_id = v_quote.club_id;

  elsif v_quote.asset_key = 'medical_van' then
    update public.club_medical_vans
    set
      status = 'sold',
      sold_game_date = v_current_game_date,
      current_assignment_type = null,
      current_assignment_id = null,
      current_assignment_label = null,
      assignment_locked = false,
      assignment_start_game_date = null,
      assignment_end_game_date = null,
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'sold_transaction_id', v_tx_id,
        'sold_game_date', v_current_game_date,
        'sale_value_cash', v_quote.sale_value_cash
      )
    where id = v_quote.asset_id;

    update public.club_infrastructure
    set medical_van_quantity = greatest(medical_van_quantity - 1, 0)
    where club_id = v_quote.club_id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'asset_key', v_quote.asset_key,
    'asset_id', v_quote.asset_id,
    'display_name', v_quote.display_name,
    'sale_value_cash', v_quote.sale_value_cash,
    'finance_transaction_id', v_tx_id
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.process_due_infrastructure_asset_repairs()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_job public.club_infrastructure_asset_repair_jobs%rowtype;
  v_current_game_date date;
begin
  v_current_game_date := public.get_current_game_date_date();

  if v_current_game_date is null then
    raise exception 'process_due_infrastructure_asset_repairs: could not resolve current game date';
  end if;

  for v_job in
    select *
    from public.club_infrastructure_asset_repair_jobs
    where status = 'pending'
      and complete_game_date <= v_current_game_date
    order by complete_game_date asc, created_at asc
    for update skip locked
  loop
    if v_job.asset_key = 'team_car' then
      update public.club_team_cars
      set
        condition_percent = 100,
        status = 'available',
        metadata = coalesce(metadata, '{}'::jsonb) - 'active_repair_job_id'
      where id = v_job.asset_id;

    elsif v_job.asset_key = 'team_bus' then
      update public.club_team_buses
      set
        condition_percent = 100,
        status = 'available',
        metadata = coalesce(metadata, '{}'::jsonb) - 'active_repair_job_id'
      where id = v_job.asset_id;

    elsif v_job.asset_key = 'equipment_van' then
      update public.club_equipment_vans
      set
        condition_percent = 100,
        status = 'available',
        metadata = coalesce(metadata, '{}'::jsonb) - 'active_repair_job_id'
      where id = v_job.asset_id;

    elsif v_job.asset_key = 'mobile_workshop' then
      update public.club_mobile_workshops
      set
        condition_percent = 100,
        status = 'available',
        metadata = coalesce(metadata, '{}'::jsonb) - 'active_repair_job_id'
      where id = v_job.asset_id;

    elsif v_job.asset_key = 'medical_van' then
      update public.club_medical_vans
      set
        condition_percent = 100,
        status = 'available',
        metadata = coalesce(metadata, '{}'::jsonb) - 'active_repair_job_id'
      where id = v_job.asset_id;
    end if;

    update public.club_infrastructure_asset_repair_jobs
    set
      status = 'completed',
      completed_at = now()
    where id = v_job.id;
  end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_infrastructure_asset_notification_for_club(p_club_id uuid, p_type_code text, p_title text, p_message text, p_payload jsonb DEFAULT '{}'::jsonb, p_action_url text DEFAULT '/dashboard/infrastructure'::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_owner_user_id uuid;
  v_notification_id bigint;
begin
  if p_club_id is null then
    raise exception 'p_club_id is required';
  end if;

  select c.owner_user_id
  into v_owner_user_id
  from public.clubs c
  where c.id = p_club_id;

  if v_owner_user_id is null then
    return null;
  end if;

  v_notification_id := public.create_infrastructure_notification(
    p_user_id := v_owner_user_id,
    p_type_code := p_type_code,
    p_title := p_title,
    p_message := p_message,
    p_action_url := p_action_url,
    p_payload := coalesce(p_payload, '{}'::jsonb)
  );

  return v_notification_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_infrastructure_asset_delivery_ordered()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_asset_kind text;
  v_asset_name text;
  v_quantity integer;
  v_delivery_label text;
begin
  if new.job_type <> 'asset_delivery' then
    return new;
  end if;

  if new.status <> 'pending' then
    return new;
  end if;

  v_asset_kind := case new.target_key
    when 'team_car' then 'Team Car'
    when 'team_bus' then 'Team Bus'
    when 'equipment_van' then 'Equipment Van'
    when 'logistics_truck' then 'Logistics Truck'
    when 'mobile_workshop' then 'Mobile Workshop'
    when 'medical_van' then 'Medical Van'
    else initcap(replace(new.target_key, '_', ' '))
  end;

  v_asset_name := coalesce(
    new.metadata->>'asset_name',
    format('%s Lv %s', v_asset_kind, coalesce(new.asset_level::text, '?'))
  );

  v_quantity := coalesce(new.asset_quantity, 1);

  if new.complete_game_date is not null then
    v_delivery_label := format(
      'Season %s - %s',
      extract(year from new.complete_game_date)::int - 1999,
      to_char(new.complete_game_date, 'FMDD Mon')
    );
  else
    v_delivery_label := 'the planned delivery date';
  end if;

  perform public.create_infrastructure_asset_notification_for_club(
    p_club_id := new.club_id,
    p_type_code := 'INFRASTRUCTURE_ASSET_ORDERED',
    p_title := format('Asset ordered: %s x%s', v_asset_name, v_quantity),
    p_message := format(
      '%s x%s has been ordered. Delivery is planned for %s.',
      v_asset_name,
      v_quantity,
      v_delivery_label
    ),
    p_payload := jsonb_build_object(
      'job_id', new.id,
      'club_id', new.club_id,
      'job_type', new.job_type,
      'target_key', new.target_key,
      'asset_level', new.asset_level,
      'asset_quantity', new.asset_quantity,
      'cost_cash', new.cost_cash,
      'duration_game_days', new.duration_game_days,
      'started_game_date', new.started_game_date,
      'complete_game_date', new.complete_game_date,
      'finance_transaction_id', new.finance_transaction_id
    )
  );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.notify_infrastructure_asset_state_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_asset_kind text;
  v_asset_name text;
  v_condition numeric;
  v_old_condition numeric;
  v_repair_complete_text text;
  v_payload jsonb;
begin
  if tg_op <> 'UPDATE' then
    return new;
  end if;

  v_asset_kind := case new.asset_key
    when 'team_car' then 'Team Car'
    when 'team_bus' then 'Team Bus'
    when 'equipment_van' then 'Equipment Van'
    when 'logistics_truck' then 'Logistics Truck'
    when 'mobile_workshop' then 'Mobile Workshop'
    when 'medical_van' then 'Medical Van'
    else initcap(replace(new.asset_key, '_', ' '))
  end;

  v_asset_name := coalesce(
    new.metadata->>'asset_name',
    new.display_name,
    format('%s Lv %s', v_asset_kind, new.asset_level)
  );

  v_condition := coalesce(new.condition_percent, 0);
  v_old_condition := coalesce(old.condition_percent, 100);

  v_payload := jsonb_build_object(
    'asset_id', new.id,
    'club_id', new.club_id,
    'asset_key', new.asset_key,
    'asset_level', new.asset_level,
    'display_name', new.display_name,
    'asset_name', v_asset_name,
    'garage_slot', new.garage_slot,
    'condition_percent', new.condition_percent,
    'old_condition_percent', old.condition_percent,
    'status', new.status,
    'old_status', old.status
  );

  if new.status = 'in_repair'
     and old.status is distinct from new.status then

    v_repair_complete_text := coalesce(
      new.metadata->>'repair_complete_game_date',
      new.metadata->>'complete_game_date',
      new.metadata->>'repair_complete_at'
    );

    perform public.create_infrastructure_asset_notification_for_club(
      p_club_id := new.club_id,
      p_type_code := 'INFRASTRUCTURE_ASSET_REPAIR_STARTED',
      p_title := format('Repair started: %s', v_asset_name),
      p_message := case
        when v_repair_complete_text is not null then
          format(
            '%s repair has started. Current condition is %s%%. Expected completion: %s.',
            v_asset_name,
            round(v_condition, 1),
            v_repair_complete_text
          )
        else
          format(
            '%s repair has started. Current condition is %s%%.',
            v_asset_name,
            round(v_condition, 1)
          )
      end,
      p_payload := v_payload || jsonb_build_object(
        'repair_complete', v_repair_complete_text
      )
    );
  end if;

  if old.status = 'in_repair'
     and new.status = 'available'
     and v_condition >= 99.5 then

    perform public.create_infrastructure_asset_notification_for_club(
      p_club_id := new.club_id,
      p_type_code := 'INFRASTRUCTURE_ASSET_REPAIRED',
      p_title := format('Repair complete: %s', v_asset_name),
      p_message := format(
        '%s has been repaired and is available again at %s%% condition.',
        v_asset_name,
        round(v_condition, 1)
      ),
      p_payload := v_payload
    );
  end if;

  if new.status = 'sold'
     and old.status is distinct from new.status then

    perform public.create_infrastructure_asset_notification_for_club(
      p_club_id := new.club_id,
      p_type_code := 'INFRASTRUCTURE_ASSET_SOLD',
      p_title := format('Asset sold: %s', v_asset_name),
      p_message := format(
        '%s has been sold and removed from the active garage.',
        v_asset_name
      ),
      p_payload := v_payload || jsonb_build_object(
        'sold_game_date', new.sold_game_date,
        'sale_value_cash', new.metadata->>'sale_value_cash',
        'finance_transaction_id', new.metadata->>'finance_transaction_id'
      )
    );
  end if;

  /*
    Low condition warning.
    Fires only when crossing from >=30 to <30,
    and only if the asset is not already sold or in repair.
  */
  if new.status not in ('sold', 'in_repair')
     and v_old_condition >= 30
     and v_condition < 30 then

    perform public.create_infrastructure_asset_notification_for_club(
      p_club_id := new.club_id,
      p_type_code := 'INFRASTRUCTURE_ASSET_CONDITION_LOW',
      p_title := format('Low condition: %s', v_asset_name),
      p_message := format(
        '%s condition has dropped below 30%% and should be repaired before another race or tour.',
        v_asset_name
      ),
      p_payload := v_payload || jsonb_build_object(
        'threshold_percent', 30,
        'recommended_action', 'repair'
      )
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_club_equipment_van_roster(p_club_id uuid)
 RETURNS TABLE(van_id uuid, club_id uuid, garage_slot integer, display_name text, asset_level smallint, asset_name text, purchase_cost_cash bigint, support_value numeric, condition_percent numeric, condition_status text, condition_factor numeric, effective_support_value numeric, status text, total_race_days integer, total_distance_km numeric, last_used_game_date date, acquired_game_date date, current_assignment_type text, current_assignment_id uuid, current_assignment_label text, assignment_locked boolean, assignment_start_game_date date, assignment_end_game_date date, condition_loss_per_race_day numeric, repair_cost_per_condition_point integer, repair_points_per_game_day numeric, min_assign_condition_percent numeric, max_assigned_per_event integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid;
begin
  v_uid := coalesce(auth.uid(), nullif(current_setting('request.jwt.claim.sub',true),'')::uuid);
  if v_uid is null then raise exception 'Not authenticated'; end if;

  if not exists (
    select 1
    from public.clubs c
    left join public.club_memberships cm on cm.club_id=c.id and cm.user_id=v_uid
    where c.id=p_club_id and (c.owner_user_id=v_uid or cm.user_id is not null)
  ) then
    raise exception 'Not allowed to view equipment vans for this club';
  end if;

  return query
  select
    ev.id,
    ev.club_id,
    ev.garage_slot,
    ev.display_name,
    ev.asset_level,
    coalesce(cfg.asset_name, ev.metadata->>'asset_name', format('Equipment Van Lv %s',ev.asset_level))::text,
    ev.purchase_cost_cash,
    ev.support_value,
    ev.condition_percent,
    case
      when ev.condition_percent >= 90 then 'Excellent'
      when ev.condition_percent >= 75 then 'Good'
      when ev.condition_percent >= 60 then 'Worn'
      when ev.condition_percent >= 45 then 'Poor'
      when ev.condition_percent >= 30 then 'Critical'
      else 'Unsafe'
    end::text,
    public.equipment_van_condition_factor(ev.condition_percent),
    round(ev.support_value * public.equipment_van_condition_factor(ev.condition_percent),2),
    ev.status,
    ev.total_race_days,
    ev.total_distance_km,
    ev.last_used_game_date,
    ev.acquired_game_date,
    ev.current_assignment_type,
    ev.current_assignment_id,
    ev.current_assignment_label,
    ev.assignment_locked,
    ev.assignment_start_game_date,
    ev.assignment_end_game_date,
    coalesce(cfg.condition_loss_per_race_day,0)::numeric,
    coalesce(cfg.repair_cost_per_condition_point,0)::integer,
    coalesce(cfg.repair_points_per_game_day,1)::numeric,
    coalesce(cfg.min_assign_condition_percent,30)::numeric,
    coalesce(cfg.max_assigned_per_event,1)::integer
  from public.club_equipment_vans ev
  left join public.infrastructure_asset_config cfg
    on cfg.asset_key=ev.asset_key and cfg.asset_level=ev.asset_level
  where ev.club_id=p_club_id and ev.status<>'sold'
  order by ev.garage_slot asc, ev.created_at asc;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_club_equipment_van_garage_summary(p_club_id uuid)
 RETURNS TABLE(club_id uuid, total_vans integer, max_total_vans integer, available_vans integer, assigned_vans integer, in_repair_vans integer, pending_delivery_vans integer, best_available_support_score numeric, max_event_support_score numeric, best_available_support_ratio numeric, support_tier text, mechanical_time_loss_reduction_pct numeric, spare_bike_response_bonus_pct numeric, equipment_condition_loss_reduction_pct numeric, pre_stage_readiness_bonus_pct numeric, missing_spare_equipment_risk_reduction_pct numeric, max_assigned_per_event integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid;
  v_max_total integer := 3;
  v_max_assigned integer := 1;
  v_max_support numeric := 3;
  v_total integer := 0;
  v_available integer := 0;
  v_assigned integer := 0;
  v_in_repair integer := 0;
  v_pending integer := 0;
  v_best numeric := 0;
  v_ratio numeric := 0;
  v_best_mr numeric := 0;
  v_best_protection numeric := 0;
begin
  v_uid := coalesce(auth.uid(), nullif(current_setting('request.jwt.claim.sub',true),'')::uuid);
  if v_uid is null then raise exception 'Not authenticated'; end if;

  if not exists (
    select 1 from public.clubs c
    left join public.club_memberships cm on cm.club_id=c.id and cm.user_id=v_uid
    where c.id=p_club_id and (c.owner_user_id=v_uid or cm.user_id is not null)
  ) then
    raise exception 'Not allowed to view equipment van summary for this club';
  end if;

  select coalesce(max(cfg.max_total_quantity),3),
         coalesce(max(cfg.max_assigned_per_event),1),
         coalesce(max(cfg.support_value),3)
  into v_max_total,v_max_assigned,v_max_support
  from public.infrastructure_asset_config cfg
  where cfg.asset_key='equipment_van';

  select count(*) filter (where ev.status<>'sold'),
         count(*) filter (where ev.status='available'),
         count(*) filter (where ev.status='assigned'),
         count(*) filter (where ev.status='in_repair')
  into v_total,v_available,v_assigned,v_in_repair
  from public.club_equipment_vans ev
  where ev.club_id=p_club_id;

  select coalesce(sum(coalesce(j.asset_quantity,1)),0)::integer
  into v_pending
  from public.club_infrastructure_jobs j
  where j.club_id=p_club_id and j.job_type='asset_delivery'
    and j.target_key='equipment_van' and j.status='pending';

  select
    coalesce(round(ev.support_value * public.equipment_van_condition_factor(ev.condition_percent),2),0),
    coalesce(round(public.equipment_van_level_mechanical_reliability_v1(ev.asset_level)
      * public.equipment_van_condition_factor(ev.condition_percent),2),0),
    coalesce(round(public.equipment_van_level_equipment_protection_pct_v1(ev.asset_level)
      * public.equipment_van_condition_factor(ev.condition_percent),2),0)
  into v_best,v_best_mr,v_best_protection
  from public.club_equipment_vans ev
  where ev.club_id=p_club_id and ev.status='available'
  order by
    public.equipment_van_level_mechanical_reliability_v1(ev.asset_level)
      * public.equipment_van_condition_factor(ev.condition_percent) desc,
    ev.condition_percent desc,
    ev.id
  limit 1;

  v_best := coalesce(v_best,0);
  v_best_mr := coalesce(v_best_mr,0);
  v_best_protection := coalesce(v_best_protection,0);
  v_ratio := least(v_best_mr / 8.0,1);

  return query select
    p_club_id,
    v_total,v_max_total,v_available,v_assigned,v_in_repair,v_pending,
    round(v_best,2), round(v_max_support*v_max_assigned,2), round(v_ratio,4),
    case when v_best_mr<=0 then 'None'
         when v_best_mr<3 then 'Basic'
         when v_best_mr<7 then 'Solid'
         else 'Strong' end::text,
    round(v_best_mr,2),
    round(v_best_mr,2),
    round(v_best_protection,2),
    round(v_best_mr,2),
    round(v_best_protection,2),
    v_max_assigned;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_club_mobile_workshop_roster(p_club_id uuid)
 RETURNS TABLE(workshop_id uuid, club_id uuid, garage_slot integer, display_name text, asset_level smallint, asset_name text, purchase_cost_cash bigint, support_value numeric, condition_percent numeric, condition_status text, condition_factor numeric, effective_support_value numeric, status text, total_race_days integer, total_distance_km numeric, last_used_game_date date, acquired_game_date date, current_assignment_type text, current_assignment_id uuid, current_assignment_label text, assignment_locked boolean, assignment_start_game_date date, assignment_end_game_date date, condition_loss_per_race_day numeric, repair_cost_per_condition_point integer, repair_points_per_game_day numeric, min_assign_condition_percent numeric, max_assigned_per_event integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_uid uuid;
begin
  v_uid:=coalesce(auth.uid(),nullif(current_setting('request.jwt.claim.sub',true),'')::uuid);
  if v_uid is null then raise exception 'Not authenticated'; end if;
  if not exists (
    select 1 from public.clubs c
    left join public.club_memberships cm on cm.club_id=c.id and cm.user_id=v_uid
    where c.id=p_club_id and (c.owner_user_id=v_uid or cm.user_id is not null)
